const NODE_FLAG_CONST: u32 = 1 << 1;
const MAX_GENERIC_INTERFACE_EXCLUSION_CONSTITUENTS: usize = 16;

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub(super) struct CanonicalTypeQueryOptions {
    pub strict_builtin_iterator_return: bool,
    pub no_implicit_any: bool,
}

/// Preflights an annotation without claiming options or writing checker state.
/// Callers without a diagnostic channel must not admit recovery plans.
pub(super) fn preflight_type_annotation(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: Option<&CanonicalGlobalTypes>,
    options: CanonicalTypeQueryOptions,
    node: NodeRef,
    initializer_symbol: Option<SemanticSymbolId>,
) -> Result<ConstructorAnnotationProof, DeclaredTypeError> {
    let aliases = HashMap::new();
    let mut planner = TypeQueryPlanner::new(
        store,
        host,
        global_types.map(|globals| globals.array_type),
        global_types.map(CanonicalArrayTargets::from_global_types),
        options.strict_builtin_iterator_return,
        &aliases,
    );
    // Class validation needs complete reference and union plans on warm queries.
    planner.replay_cached_annotations = true;
    let methods = object_members::plan_enclosing_generic_interface_methods(store, host, node)
        .map_err(property_object_error)?;
    planner.plan_interface_method_dependencies(&methods, node)?;
    planner.plan_type_node(node)?;
    let mut references = Vec::new();
    let supported = planned_constructor_annotation_shape(
        store,
        host,
        &planner.plan,
        node,
        &mut HashSet::new(),
        &mut references,
    );
    if supported {
        for &reference in &references {
            let resolved = planner.resolve_uncached_type_reference_symbol(reference)?;
            let expected = planner.plan.references[&reference].symbol;
            if store.get_merged_symbol(resolved) != Some(expected) {
                return Err(type_node_unavailable(
                    TypeNodeUnavailable::InvalidCachedSymbol {
                        node: reference,
                        symbol: expected,
                    },
                ));
            }
        }
    }
    let plan = planner.finish();
    if !supported
        || !plan.recovered_missing_references.is_empty()
        || !plan.recovered_missing_reference_diagnostics.is_empty()
        || plan
            .references
            .values()
            .any(|reference| reference.arity != PlannedTypeReferenceArity::Valid)
        || plan
            .unique_symbols
            .values()
            .any(|symbol| symbol.diagnostic.is_some())
        || initializer_symbol.is_some_and(|symbol| {
            !planned_annotation_accepts_symbol(host, &plan, node, symbol, &mut HashSet::new())
        })
    {
        return Err(type_node_unavailable(
            TypeNodeUnavailable::UnsupportedSyntax {
                node,
                kind: preflight_node(store, host, node)?.kind,
            },
        ));
    }
    let bindings = references
        .into_iter()
        .map(|node| (node, plan.references[&node].symbol))
        .collect();
    let proof = ConstructorAnnotationProof {
        node,
        plan,
        bindings,
    };
    proof.cached_type(store, host, global_types)?;
    Ok(proof)
}

/// Keeps the checked source identities while the ordinary query publishes its types.
/// Parentheses, keywords, and null do not require their own node cache entries.
pub(super) struct ConstructorAnnotationProof {
    node: NodeRef,
    plan: TypeQueryPlan,
    bindings: BTreeMap<NodeRef, SemanticSymbolId>,
}

impl ConstructorAnnotationProof {
    pub(super) fn bindings(
        &self,
    ) -> impl ExactSizeIterator<Item = (NodeRef, SemanticSymbolId)> + '_ {
        self.bindings.iter().map(|(&node, &symbol)| (node, symbol))
    }

    pub(super) fn bindings_are_published(&self, store: &CanonicalTypeMapperStore) -> bool {
        self.bindings()
            .all(|(node, symbol)| store.constructor_annotation_binding(node) == Some(symbol))
    }

    pub(super) fn cached_type(
        &self,
        store: &CanonicalTypeMapperStore,
        host: &DeclaredTypeHost<'_>,
        global_types: Option<&CanonicalGlobalTypes>,
    ) -> Result<Option<TypeId>, DeclaredTypeError> {
        self.node_type(store, host, global_types, self.node, &mut HashSet::new())
    }

    #[allow(clippy::too_many_lines)] // Checks each admitted source shape against its own provider.
    fn node_type(
        &self,
        store: &CanonicalTypeMapperStore,
        host: &DeclaredTypeHost<'_>,
        global_types: Option<&CanonicalGlobalTypes>,
        node: NodeRef,
        active: &mut HashSet<NodeRef>,
    ) -> Result<Option<TypeId>, DeclaredTypeError> {
        let invalid = || type_node_unavailable(TypeNodeUnavailable::InvalidTypeReference(node));
        if !active.insert(node) {
            return Err(invalid());
        }
        let bootstrap = store.intrinsic_bootstrap().ok_or_else(&invalid)?;
        let expected = if let Some(reference) = self.plan.references.get(&node) {
            let cached_symbol = store
                .symbol_node_links(node)
                .and_then(|links| links.resolved_symbol);
            let published_type = store
                .type_node_links(node)
                .and_then(|links| links.resolved_type)
                .is_some();
            if (published_type || cached_symbol.is_some())
                && cached_symbol != Some(reference.symbol)
                || store
                    .constructor_annotation_binding(node)
                    .is_some_and(|binding| binding != reference.symbol)
            {
                return Err(invalid());
            }
            if let Some(alias) = self.plan.aliases.get(&reference.symbol) {
                let expected =
                    self.node_type(store, host, global_types, alias.type_node, active)?;
                if store
                    .type_alias_links(reference.symbol)
                    .is_some_and(|links| {
                        links.type_parameters.is_some()
                            || links.instantiations.is_some()
                            || links.is_constructor_declared_property
                            || links.declared_type.is_some() && links.declared_type != expected
                    })
                {
                    return Err(invalid());
                }
                expected
            } else {
                let symbol = store.symbol(reference.symbol).ok_or_else(&invalid)?;
                if preflight_class_or_interface_reference(
                    store,
                    host,
                    reference.symbol,
                    symbol.flags(),
                )? != 0
                {
                    return Err(invalid());
                }
                store
                    .declared_type_links(reference.symbol)
                    .and_then(|links| links.declared_type)
            }
        } else if let Some(union) = self.plan.unions.get(&node) {
            let mut constituents = Vec::with_capacity(union.types.len());
            let mut complete = true;
            for child in &union.types {
                if let Some(type_) = self.node_type(store, host, global_types, *child, active)? {
                    constituents.push(type_);
                } else {
                    complete = false;
                }
            }
            if complete
                && store
                    .type_node_links(node)
                    .and_then(|links| links.resolved_type)
                    .is_some()
            {
                store
                    .cached_literal_union_type_with_alias(
                        &constituents,
                        union.alias_symbol.map(|symbol| (symbol, &[][..])),
                        global_types.map(CanonicalArrayTargets::from_global_types),
                    )
                    .map_err(type_construction_error)?
            } else {
                None
            }
        } else if let Some(literal) = self.plan.literals.get(&node) {
            match literal {
                PlannedLiteralType::Null => Some(bootstrap.null_type),
                PlannedLiteralType::String(value) => bootstrap.cached_string_literal_type(value),
                PlannedLiteralType::Number { value, .. } => {
                    bootstrap.cached_number_literal_type(*value)
                }
                PlannedLiteralType::BigInt { value, .. } => {
                    bootstrap.cached_bigint_literal_type(value)
                }
                PlannedLiteralType::Boolean(value) => Some(if *value {
                    bootstrap.regular_true_type
                } else {
                    bootstrap.regular_false_type
                }),
            }
        } else {
            let record = preflight_node(store, host, node)?;
            if let NodeData::ParenthesizedTypeNode(parenthesized) = &record.data {
                self.node_type(
                    store,
                    host,
                    global_types,
                    NodeRef::new(node.arena, node.file, parenthesized.type_),
                    active,
                )?
            } else {
                Some(match record.kind {
                    SyntaxKind::AnyKeyword => bootstrap.any_type,
                    SyntaxKind::UnknownKeyword => bootstrap.unknown_type,
                    SyntaxKind::StringKeyword => bootstrap.string_type,
                    SyntaxKind::NumberKeyword => bootstrap.number_type,
                    SyntaxKind::BigIntKeyword => bootstrap.bigint_type,
                    SyntaxKind::BooleanKeyword => bootstrap.boolean_type,
                    SyntaxKind::SymbolKeyword => bootstrap.es_symbol_type,
                    SyntaxKind::VoidKeyword => bootstrap.void_type,
                    SyntaxKind::UndefinedKeyword => bootstrap.undefined_type,
                    SyntaxKind::NeverKeyword => bootstrap.never_type,
                    SyntaxKind::ObjectKeyword => bootstrap.non_primitive_type,
                    _ => return Err(invalid()),
                })
            }
        };
        if store.type_node_links(node).is_some_and(|links| {
            links != &TypeNodeLinks::default()
                && (links.outer_type_parameters.is_some()
                    || links.resolved_type.is_none()
                    || links.resolved_type != expected)
        }) || !self.plan.references.contains_key(&node)
            && store
                .symbol_node_links(node)
                .is_some_and(|links| links != &SymbolNodeLinks::default())
        {
            return Err(invalid());
        }
        active.remove(&node);
        let needs_node_cache = self.plan.references.contains_key(&node)
            || self.plan.unions.contains_key(&node)
            || self
                .plan
                .literals
                .get(&node)
                .is_some_and(|literal| !matches!(literal, PlannedLiteralType::Null));
        if needs_node_cache
            && store
                .type_node_links(node)
                .and_then(|links| links.resolved_type)
                .is_none()
        {
            return Ok(None);
        }
        Ok(expected)
    }
}

fn planned_constructor_annotation_shape(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &TypeQueryPlan,
    node: NodeRef,
    active: &mut HashSet<NodeRef>,
    references: &mut Vec<NodeRef>,
) -> bool {
    if !active.insert(node) {
        return false;
    }
    let result = if let Some(union) = plan.unions.get(&node) {
        union.types.iter().all(|node| {
            planned_constructor_annotation_shape(store, host, plan, *node, active, references)
        })
    } else if let Some(reference) = plan.references.get(&node) {
        references.push(node);
        reference.type_arguments.is_empty()
            && store.symbol(reference.symbol).is_some_and(|symbol| {
                if symbol.flags() == SymbolFlags::TYPE_ALIAS {
                    plan.aliases.get(&reference.symbol).is_some_and(|alias| {
                        alias.type_parameters.is_empty()
                            && planned_constructor_annotation_shape(
                                store,
                                host,
                                plan,
                                alias.type_node,
                                active,
                                references,
                            )
                    })
                } else {
                    symbol.flags() & SymbolFlags::TYPE == SymbolFlags::INTERFACE
                        && preflight_class_or_interface_reference(
                            store,
                            host,
                            reference.symbol,
                            symbol.flags(),
                        )
                        .ok()
                            == Some(0)
                }
            })
    } else {
        match host.node(node).map(|node| &node.data) {
            Some(NodeData::KeywordTypeNode(_)) => host.node(node).is_some_and(|node| {
                matches!(
                    node.kind,
                    SyntaxKind::AnyKeyword
                        | SyntaxKind::UnknownKeyword
                        | SyntaxKind::StringKeyword
                        | SyntaxKind::NumberKeyword
                        | SyntaxKind::BigIntKeyword
                        | SyntaxKind::BooleanKeyword
                        | SyntaxKind::SymbolKeyword
                        | SyntaxKind::VoidKeyword
                        | SyntaxKind::UndefinedKeyword
                        | SyntaxKind::NeverKeyword
                        | SyntaxKind::ObjectKeyword
                )
            }),
            Some(NodeData::LiteralTypeNode(_)) => true,
            Some(NodeData::ParenthesizedTypeNode(parenthesized)) => {
                planned_constructor_annotation_shape(
                    store,
                    host,
                    plan,
                    NodeRef::new(node.arena, node.file, parenthesized.type_),
                    active,
                    references,
                )
            }
            _ => false,
        }
    };
    active.remove(&node);
    result
}

// Exact declared identities and their union members need no relation writes.
// Other initializer relations remain unsupported at this preflight boundary.
fn planned_annotation_accepts_symbol(
    host: &DeclaredTypeHost<'_>,
    plan: &TypeQueryPlan,
    node: NodeRef,
    symbol: SemanticSymbolId,
    active: &mut HashSet<NodeRef>,
) -> bool {
    if !active.insert(node) {
        return false;
    }
    let result = if let Some(union) = plan.unions.get(&node) {
        union
            .types
            .iter()
            .any(|node| planned_annotation_accepts_symbol(host, plan, *node, symbol, active))
    } else if let Some(reference) = plan.references.get(&node) {
        reference.type_arguments.is_empty()
            && (reference.symbol == symbol
                || plan.aliases.get(&reference.symbol).is_some_and(|alias| {
                    alias.type_parameters.is_empty()
                        && planned_annotation_accepts_symbol(
                            host,
                            plan,
                            alias.type_node,
                            symbol,
                            active,
                        )
                }))
    } else {
        match host.node(node).map(|node| &node.data) {
            Some(NodeData::KeywordTypeNode(_)) => host.node(node).is_some_and(|node| {
                matches!(
                    node.kind,
                    SyntaxKind::AnyKeyword | SyntaxKind::UnknownKeyword
                )
            }),
            Some(NodeData::ParenthesizedTypeNode(parenthesized)) => {
                planned_annotation_accepts_symbol(
                    host,
                    plan,
                    NodeRef::new(node.arena, node.file, parenthesized.type_),
                    symbol,
                    active,
                )
            }
            _ => false,
        }
    };
    active.remove(&node);
    result
}

/// Immutable proof that one leaf in an exact importer annotation root names
/// one alias whose immediate and final type-only targets were independently
/// derived from the program's exact module-resolution manifest.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct CanonicalTypeReferenceAliasTarget {
    root: NodeRef,
    reference: NodeRef,
    binding_declaration: NodeRef,
    alias: SemanticSymbolId,
    immediate_target: SemanticSymbolId,
    target: SemanticSymbolId,
}

impl CanonicalTypeReferenceAliasTarget {
    #[cfg_attr(not(test), allow(dead_code))]
    pub(super) const fn new(
        root: NodeRef,
        reference: NodeRef,
        binding_declaration: NodeRef,
        alias: SemanticSymbolId,
        immediate_target: SemanticSymbolId,
        target: SemanticSymbolId,
    ) -> Self {
        Self {
            root,
            reference,
            binding_declaration,
            alias,
            immediate_target,
            target,
        }
    }
}

/// Immutable proof for one parser-owned `JSDoc` import and its `CommonJS` target.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct CanonicalJsDocImportTypeTarget {
    local_declaration: NodeRef,
    local_symbol: SemanticSymbolId,
    import_type: NodeRef,
    module_specifier: NodeRef,
    imported_name: NodeRef,
    module_symbol: SemanticSymbolId,
    target_symbol: SemanticSymbolId,
    target_declaration: NodeRef,
}

impl CanonicalJsDocImportTypeTarget {
    #[allow(clippy::too_many_arguments)]
    pub(super) const fn new(
        local_declaration: NodeRef,
        local_symbol: SemanticSymbolId,
        import_type: NodeRef,
        module_specifier: NodeRef,
        imported_name: NodeRef,
        module_symbol: SemanticSymbolId,
        target_symbol: SemanticSymbolId,
        target_declaration: NodeRef,
    ) -> Self {
        Self {
            local_declaration,
            local_symbol,
            import_type,
            module_specifier,
            imported_name,
            module_symbol,
            target_symbol,
            target_declaration,
        }
    }
}

fn validate_jsdoc_import_type_target(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    capability: CanonicalJsDocImportTypeTarget,
) -> Result<(), DeclaredTypeError> {
    let invalid = || {
        type_node_unavailable(TypeNodeUnavailable::InvalidJsDocImportTypeTarget {
            node: capability.import_type,
            alias: capability.local_symbol,
            target: capability.target_symbol,
        })
    };
    let local = store.symbol(capability.local_symbol).ok_or_else(&invalid)?;
    let local_declaration = authenticated_type_alias_declaration(
        store,
        host,
        capability.local_declaration,
        capability.local_symbol,
    )?
    .ok_or_else(&invalid)?;
    let local_bound = host
        .bound_file(capability.local_declaration)
        .ok_or_else(&invalid)?;
    let local_facts = local_bound.source_facts().ok_or_else(&invalid)?;
    let import_record = preflight_node(store, host, capability.import_type)?;
    let NodeData::ImportTypeNode(import) = &import_record.data else {
        return Err(invalid());
    };
    let argument = NodeRef::new(
        capability.import_type.arena,
        capability.import_type.file,
        import.argument,
    );
    let argument_record = preflight_node(store, host, argument)?;
    let NodeData::LiteralTypeNode(literal) = &argument_record.data else {
        return Err(invalid());
    };
    let specifier_record = preflight_node(store, host, capability.module_specifier)?;
    let NodeData::StringLiteral(specifier) = &specifier_record.data else {
        return Err(invalid());
    };
    let qualifier_record = preflight_node(store, host, capability.imported_name)?;
    let NodeData::Identifier(qualifier) = &qualifier_record.data else {
        return Err(invalid());
    };
    let target = store
        .symbol(capability.target_symbol)
        .ok_or_else(&invalid)?;
    let target_bound = host
        .bound_file(capability.target_declaration)
        .ok_or_else(&invalid)?;
    let target_facts = target_bound.source_facts().ok_or_else(&invalid)?;
    let target_declaration = authenticated_type_alias_declaration(
        store,
        host,
        capability.target_declaration,
        capability.target_symbol,
    )?
    .ok_or_else(&invalid)?;
    let module = store
        .symbol(capability.module_symbol)
        .ok_or_else(&invalid)?;
    let exports = module
        .exports()
        .and_then(|exports| store.symbol_table(exports))
        .ok_or_else(&invalid)?;
    let promoted = exports
        .get(InternalSymbolName::ExportEquals.as_ref())
        .ok_or_else(&invalid)?;
    let promoted_target = store
        .symbol(promoted)
        .and_then(ts_binder::semantic::Symbol::exports)
        .and_then(|exports| store.symbol_table(exports))
        .and_then(|exports| exports.get_source(&qualifier.text));

    if !local_facts.is_javascript_file()
        || local_facts.is_declaration_file()
        || local.flags() != SymbolFlags::TYPE_ALIAS
        || local.declarations() != Some(&[capability.local_declaration])
        || store.get_merged_symbol(capability.local_symbol) != Some(capability.local_symbol)
        || local_declaration.type_ != capability.import_type.node
        || !capability.import_type.is_for(
            capability.local_declaration.arena,
            capability.local_declaration.file,
        )
        || import_record.kind != SyntaxKind::ImportType
        || import_record.flags.0 != 0
        || import_record.parent != Some(capability.local_declaration.node)
        || import.attributes.is_some()
        || import.is_type_of
        || import.type_arguments.is_some()
        || import.qualifier != Some(capability.imported_name.node)
        || argument_record.kind != SyntaxKind::LiteralType
        || argument_record.flags.0 != 0
        || argument_record.parent != Some(capability.import_type.node)
        || literal.literal != capability.module_specifier.node
        || !capability
            .module_specifier
            .is_for(capability.import_type.arena, capability.import_type.file)
        || specifier_record.kind != SyntaxKind::StringLiteral
        || specifier_record.flags.0 != 0
        || specifier_record.parent != Some(argument.node)
        || specifier.token_flags.0 != 0
        || !capability
            .imported_name
            .is_for(capability.import_type.arena, capability.import_type.file)
        || qualifier_record.kind != SyntaxKind::Identifier
        || qualifier_record.flags.0 != 0
        || qualifier_record.parent != Some(capability.import_type.node)
        || qualifier.flow_node.is_some()
        || qualifier.text.is_empty()
        || target.flags() != SymbolFlags::TYPE_ALIAS
        || target.declarations() != Some(&[capability.target_declaration])
        || target.name().as_bytes() != qualifier.text.as_bytes()
        || target_declaration.type_parameters.is_some()
        || !target_facts.is_javascript_file()
        || !target_facts.is_common_js_module()
        || capability.target_declaration.file == capability.local_declaration.file
        || target_bound
            .symbol(target_bound.source_file())
            .and_then(|symbol| store.get_merged_symbol(symbol))
            != Some(capability.module_symbol)
        || store.get_parent_of_symbol(capability.target_symbol) != Some(capability.module_symbol)
        || store.get_merged_symbol(capability.target_symbol) != Some(capability.target_symbol)
        || exports.get_source(&qualifier.text) != Some(capability.target_symbol)
        || !super::alias::is_promoted_commonjs_export_alias(store, promoted)
        || promoted_target != Some(capability.target_symbol)
        || store
            .symbol_node_links(capability.import_type)
            .is_some_and(|links| links.resolved_symbol.is_some())
        || store
            .symbol_node_links(capability.imported_name)
            .and_then(|links| links.resolved_symbol)
            .is_some_and(|cached| cached != capability.target_symbol)
        || store
            .type_node_links(capability.import_type)
            .is_some_and(|links| links.outer_type_parameters.is_some())
        || store
            .type_alias_links(capability.local_symbol)
            .is_some_and(|links| {
                links.type_parameters.is_some()
                    || links.instantiations.is_some()
                    || links.is_constructor_declared_property
            })
    {
        return Err(invalid());
    }

    let target_type = store
        .type_alias_links(capability.target_symbol)
        .and_then(|links| links.declared_type);
    let local_type = store
        .type_alias_links(capability.local_symbol)
        .and_then(|links| links.declared_type);
    let imported_type = store
        .type_node_links(capability.import_type)
        .and_then(|links| links.resolved_type);
    if local_type.is_some_and(|cached| target_type != Some(cached))
        || imported_type.is_some_and(|cached| target_type != Some(cached))
        || local_type.is_some_and(|cached| {
            imported_type != Some(cached)
                || store
                    .symbol_node_links(capability.imported_name)
                    .and_then(|links| links.resolved_symbol)
                    != Some(capability.target_symbol)
        })
    {
        return Err(invalid());
    }
    Ok(())
}

fn authenticated_default_import_interface_return(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    capability: CanonicalTypeReferenceAliasTarget,
    target: SemanticSymbolId,
) -> bool {
    let Some(binding) = host.node(capability.binding_declaration) else {
        return false;
    };
    let NodeData::ImportClause(clause) = &binding.data else {
        return false;
    };
    let Some(name) = clause.name else {
        return false;
    };
    let name = NodeRef::new(
        capability.binding_declaration.arena,
        capability.binding_declaration.file,
        name,
    );
    let Some(name_record) = host.node(name) else {
        return false;
    };
    let NodeData::Identifier(identifier) = &name_record.data else {
        return false;
    };
    let Some(parent) = binding.parent else {
        return false;
    };
    let import = NodeRef::new(
        capability.binding_declaration.arena,
        capability.binding_declaration.file,
        parent,
    );
    let Some(import_record) = host.node(import) else {
        return false;
    };
    let NodeData::ImportDeclaration(declaration) = &import_record.data else {
        return false;
    };
    let Some(bound) = host.bound_file(capability.binding_declaration) else {
        return false;
    };
    let Some(root) = host.node(capability.root) else {
        return false;
    };
    let Some(root_parent) = root.parent else {
        return false;
    };
    let function = NodeRef::new(capability.root.arena, capability.root.file, root_parent);
    let Some(function_record) = host.node(function) else {
        return false;
    };
    let NodeData::FunctionDeclaration(function_data) = &function_record.data else {
        return false;
    };

    binding.kind == SyntaxKind::ImportClause
        && binding.flags.0 == 0
        && clause.phase_modifier.is_none()
        && clause.named_bindings.is_none()
        && clause.local_symbol.is_none()
        && clause.symbol.is_none()
        && clause.facts == 0
        && name_record.kind == SyntaxKind::Identifier
        && name_record.flags.0 == 0
        && name_record.parent == Some(capability.binding_declaration.node)
        && identifier.flow_node.is_none()
        && store
            .symbol(capability.alias)
            .and_then(|alias| alias.name().as_utf8())
            == Some(identifier.text.as_str())
        && bound
            .symbol(capability.binding_declaration)
            .and_then(|alias| store.get_merged_symbol(alias))
            == Some(capability.alias)
        && import_record.kind == SyntaxKind::ImportDeclaration
        && import_record.parent == Some(bound.source_file().node)
        && declaration.import_clause == Some(capability.binding_declaration.node)
        && function_record.kind == SyntaxKind::FunctionDeclaration
        && function_data.type_ == Some(capability.root.node)
        && store
            .symbol(target)
            .is_some_and(|target| target.flags() == SymbolFlags::INTERFACE)
        && store
            .alias_symbol_links(capability.alias)
            .is_some_and(|links| links.type_only_declaration.is_none())
}

impl From<CanonicalCheckerOptions> for CanonicalTypeQueryOptions {
    fn from(options: CanonicalCheckerOptions) -> Self {
        Self {
            strict_builtin_iterator_return: options.strict_builtin_iterator_return,
            no_implicit_any: options.no_implicit_any,
        }
    }
}

impl From<&CanonicalCheckerOptions> for CanonicalTypeQueryOptions {
    fn from(options: &CanonicalCheckerOptions) -> Self {
        (*options).into()
    }
}

