    fn assert_invalid_literal_query_is_atomic(fixture: &mut Fixture) {
        let alias = named_symbol(fixture, SyntaxKind::TypeAliasDeclaration, "Bad");
        let before = literal_state(&fixture.store);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        assert!(matches!(
            query_declared(
                fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidLiteralType(_)
            ))
        ));
        assert_eq!(literal_state(&fixture.store), before);
        assert!(fixture.store.type_alias_links(alias).is_none());
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn reparsed_javascript_typedef_aliases_preserve_declared_types_and_warm_caches() {
        for (module_state, assignment) in [
            (CanonicalModuleState::Script, ""),
            (CanonicalModuleState::CommonJs, "\nmodule.exports = value;"),
        ] {
            let source = format!(
                "{}{}",
                concat!(
                    "/** @typedef {number} Count */\n",
                    "/** @typedef {string | number} Scalar */\n",
                    "/** @typedef {{ value: 1 }} Shape */\n",
                    "const value = 1;",
                ),
                assignment
            );
            let mut fixture = javascript_typedef_fixture(&source, module_state, |_| {});
            let count = named_symbol(&fixture, SyntaxKind::JsTypeAliasDeclaration, "Count");
            let scalar = named_symbol(&fixture, SyntaxKind::JsTypeAliasDeclaration, "Scalar");
            let shape = named_symbol(&fixture, SyntaxKind::JsTypeAliasDeclaration, "Shape");
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let number = fixture.store.intrinsic_bootstrap().unwrap().number_type;
            assert_eq!(
                query_declared(
                    &mut fixture,
                    count,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(number)
            );

            let scalar_type = query_declared(
                &mut fixture,
                scalar,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let scalar_record = fixture.store.type_payload(scalar_type).unwrap();
            assert!(matches!(scalar_record.data(), TypeData::Union(_)));
            assert_eq!(
                scalar_record
                    .alias()
                    .and_then(|alias| fixture.store.type_alias(alias))
                    .and_then(TypeAlias::symbol),
                Some(scalar)
            );

            let shape_type = query_declared(
                &mut fixture,
                shape,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let shape_record = fixture.store.type_payload(shape_type).unwrap();
            let TypeData::Object(object) = shape_record.data() else {
                panic!("a reparsed structural typedef must retain its object members")
            };
            assert_eq!(
                shape_record.object_flags(),
                ObjectFlags::ANONYMOUS | ObjectFlags::MEMBERS_RESOLVED
            );
            assert_eq!(
                shape_record
                    .alias()
                    .and_then(|alias| fixture.store.type_alias(alias))
                    .and_then(TypeAlias::symbol),
                Some(shape)
            );
            let [property] = object.structured.properties.as_deref().unwrap() else {
                panic!("a reparsed structural typedef must retain one property")
            };
            assert_eq!(
                fixture.store.symbol(*property).unwrap().name().as_utf8(),
                Some("value")
            );
            assert!(
                fixture
                    .store
                    .value_symbol_links(*property)
                    .and_then(|links| links.resolved_type)
                    .is_some()
            );

            for (symbol, expected) in [(count, number), (scalar, scalar_type), (shape, shape_type)]
            {
                let warm = union_state(&fixture.store);
                assert_eq!(
                    query_declared(
                        &mut fixture,
                        symbol,
                        CanonicalTypeQueryOptions::default(),
                        &mut diagnostics,
                    ),
                    Ok(expected),
                    "cached JSDoc typedef {symbol:?} in {module_state:?}",
                );
                assert_eq!(union_state(&fixture.store), warm);
                let declaration = named_node(
                    &fixture,
                    SyntaxKind::JsTypeAliasDeclaration,
                    fixture
                        .store
                        .symbol(symbol)
                        .unwrap()
                        .name()
                        .as_utf8()
                        .unwrap(),
                );
                let NodeData::TypeAliasDeclaration(alias) =
                    &fixture.parsed.arena.get(declaration.node).unwrap().data
                else {
                    unreachable!()
                };
                let body = NodeRef::new(declaration.arena, declaration.file, alias.type_);
                assert_eq!(
                    query_node(&mut fixture, body, &mut diagnostics),
                    Ok(expected)
                );
                assert_eq!(union_state(&fixture.store), warm);
            }
            assert!(diagnostics.is_empty(), "{diagnostics:?}");
        }
    }

    #[test]
    fn commonjs_javascript_typedef_aliases_reject_forged_cached_property_types() {
        let mut fixture = javascript_typedef_fixture(
            concat!(
                "/** @typedef {{ value: 1 }} Shape */\n",
                "const value = 1;\n",
                "module.exports = value;",
            ),
            CanonicalModuleState::CommonJs,
            |_| {},
        );
        let symbol = named_symbol(&fixture, SyntaxKind::JsTypeAliasDeclaration, "Shape");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let type_ = query_declared(
            &mut fixture,
            symbol,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let property = fixture
            .store
            .type_payload(type_)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.properties.as_deref())
            .and_then(|properties| properties.first().copied())
            .unwrap();
        let original = fixture.store.value_symbol_links(property).unwrap().clone();
        let forged = fixture.store.intrinsic_bootstrap().unwrap().string_type;
        assert!(fixture.store.set_value_symbol_links(
            property,
            ValueSymbolLinks {
                resolved_type: Some(forged),
                ..ValueSymbolLinks::default()
            },
        ));
        let before = store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                symbol,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidCachedUnionType(type_),
            ))
        );
        assert_eq!(store_state(&fixture.store), before);

        assert!(fixture.store.set_value_symbol_links(property, original));
        let repaired = store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                symbol,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(type_)
        );
        assert_eq!(store_state(&fixture.store), repaired);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn javascript_typedef_aliases_reject_unreparsed_declarations_atomically() {
        let mut fixture = javascript_typedef_fixture(
            "/** @typedef {number} Value */\nconst value = 1;",
            CanonicalModuleState::Script,
            |parsed| {
                let declaration = parsed
                    .arena
                    .iter()
                    .find_map(|(node, record)| {
                        (record.kind == SyntaxKind::JsTypeAliasDeclaration).then_some(node)
                    })
                    .unwrap();
                parsed.arena.get_mut(declaration).unwrap().flags = NodeFlags::default();
            },
        );
        let declaration = named_node(&fixture, SyntaxKind::JsTypeAliasDeclaration, "Value");
        let symbol = named_symbol(&fixture, SyntaxKind::JsTypeAliasDeclaration, "Value");
        let before = store_state(&fixture.store);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        assert_eq!(
            query_declared(
                &mut fixture,
                symbol,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidTypeAliasDeclaration(declaration),
            ))
        );
        assert_eq!(store_state(&fixture.store), before);
        assert!(fixture.store.type_alias_links(symbol).is_none());
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn keyword_and_parenthesized_nodes_reuse_exact_bootstrap_identities() {
        let source = concat!(
            "type Any = any; type Unknown = unknown; type String = string; ",
            "type Number = number; type BigInt = bigint; type Boolean = boolean; ",
            "type Symbol = symbol; type Void = void; type Undefined = undefined; ",
            "type Null = null; type Never = never; type Object = object; ",
            "type Intrinsic = intrinsic; type Parenthesized = ((string));",
        );
        let mut fixture = fixture(source);
        let expected = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            [
                ("Any", bootstrap.any_type),
                ("Unknown", bootstrap.unknown_type),
                ("String", bootstrap.string_type),
                ("Number", bootstrap.number_type),
                ("BigInt", bootstrap.bigint_type),
                ("Boolean", bootstrap.boolean_type),
                ("Symbol", bootstrap.es_symbol_type),
                ("Void", bootstrap.void_type),
                ("Undefined", bootstrap.undefined_type),
                ("Null", bootstrap.null_type),
                ("Never", bootstrap.never_type),
                ("Object", bootstrap.non_primitive_type),
                ("Intrinsic", bootstrap.intrinsic_marker_type),
                ("Parenthesized", bootstrap.string_type),
            ]
        };
        let nodes = expected
            .iter()
            .map(|(name, expected)| (alias_parts(&fixture, name).2, *expected))
            .collect::<Vec<_>>();
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let mut query = CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        for (node, expected) in nodes {
            assert_eq!(query.get_type_from_type_node(node), Ok(expected));
        }
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // One identity matrix shares a single checker cache.
    fn non_null_literal_nodes_use_regular_interned_identities_and_exact_fresh_links() {
        let source = concat!(
            "type Single = 'shared'; type Template = `shared`; ",
            "type Thousand = 1_000; type ThousandAgain = 1000; ",
            "type Zero = 0; type NegativeZero = -0; ",
            "type PositiveBig = 123_456n; type PositiveBigAgain = 123456n; ",
            "type NegativeBig = -123_456n; type ZeroBig = 0n; type NegativeZeroBig = -0n; ",
            "type True = true; type False = false; type NullLiteral = null;",
        );
        let mut fixture = fixture(source);
        let names = [
            "Single",
            "Template",
            "Thousand",
            "ThousandAgain",
            "NegativeZero",
            "Zero",
            "NegativeBig",
            "PositiveBig",
            "PositiveBigAgain",
            "ZeroBig",
            "NegativeZeroBig",
            "True",
            "False",
            "NullLiteral",
        ];
        let nodes = names
            .iter()
            .map(|name| (*name, alias_parts(&fixture, name).2))
            .collect::<Vec<_>>();
        let (zero, zero_bigint, regular_true, regular_false, null) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (
                bootstrap.zero_type,
                bootstrap.zero_bigint_type,
                bootstrap.regular_true_type,
                bootstrap.regular_false_type,
                bootstrap.null_type,
            )
        };
        let before = literal_state(&fixture.store);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let mut resolved = BTreeMap::new();
        {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            let mut query = CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            for (name, node) in &nodes {
                resolved.insert(*name, query.get_type_from_type_node(*node).unwrap());
            }
        }

        assert_eq!(resolved["Single"], resolved["Template"]);
        assert_eq!(resolved["Thousand"], resolved["ThousandAgain"]);
        assert_eq!(resolved["Zero"], zero);
        assert_eq!(resolved["NegativeZero"], zero);
        assert_eq!(resolved["PositiveBig"], resolved["PositiveBigAgain"]);
        assert_ne!(resolved["PositiveBig"], resolved["NegativeBig"]);
        assert_eq!(resolved["ZeroBig"], zero_bigint);
        assert_eq!(resolved["NegativeZeroBig"], zero_bigint);
        assert_eq!(resolved["True"], regular_true);
        assert_eq!(resolved["False"], regular_false);
        assert_eq!(resolved["NullLiteral"], null);

        assert_regular_literal(
            &fixture.store,
            resolved["Single"],
            &LiteralValue::String("shared".into()),
        );
        assert_regular_literal(
            &fixture.store,
            resolved["Thousand"],
            &LiteralValue::Number(Number::new(1000.0)),
        );
        assert_regular_literal(
            &fixture.store,
            zero,
            &LiteralValue::Number(Number::new(0.0)),
        );
        assert_regular_literal(
            &fixture.store,
            resolved["PositiveBig"],
            &LiteralValue::BigInt(PseudoBigInt::parse_valid("123456n")),
        );
        assert_regular_literal(
            &fixture.store,
            resolved["NegativeBig"],
            &LiteralValue::BigInt(PseudoBigInt::parse_valid("-123456n")),
        );
        assert_regular_literal(
            &fixture.store,
            zero_bigint,
            &LiteralValue::BigInt(PseudoBigInt::default()),
        );

        let after = literal_state(&fixture.store);
        assert_eq!(after.0.0, before.0.0 + 10);
        assert_eq!(after.1, before.1 + 1);
        assert_eq!(after.2, before.2 + 1);
        assert_eq!(after.3, before.3 + 2);
        let null_node = alias_parts(&fixture, "NullLiteral").2;
        assert!(fixture.store.type_node_links(null_node).is_none());
        for (name, node) in &nodes {
            if *name != "NullLiteral" {
                assert_eq!(
                    fixture
                        .store
                        .type_node_links(*node)
                        .and_then(|links| links.resolved_type),
                    Some(resolved[*name])
                );
            }
        }

        {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            let mut query = CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            for (name, node) in &nodes {
                assert_eq!(query.get_type_from_type_node(*node), Ok(resolved[*name]));
            }
        }
        assert_eq!(literal_state(&fixture.store), after);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn unary_minus_evaluates_and_interns_the_positive_operand_before_the_result() {
        let mut bigint = fixture("type Negative = -42n;");
        let node = alias_parts(&bigint, "Negative").2;
        let symbol = named_symbol(&bigint, SyntaxKind::TypeAliasDeclaration, "Negative");
        let before = literal_state(&bigint.store);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let resolved = {
            let host = post_global_host(
                &bigint.parsed.arena,
                bigint.files.get(&bigint.file).unwrap(),
            );
            CanonicalTypeQuery::new(
                &mut bigint.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_declared_type_of_symbol(symbol)
            .unwrap()
        };
        let after = literal_state(&bigint.store);
        assert_eq!(after.0.0, before.0.0 + 4);
        assert_eq!(after.3, before.3 + 2);
        let positive = bigint
            .store
            .intrinsic_bootstrap()
            .unwrap()
            .cached_bigint_literal_type(&PseudoBigInt::parse_valid("42n"))
            .unwrap();
        let negative = bigint
            .store
            .intrinsic_bootstrap()
            .unwrap()
            .cached_bigint_literal_type(&PseudoBigInt::parse_valid("-42n"))
            .unwrap();
        assert_eq!(resolved, negative);
        assert_eq!(
            bigint
                .store
                .type_node_links(node)
                .and_then(|links| links.resolved_type),
            Some(negative)
        );
        assert_eq!(
            bigint
                .store
                .type_alias_links(symbol)
                .and_then(|links| links.declared_type),
            Some(negative)
        );
        assert_ne!(positive, negative);
        assert_regular_literal(
            &bigint.store,
            positive,
            &LiteralValue::BigInt(PseudoBigInt::parse_valid("42n")),
        );
        assert_regular_literal(
            &bigint.store,
            negative,
            &LiteralValue::BigInt(PseudoBigInt::parse_valid("-42n")),
        );
        assert!(diagnostics.is_empty());

        let mut negative_zero = fixture("type NegativeZero = -0;");
        let node = alias_parts(&negative_zero, "NegativeZero").2;
        let symbol = named_symbol(
            &negative_zero,
            SyntaxKind::TypeAliasDeclaration,
            "NegativeZero",
        );
        let zero = negative_zero.store.intrinsic_bootstrap().unwrap().zero_type;
        let before = literal_state(&negative_zero.store);
        let resolved = {
            let host = post_global_host(
                &negative_zero.parsed.arena,
                negative_zero.files.get(&negative_zero.file).unwrap(),
            );
            CanonicalTypeQuery::new(
                &mut negative_zero.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_declared_type_of_symbol(symbol)
            .unwrap()
        };
        let after = literal_state(&negative_zero.store);
        assert_eq!(resolved, zero);
        assert_eq!(
            negative_zero
                .store
                .type_node_links(node)
                .and_then(|links| links.resolved_type),
            Some(zero)
        );
        assert_eq!(after.0.0, before.0.0 + 1);
        assert_eq!(after.2, before.2);
        assert_regular_literal(
            &negative_zero.store,
            zero,
            &LiteralValue::Number(Number::new(0.0)),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn literal_spelling_variants_normalize_to_the_same_canonical_values() {
        let mut fixture = fixture(concat!(
            r#"type Escaped = "\x61"; type Plain = 'a'; type Template = `a`; "#,
            "type Hex = 0xff; type Decimal = 255; type Binary = 0b1010; type Ten = 10; ",
            "type Octal = 0o10; type Eight = 8; type Exponent = 1.5e2; type OneFifty = 150; ",
            "type HexBig = 0xffn; type DecimalBig = 255n; ",
            "type SeparatedBig = 1_000n; type ThousandBig = 1000n;",
        ));
        let names = [
            "Escaped",
            "Plain",
            "Template",
            "Hex",
            "Decimal",
            "Binary",
            "Ten",
            "Octal",
            "Eight",
            "Exponent",
            "OneFifty",
            "HexBig",
            "DecimalBig",
            "SeparatedBig",
            "ThousandBig",
        ];
        let nodes = names
            .iter()
            .map(|name| (*name, alias_parts(&fixture, name).2))
            .collect::<Vec<_>>();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let mut resolved = BTreeMap::new();
        {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            let mut query = CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            for (name, node) in nodes {
                resolved.insert(name, query.get_type_from_type_node(node).unwrap());
            }
        }
        assert_eq!(resolved["Escaped"], resolved["Plain"]);
        assert_eq!(resolved["Plain"], resolved["Template"]);
        for (left, right) in [
            ("Hex", "Decimal"),
            ("Binary", "Ten"),
            ("Octal", "Eight"),
            ("Exponent", "OneFifty"),
            ("HexBig", "DecimalBig"),
            ("SeparatedBig", "ThousandBig"),
        ] {
            assert_eq!(resolved[left], resolved[right], "{left} versus {right}");
        }
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn parsed_unions_sort_deduplicate_cache_and_preserve_direct_alias_identity() {
        let mut fixture = fixture(concat!(
            "type Named = string | number; ",
            "type Duplicate = number | string | string; ",
            "declare let first: string | number; ",
            "declare let second: number | string;",
        ));
        let named_alias_symbol = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Named");
        let named_node = alias_parts(&fixture, "Named").2;
        let duplicate_symbol =
            named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Duplicate");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let direct = query_node(&mut fixture, named_node, &mut diagnostics).unwrap();
        let declared = query_declared(
            &mut fixture,
            named_alias_symbol,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert_eq!(direct, declared);
        assert_eq!(
            union_alias_symbol(&fixture.store, direct),
            Some(named_alias_symbol)
        );
        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        assert_eq!(
            union_types(&fixture.store, direct),
            [bootstrap.string_type, bootstrap.number_type]
        );
        assert!(
            fixture
                .store
                .type_payload(direct)
                .unwrap()
                .object_flags()
                .contains(ObjectFlags::PRIMITIVE_UNION)
        );

        let duplicate = query_declared(
            &mut fixture,
            duplicate_symbol,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert_ne!(duplicate, direct);
        assert_eq!(
            union_types(&fixture.store, duplicate),
            union_types(&fixture.store, direct)
        );
        assert_eq!(
            union_alias_symbol(&fixture.store, duplicate),
            Some(duplicate_symbol)
        );

        let anonymous =
            fixture
                .parsed
                .arena
                .iter()
                .filter_map(|(id, node)| {
                    (node.kind == SyntaxKind::UnionType
                        && node.parent.is_some_and(|parent| {
                            fixture.parsed.arena.get(parent).is_some_and(|parent| {
                                parent.kind == SyntaxKind::VariableDeclaration
                            })
                        }))
                    .then_some(NodeRef::new(
                        fixture.parsed.arena.id(),
                        fixture.file,
                        id,
                    ))
                })
                .collect::<Vec<_>>();
        assert_eq!(anonymous.len(), 2);
        let first = query_node(&mut fixture, anonymous[0], &mut diagnostics).unwrap();
        let second = query_node(&mut fixture, anonymous[1], &mut diagnostics).unwrap();
        assert_eq!(first, second);
        assert_eq!(
            first,
            fixture
                .store
                .intrinsic_bootstrap()
                .unwrap()
                .string_or_number_type
        );
        assert_eq!(
            query_node(&mut fixture, named_node, &mut diagnostics),
            Ok(direct)
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn generic_interface_union_constituents_preserve_identity_and_warm_caches() {
        let mut fixture = fixture_with_intrinsic(
            "interface Box<T> {} type Result = Box<string> | null;",
            IntrinsicBootstrapOptions {
                strict_null_checks: true,
                ..IntrinsicBootstrapOptions::default()
            },
        );
        let owner = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Box");
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Result");
        let body = alias_parts(&fixture, "Result").2;
        let (string, null) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.null_type)
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let resolved = query_declared(
            &mut fixture,
            alias,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let reference = union_types(&fixture.store, resolved)
            .iter()
            .copied()
            .find(|type_| validate_direct_generic_reference(&fixture.store, *type_).is_ok())
            .expect("the union retains its authenticated generic interface reference");
        let validated = validate_direct_generic_reference(&fixture.store, reference).unwrap();
        assert_eq!(
            Some(validated.target),
            fixture
                .store
                .declared_type_links(owner)
                .and_then(|links| links.declared_type),
        );
        assert_eq!(validated.type_arguments.as_slice(), &[string]);
        assert!(union_types(&fixture.store, resolved).contains(&null));
        assert_eq!(union_alias_symbol(&fixture.store, resolved), Some(alias));
        assert_eq!(fixture.store.validate_union_constituent(reference), Ok(()));

        let warm = union_state(&fixture.store);
        for _ in 0..2 {
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(resolved),
            );
            assert_eq!(
                query_node(&mut fixture, body, &mut diagnostics),
                Ok(resolved)
            );
            assert_eq!(union_state(&fixture.store), warm);
        }
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn generic_nullable_union_aliases_substitute_owned_parameters_and_replay_warm() {
        let mut fixture = fixture_with_intrinsic(
            concat!(
                "type Maybe<Value> = Value | null; ",
                "let first: Maybe<string>; ",
                "let second: Maybe<string>; ",
                "let number: Maybe<number>;",
            ),
            IntrinsicBootstrapOptions {
                strict_null_checks: true,
                ..IntrinsicBootstrapOptions::default()
            },
        );
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Maybe");
        let parameter = named_symbol(&fixture, SyntaxKind::TypeParameter, "Value");
        let first = variable_type_node(&fixture, "first");
        let second = variable_type_node(&fixture, "second");
        let number = variable_type_node(&fixture, "number");
        let (string_type, number_type, null_type) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (
                bootstrap.string_type,
                bootstrap.number_type,
                bootstrap.null_type,
            )
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let declared = query_declared(
            &mut fixture,
            alias,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let parameter_type = fixture
            .store
            .declared_type_links(parameter)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_eq!(union_alias_symbol(&fixture.store, declared), Some(alias));
        assert_eq!(
            fixture
                .store
                .validate_union_alias_identity(declared, alias, &[parameter_type]),
            Ok(()),
        );
        assert!(union_types(&fixture.store, declared).contains(&parameter_type));
        assert!(union_types(&fixture.store, declared).contains(&null_type));

        let first_type = query_node(&mut fixture, first, &mut diagnostics).unwrap();
        let second_type = query_node(&mut fixture, second, &mut diagnostics).unwrap();
        let number_result = query_node(&mut fixture, number, &mut diagnostics).unwrap();
        assert_eq!(first_type, second_type);
        assert_ne!(first_type, number_result);
        assert_eq!(
            fixture
                .store
                .validate_union_alias_identity(first_type, alias, &[string_type]),
            Ok(())
        );
        assert_eq!(
            fixture
                .store
                .validate_union_alias_identity(number_result, alias, &[number_type]),
            Ok(())
        );
        assert!(union_types(&fixture.store, first_type).contains(&string_type));
        assert!(union_types(&fixture.store, first_type).contains(&null_type));
        assert!(union_types(&fixture.store, number_result).contains(&number_type));
        assert!(union_types(&fixture.store, number_result).contains(&null_type));

        let warm = union_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(declared),
        );
        for (node, expected) in [
            (first, first_type),
            (second, second_type),
            (number, number_result),
        ] {
            assert_eq!(
                query_node(&mut fixture, node, &mut diagnostics),
                Ok(expected)
            );
        }
        assert_eq!(union_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn generic_union_alias_identity_keeps_argument_order_and_reduced_results() {
        for reference_first in [false, true] {
            let mut fixture = fixture(concat!(
                "type Choice<Left, Right> = Left | Right; ",
                "let forward: Choice<string, number>; ",
                "let reverse: Choice<number, string>; ",
                "let reduced: Choice<string, string>;",
            ));
            let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Choice");
            let forward_node = variable_type_node(&fixture, "forward");
            let reverse_node = variable_type_node(&fixture, "reverse");
            let reduced_node = variable_type_node(&fixture, "reduced");
            let (string, number) = {
                let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
                (bootstrap.string_type, bootstrap.number_type)
            };
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            if !reference_first {
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap();
            }
            let forward = query_node(&mut fixture, forward_node, &mut diagnostics).unwrap();
            let reverse = query_node(&mut fixture, reverse_node, &mut diagnostics).unwrap();
            let reduced = query_node(&mut fixture, reduced_node, &mut diagnostics).unwrap();
            assert_ne!(forward, reverse);
            assert_eq!(
                union_types(&fixture.store, forward),
                union_types(&fixture.store, reverse)
            );
            assert_eq!(
                fixture
                    .store
                    .validate_union_alias_identity(forward, alias, &[string, number]),
                Ok(())
            );
            assert_eq!(
                fixture
                    .store
                    .validate_union_alias_identity(reverse, alias, &[number, string]),
                Ok(())
            );
            assert_eq!(reduced, string);
            assert!(
                fixture
                    .store
                    .type_payload(reduced)
                    .unwrap()
                    .alias()
                    .is_none()
            );
            let declared = query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let parameters = fixture
                .store
                .type_alias_links(alias)
                .unwrap()
                .type_parameters
                .as_ref()
                .unwrap();
            assert_eq!(
                fixture
                    .store
                    .validate_union_alias_identity(declared, alias, parameters),
                Ok(())
            );
            let before = union_state(&fixture.store);
            for (node, expected) in [
                (forward_node, forward),
                (reverse_node, reverse),
                (reduced_node, reduced),
            ] {
                assert_eq!(
                    query_node(&mut fixture, node, &mut diagnostics),
                    Ok(expected)
                );
            }
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics
                ),
                Ok(declared)
            );
            assert_eq!(union_state(&fixture.store), before);
            assert!(diagnostics.is_empty());
        }
    }

