    #[test]
    fn alias_chains_cache_in_type_alias_links_and_ignore_declared_type_links() {
        let mut fixture = fixture("type Base = string; type Alias = Base;");
        let base = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Base");
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Alias");
        let (_, _, reference) = alias_parts(&fixture, "Alias");
        let number_type = fixture.store.intrinsic_bootstrap().unwrap().number_type;
        let string_type = fixture.store.intrinsic_bootstrap().unwrap().string_type;
        assert!(fixture.store.set_declared_type_links(
            alias,
            DeclaredTypeLinks {
                declared_type: Some(number_type),
                ..DeclaredTypeLinks::default()
            },
        ));

        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(string_type)
        );
        assert_eq!(
            fixture
                .store
                .type_alias_links(base)
                .and_then(|links| links.declared_type),
            Some(string_type)
        );
        assert_eq!(
            fixture
                .store
                .type_alias_links(alias)
                .and_then(|links| links.declared_type),
            Some(string_type)
        );
        assert_eq!(
            fixture
                .store
                .declared_type_links(alias)
                .and_then(|links| links.declared_type),
            Some(number_type)
        );
        assert_eq!(
            fixture
                .store
                .type_node_links(reference)
                .and_then(|links| links.resolved_type),
            Some(string_type)
        );
        assert_eq!(
            fixture
                .store
                .symbol_node_links(reference)
                .and_then(|links| links.resolved_symbol),
            Some(base)
        );

        let empty = DeclaredTypeHost::new(std::iter::empty::<(&NodeArena, &BoundFile)>()).unwrap();
        let mut retry_diagnostics = CanonicalCheckerDiagnostics::default();
        let mut retry = CanonicalTypeQuery::new(
            &mut fixture.store,
            &empty,
            CanonicalTypeQueryOptions::default(),
            &mut retry_diagnostics,
        )
        .unwrap();
        assert_eq!(retry.get_declared_type_of_symbol(alias), Ok(string_type));
        assert!(retry_diagnostics.is_empty());
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn generic_alias_seeds_its_identity_instantiation_in_parameter_order() {
        let mut fixture = fixture("type Id<T, U> = T;");
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Id");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let declared = query_declared(
            &mut fixture,
            alias,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let links = fixture.store.type_alias_links(alias).unwrap();
        let parameters = links.type_parameters.as_deref().unwrap();
        assert_eq!(parameters.len(), 2);
        let names = parameters
            .iter()
            .map(|parameter| {
                let symbol = fixture
                    .store
                    .type_payload(*parameter)
                    .unwrap()
                    .symbol()
                    .unwrap();
                fixture
                    .store
                    .symbol(symbol)
                    .unwrap()
                    .name()
                    .as_utf8()
                    .unwrap()
            })
            .collect::<Vec<_>>();
        assert_eq!(names, ["T", "U"]);
        assert_eq!(declared, parameters[0]);
        assert_eq!(
            links
                .instantiations
                .as_ref()
                .unwrap()
                .get(&type_list_key(parameters)),
            Some(&declared)
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn default_library_non_nullable_alias_preserves_deferred_parameter_identity() {
        let mut fixture = default_library_fixture(concat!(
            "type NonNullable<T> = T & {}; ",
            "type Forward<Value> = NonNullable<Value>;",
        ));
        let non_nullable = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "NonNullable");
        let forward = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Forward");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let declared = query_declared(
            &mut fixture,
            non_nullable,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let parameter = fixture
            .store
            .type_alias_links(non_nullable)
            .and_then(|links| links.type_parameters.as_deref())
            .and_then(|parameters| parameters.first())
            .copied()
            .unwrap();
        let projection = fixture
            .store
            .validate_deferred_intersection_type(declared)
            .unwrap();
        let empty_object = fixture
            .store
            .intrinsic_bootstrap()
            .unwrap()
            .empty_type_literal_type;
        assert_eq!(projection.alias_symbol, Some(non_nullable));
        assert_eq!(projection.alias_arguments, [parameter]);
        assert_eq!(projection.types, [parameter, empty_object]);

        let forwarded = query_declared(
            &mut fixture,
            forward,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let forward_parameter = fixture
            .store
            .type_alias_links(forward)
            .and_then(|links| links.type_parameters.as_deref())
            .and_then(|parameters| parameters.first())
            .copied()
            .unwrap();
        let forwarded_projection = fixture
            .store
            .validate_deferred_intersection_type(forwarded)
            .unwrap();
        assert_eq!(forwarded_projection.alias_symbol, Some(non_nullable));
        assert_eq!(forwarded_projection.alias_arguments, [forward_parameter]);
        assert_eq!(
            forwarded_projection.types,
            [forward_parameter, empty_object]
        );
        assert_ne!(declared, forwarded);

        let warm = store_state(&fixture.store);
        for (alias, expected) in [(non_nullable, declared), (forward, forwarded)] {
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

