    #[test]
    #[allow(clippy::too_many_lines)] // Both related aliases share one authenticated ambient module.
    fn prop_types_key_aliases_rebind_mapped_conditionals_and_reuse_warm_caches() {
        let PropTypesInferPropsFixture {
            library,
            declarations,
            library_file,
            declaration_file,
            files,
            mut store,
        } = prop_types_key_alias_fixture(
            "prop-types",
            concat!(
                "{ [K in keyof V]: V[K] extends Validator<infer T> ",
                "? IsOptional<T> extends true ? never : K : never }[keyof V]",
            ),
            "Exclude<keyof V, RequiredKeys<V>>",
        );
        let bound = files.get(&declaration_file).unwrap();
        let find_alias = |name: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::TypeAliasDeclaration(alias) = &record.data else {
                        return None;
                    };
                    (identifier_text(&declarations.arena, alias.name) == Some(name)).then(|| {
                        bound
                            .symbol(NodeRef::new(
                                declarations.arena.id(),
                                declaration_file,
                                node,
                            ))
                            .unwrap()
                    })
                })
                .unwrap()
        };
        let required = find_alias("RequiredKeys");
        let optional = find_alias("OptionalKeys");
        let required_forward = find_alias("RequiredForward");
        let optional_forward = find_alias("OptionalForward");
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, files.get(&library_file).unwrap()),
                (&declarations.arena, bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let aliases = HashMap::new();
        let planner = TypeQueryPlanner::new(&store, &host, None, None, false, &aliases);
        assert_eq!(
            planner
                .authenticated_prop_types_key_alias(required)
                .map(|proof| proof.kind),
            Some(PropTypesKeyAliasKind::Required),
        );
        assert_eq!(
            planner
                .authenticated_prop_types_key_alias(optional)
                .map(|proof| proof.kind),
            Some(PropTypesKeyAliasKind::Optional),
        );

        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let required_result = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_declared_type_of_symbol(required_forward)
        .unwrap();
        let required_parameter = store
            .type_alias_links(required_forward)
            .and_then(|links| links.type_parameters.as_deref())
            .and_then(|parameters| parameters.first())
            .copied()
            .unwrap();
        let required_links = store.type_alias_links(required).unwrap();
        assert_eq!(
            store.validate_prop_types_required_keys_instantiation(
                required,
                required_links.declared_type.unwrap(),
                required_links.type_parameters.as_deref().unwrap(),
                &[required_parameter],
                required_result,
            ),
            Ok(()),
        );
        let TypeData::IndexedAccess(required_index) =
            store.type_payload(required_result).unwrap().data()
        else {
            panic!("RequiredKeys must preserve its mapped indexed identity")
        };
        let TypeData::Index(keys) = store
            .type_payload(required_index.index_type)
            .unwrap()
            .data()
        else {
            panic!("RequiredKeys must retain keyof its forwarded source")
        };
        assert_eq!(keys.target, required_parameter);

        let optional_result = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_declared_type_of_symbol(optional_forward)
        .unwrap();
        let optional_parameter = store
            .type_alias_links(optional_forward)
            .and_then(|links| links.type_parameters.as_deref())
            .and_then(|parameters| parameters.first())
            .copied()
            .unwrap();
        let TypeData::Conditional(optional_condition) =
            store.type_payload(optional_result).unwrap().data()
        else {
            panic!("OptionalKeys must preserve its deferred Exclude conditional")
        };
        let TypeData::Index(optional_keys) = store
            .type_payload(optional_condition.check_type)
            .unwrap()
            .data()
        else {
            panic!("OptionalKeys must retain keyof its forwarded source")
        };
        assert_eq!(optional_keys.target, optional_parameter);
        assert!(matches!(
            store
                .type_payload(optional_condition.extends_type)
                .map(TypeRecord::data),
            Some(TypeData::IndexedAccess(_)),
        ));

        let warm = store_state(&store);
        for (alias, expected) in [
            (required_forward, required_result),
            (optional_forward, optional_result),
        ] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_declared_type_of_symbol(alias),
                Ok(expected),
            );
            assert_eq!(store_state(&store), warm);
        }
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn prop_types_key_aliases_reject_other_modules_and_changed_conditional_branches() {
        let valid_required = concat!(
            "{ [K in keyof V]: V[K] extends Validator<infer T> ",
            "? IsOptional<T> extends true ? never : K : never }[keyof V]",
        );
        for (module, required) in [
            ("lookalike", valid_required),
            (
                "prop-types",
                concat!(
                    "{ [K in keyof V]: V[K] extends Validator<infer T> ",
                    "? IsOptional<T> extends true ? K : never : never }[keyof V]",
                ),
            ),
        ] {
            let PropTypesInferPropsFixture {
                library,
                declarations,
                library_file,
                declaration_file,
                files,
                mut store,
            } = prop_types_key_alias_fixture(module, required, "Exclude<keyof V, RequiredKeys<V>>");
            let bound = files.get(&declaration_file).unwrap();
            let alias = declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::TypeAliasDeclaration(alias) = &record.data else {
                        return None;
                    };
                    (identifier_text(&declarations.arena, alias.name) == Some("RequiredKeys")).then(
                        || {
                            bound
                                .symbol(NodeRef::new(
                                    declarations.arena.id(),
                                    declaration_file,
                                    node,
                                ))
                                .unwrap()
                        },
                    )
                })
                .unwrap();
            let host = DeclaredTypeHost::new_after_global_merge(
                [
                    (&library.arena, files.get(&library_file).unwrap()),
                    (&declarations.arena, bound),
                ],
                GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
            )
            .unwrap();
            let aliases = HashMap::new();
            assert!(
                TypeQueryPlanner::new(&store, &host, None, None, false, &aliases)
                    .authenticated_prop_types_key_alias(alias)
                    .is_none(),
                "module: {module}",
            );

            let forward = declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::TypeAliasDeclaration(alias) = &record.data else {
                        return None;
                    };
                    (identifier_text(&declarations.arena, alias.name) == Some("RequiredForward"))
                        .then(|| {
                            bound
                                .symbol(NodeRef::new(
                                    declarations.arena.id(),
                                    declaration_file,
                                    node,
                                ))
                                .unwrap()
                        })
                })
                .unwrap();
            let before = store_state(&store);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            assert!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_declared_type_of_symbol(forward)
                .is_err(),
            );
            assert_eq!(store_state(&store), before);
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn poisoned_prop_types_required_key_mapper_fails_before_warm_query_writes() {
        let PropTypesInferPropsFixture {
            library,
            declarations,
            library_file,
            declaration_file,
            files,
            mut store,
        } = prop_types_key_alias_fixture(
            "prop-types",
            concat!(
                "{ [K in keyof V]: V[K] extends Validator<infer T> ",
                "? IsOptional<T> extends true ? never : K : never }[keyof V]",
            ),
            "Exclude<keyof V, RequiredKeys<V>>",
        );
        let bound = files.get(&declaration_file).unwrap();
        let alias = declarations
            .arena
            .iter()
            .find_map(|(node, record)| {
                let NodeData::TypeAliasDeclaration(alias) = &record.data else {
                    return None;
                };
                (identifier_text(&declarations.arena, alias.name) == Some("RequiredForward")).then(
                    || {
                        bound
                            .symbol(NodeRef::new(
                                declarations.arena.id(),
                                declaration_file,
                                node,
                            ))
                            .unwrap()
                    },
                )
            })
            .unwrap();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, files.get(&library_file).unwrap()),
                (&declarations.arena, bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let resolved = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_declared_type_of_symbol(alias)
        .unwrap();
        let parameter = match store.type_payload(resolved).unwrap().data() {
            TypeData::IndexedAccess(indexed) => {
                match store.type_payload(indexed.object_type).unwrap().data() {
                    TypeData::Mapped(mapped) => mapped.type_parameter.unwrap(),
                    _ => unreachable!(),
                }
            }
            _ => unreachable!(),
        };
        let (constraint, target, mapper, default_type) =
            match store.type_payload(parameter).unwrap().data() {
                TypeData::TypeParameter(parameter) => (
                    parameter.constraint,
                    parameter.target,
                    parameter.mapper,
                    parameter.resolved_default_type,
                ),
                _ => unreachable!(),
            };
        assert!(mapper.is_some());
        assert!(store.set_type_parameter_resolution(
            parameter,
            constraint,
            target,
            None,
            default_type,
        ));
        let poisoned = store_state(&store);

        for _ in 0..2 {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_declared_type_of_symbol(alias),
                Err(type_node_unavailable(
                    TypeNodeUnavailable::InvalidCachedTypeAlias(alias),
                )),
            );
            assert_eq!(store_state(&store), poisoned);
        }
        assert!(store.set_type_parameter_resolution(
            parameter,
            constraint,
            target,
            mapper,
            default_type,
        ));
        assert_eq!(
            CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_declared_type_of_symbol(alias),
            Ok(resolved),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn warmed_non_nullable_alias_rejects_changed_parameter_and_empty_object_identities() {
        let mut fixture = default_library_fixture("type NonNullable<T> = T & {};");
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "NonNullable");
        let intersection = alias_parts(&fixture, "NonNullable").2;
        let NodeData::IntersectionTypeNode(data) =
            &fixture.parsed.arena.get(intersection.node).unwrap().data
        else {
            panic!("NonNullable must have an intersection body")
        };
        let empty = NodeRef::new(intersection.arena, intersection.file, data.types.nodes[1]);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let declared = query_declared(
            &mut fixture,
            alias,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let parameter = fixture
            .store
            .type_alias_links(alias)
            .and_then(|links| links.type_parameters.as_deref())
            .and_then(|parameters| parameters.first())
            .and_then(|parameter| cached_ordinary_type_parameter_owner(&fixture.store, *parameter))
            .unwrap();
        let original_relationships = {
            let owner = fixture.store.symbol(parameter).unwrap();
            (
                owner.members(),
                owner.exports(),
                owner.parent(),
                owner.export_symbol(),
            )
        };
        assert!(fixture.store.set_symbol_relationships(
            parameter,
            original_relationships.0,
            original_relationships.1,
            Some(alias),
            original_relationships.3,
        ));
        let changed = union_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(type_node_unavailable(
                TypeNodeUnavailable::InvalidCachedTypeAlias(alias),
            )),
        );
        assert_eq!(union_state(&fixture.store), changed);
        assert!(fixture.store.set_symbol_relationships(
            parameter,
            original_relationships.0,
            original_relationships.1,
            original_relationships.2,
            original_relationships.3,
        ));
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(declared),
        );

        let original_links = fixture.store.type_node_links(empty).cloned().unwrap();
        let mut changed_links = original_links.clone();
        changed_links.resolved_type = Some(
            fixture
                .store
                .intrinsic_bootstrap()
                .unwrap()
                .empty_object_type,
        );
        assert!(fixture.store.set_type_node_links(empty, changed_links));
        let changed = union_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(type_node_unavailable(
                TypeNodeUnavailable::InvalidCachedTypeAlias(alias),
            )),
        );
        assert_eq!(union_state(&fixture.store), changed);
        assert!(fixture.store.set_type_node_links(empty, original_links));
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(declared),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn default_library_non_nullable_reduces_concrete_arguments_and_forwarded_aliases() {
        for strict_null_checks in [false, true] {
            let mut fixture = fixture_with_source_facts(
                concat!(
                    "type NonNullable<T> = T & {}; ",
                    "type Text = NonNullable<string>; ",
                    "type Null = NonNullable<null>; ",
                    "type Missing = NonNullable<undefined>; ",
                    "type Never = NonNullable<never>; ",
                    "type Unknown = NonNullable<unknown>; ",
                    "type Any = NonNullable<any>; ",
                    "type Optional = NonNullable<string | null | undefined>; ",
                    "type Forward<Value> = NonNullable<Value>; ",
                    "type ForwardText = Forward<string>;",
                ),
                CanonicalModuleState::Script,
                IntrinsicBootstrapOptions {
                    strict_null_checks,
                    ..IntrinsicBootstrapOptions::default()
                },
                true,
                |_| {},
            );
            let expected = {
                let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
                [
                    ("Text", bootstrap.string_type),
                    ("Null", bootstrap.never_type),
                    ("Missing", bootstrap.never_type),
                    ("Never", bootstrap.never_type),
                    ("Unknown", bootstrap.empty_type_literal_type),
                    ("Any", bootstrap.any_type),
                    ("Optional", bootstrap.string_type),
                    ("ForwardText", bootstrap.string_type),
                ]
            };
            let mut diagnostics = CanonicalCheckerDiagnostics::default();

            for (name, type_) in expected {
                let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
                assert_eq!(
                    query_declared(
                        &mut fixture,
                        alias,
                        CanonicalTypeQueryOptions::default(),
                        &mut diagnostics,
                    ),
                    Ok(type_),
                    "{name}, strict_null_checks={strict_null_checks}",
                );
            }

            let warm = store_state(&fixture.store);
            for (name, type_) in expected {
                let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
                assert_eq!(
                    query_declared(
                        &mut fixture,
                        alias,
                        CanonicalTypeQueryOptions::default(),
                        &mut diagnostics,
                    ),
                    Ok(type_),
                    "warm {name}, strict_null_checks={strict_null_checks}",
                );
            }
            assert_eq!(store_state(&fixture.store), warm);
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // One source fixture verifies both mapped utilities and shared origins.
    fn default_library_pick_and_partial_preserve_property_keys_and_modifiers() {
        let mut fixture = default_library_fixture(concat!(
            "type Partial<T> = { [P in keyof T]?: T[P] }; ",
            "type Pick<T, K extends keyof T> = { [P in K]: T[P] }; ",
            "interface Shape { readonly fixed: string; optional?: number; other: boolean; } ",
            "type Weak = Partial<Shape>; ",
            "type Selected = Pick<Shape, 'fixed' | 'optional'>;",
        ));
        let partial = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Partial");
        let pick = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Pick");
        let weak = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Weak");
        let selected = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Selected");
        let shape = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Shape");
        let (string, number) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.number_type)
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let weak_type = query_declared(
            &mut fixture,
            weak,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let selected_type = query_declared(
            &mut fixture,
            selected,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let shape_type = fixture
            .store
            .declared_type_links(shape)
            .and_then(|links| links.declared_type)
            .unwrap();
        let source_fixed = fixture
            .store
            .symbol(shape)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| fixture.store.symbol_table(members))
            .and_then(|members| members.get_source("fixed"))
            .unwrap();

        let partial_links = fixture.store.type_alias_links(partial).unwrap();
        let partial_declared = partial_links.declared_type.unwrap();
        let partial_parameters = partial_links.type_parameters.as_deref().unwrap();
        assert_eq!(
            fixture
                .store
                .validate_homomorphic_mapped_alias_instantiation(
                    partial,
                    partial_declared,
                    partial_parameters,
                    &[shape_type],
                    weak_type,
                    MappedTypeModifiers::INCLUDE_OPTIONAL,
                ),
            Ok(()),
        );

        let selected_argument = match &fixture
            .parsed
            .arena
            .get(alias_parts(&fixture, "Selected").2.node)
            .unwrap()
            .data
        {
            NodeData::TypeReferenceNode(reference) => NodeRef::new(
                fixture.parsed.arena.id(),
                fixture.file,
                reference.type_arguments.as_ref().unwrap().nodes[1],
            ),
            _ => unreachable!(),
        };
        let selected_keys = fixture
            .store
            .type_node_links(selected_argument)
            .and_then(|links| links.resolved_type)
            .unwrap();
        let pick_links = fixture.store.type_alias_links(pick).unwrap();
        assert_eq!(
            fixture.store.validate_pick_mapped_alias_instantiation(
                pick,
                pick_links.declared_type.unwrap(),
                pick_links.type_parameters.as_deref().unwrap(),
                &[shape_type, selected_keys],
                selected_type,
            ),
            Ok(()),
        );

        let weak_fixed = fixture
            .store
            .resolve_mapped_type_property(weak_type, "fixed", MappedTypeModifiers::NONE)
            .unwrap()
            .unwrap();
        assert_eq!(weak_fixed.type_id(), string);
        assert!(weak_fixed.is_optional());
        assert!(weak_fixed.is_readonly());
        assert_eq!(
            fixture
                .store
                .mapped_symbol_links(weak_fixed.symbol())
                .and_then(|links| links.synthetic_origin),
            Some(source_fixed),
        );
        let weak_optional = fixture
            .store
            .resolve_mapped_type_property(weak_type, "optional", MappedTypeModifiers::NONE)
            .unwrap()
            .unwrap();
        assert_eq!(weak_optional.type_id(), number);
        assert!(weak_optional.is_optional());

        let fixed = fixture
            .store
            .resolve_mapped_type_property(selected_type, "fixed", MappedTypeModifiers::NONE)
            .unwrap()
            .unwrap();
        assert_eq!(fixed.type_id(), string);
        assert!(!fixed.is_optional());
        assert!(fixed.is_readonly());
        assert_eq!(
            fixture
                .store
                .mapped_symbol_links(fixed.symbol())
                .and_then(|links| links.synthetic_origin),
            Some(source_fixed),
        );
        let optional = fixture
            .store
            .resolve_mapped_type_property(selected_type, "optional", MappedTypeModifiers::NONE)
            .unwrap()
            .unwrap();
        assert_eq!(optional.type_id(), number);
        assert!(optional.is_optional());
        assert_eq!(
            fixture.store.resolve_mapped_type_property(
                selected_type,
                "other",
                MappedTypeModifiers::NONE,
            ),
            Ok(None),
        );
        assert_eq!(
            fixture
                .store
                .resolve_mapped_type_members(weak_type, MappedTypeModifiers::EXCLUDE_OPTIONAL),
            Err(MappedTypeError::InvalidModifiers),
        );

        let warm = union_state(&fixture.store);
        for (alias, expected) in [(weak, weak_type), (selected, selected_type)] {
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
            );
            assert_eq!(union_state(&fixture.store), warm);
        }
        assert!(diagnostics.is_empty());
    }

