    #[test]
    fn record_mapped_alias_warm_cache_rejects_invalid_mapper_and_owner_metadata() {
        for corruption in 0..3 {
            let mut fixture = fixture(concat!(
                "type Record<K extends keyof any, T> = { [P in K]: T }; ",
                "type First = Record<string, number>;",
            ));
            let first = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "First");
            let string_type = fixture.store.intrinsic_bootstrap().unwrap().string_type;
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let instantiated = query_declared(
                &mut fixture,
                first,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let record = fixture.store.type_payload(instantiated).unwrap();
            let identity = record.alias().unwrap();
            let TypeData::Mapped(mapped) = record.data() else {
                unreachable!()
            };
            let parameter = mapped.type_parameter.unwrap();

            match corruption {
                0 => {
                    let TypeData::TypeParameter(parameter_data) =
                        fixture.store.type_payload(parameter).unwrap().data()
                    else {
                        unreachable!()
                    };
                    let constraint = parameter_data.constraint;
                    let target = parameter_data.target;
                    let default_type = parameter_data.resolved_default_type;
                    assert!(fixture.store.set_type_parameter_resolution(
                        parameter,
                        constraint,
                        target,
                        None,
                        default_type,
                    ));
                }
                1 => {
                    assert!(
                        fixture
                            .store
                            .set_type_alias_arguments(identity, Some(vec![string_type]))
                    );
                }
                2 => assert!(fixture.store.set_type_alias(instantiated, None)),
                _ => unreachable!(),
            }

            let before = union_state(&fixture.store);
            for _ in 0..2 {
                assert_eq!(
                    query_declared(
                        &mut fixture,
                        first,
                        CanonicalTypeQueryOptions::default(),
                        &mut diagnostics,
                    ),
                    Err(type_node_unavailable(
                        TypeNodeUnavailable::InvalidCachedTypeAlias(first),
                    )),
                    "corruption case {corruption}",
                );
                assert_eq!(union_state(&fixture.store), before);
            }
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn record_mapped_alias_rejects_another_owners_cached_instance_before_publication() {
        let mut fixture = fixture(concat!(
            "type Record<K extends keyof any, T> = { [P in K]: T }; ",
            "type First = Record<string, number>; ",
            "type Second = Record<string, number>;",
        ));
        let record = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Record");
        let first = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "First");
        let second = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Second");
        let second_reference = alias_parts(&fixture, "Second").2;
        let arguments = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            [bootstrap.string_type, bootstrap.number_type]
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let first_type = query_declared(
            &mut fixture,
            first,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let second_global = fixture.store.global_symbol_id(second).unwrap();
        let second_key = alias_instantiation_key(&arguments, Some((second_global, &[])));
        let mut links = fixture.store.type_alias_links(record).unwrap().clone();
        assert_eq!(
            links
                .instantiations
                .as_mut()
                .unwrap()
                .insert(second_key, first_type),
            None,
        );
        assert!(fixture.store.set_type_alias_links(record, links));
        let before = union_state(&fixture.store);

        for _ in 0..2 {
            assert_eq!(
                query_declared(
                    &mut fixture,
                    second,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Err(type_node_unavailable(
                    TypeNodeUnavailable::InvalidGenericAliasInstantiationCache(record),
                )),
            );
            assert_eq!(union_state(&fixture.store), before);
            assert!(fixture.store.type_alias_links(second).is_none());
            assert!(fixture.store.type_node_links(second_reference).is_none());
            assert!(fixture.store.symbol_node_links(second_reference).is_none());
        }
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn generic_alias_constraints_resolve_supported_bounds_before_alias_bodies() {
        let mut fixture = fixture(concat!(
            "type Text<T extends string> = T; ",
            "type Dependent<T extends string, U extends T> = U; ",
            "type Anything<T extends any> = T; ",
            "type Parenthesized<T extends (string)> = T; ",
            "type Scalar<T extends string | number> = T; ",
            "type Exact<T extends 'ok'> = T; ",
            "type Word = Text<'ok'>; ",
            "type Matched = Dependent<'ok', 'ok'>; ",
            "type Number = Anything<number>; ",
            "type ParenthesizedWord = Parenthesized<string>; ",
            "type ScalarNumber = Scalar<number>; ",
            "type ExactWord = Exact<'ok'>;",
        ));
        let text = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Text");
        let dependent = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Dependent");
        let anything = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Anything");
        let scalar = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Scalar");
        let (string_type, number_type, unknown_type) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (
                bootstrap.string_type,
                bootstrap.number_type,
                bootstrap.unknown_type,
            )
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        for name in [
            "Word",
            "Matched",
            "Number",
            "ParenthesizedWord",
            "ScalarNumber",
            "ExactWord",
        ] {
            let symbol = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
            let resolved = query_declared(
                &mut fixture,
                symbol,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            if matches!(name, "Number" | "ScalarNumber") {
                assert_eq!(resolved, number_type, "alias {name}");
            } else if name == "ParenthesizedWord" {
                assert_eq!(resolved, string_type);
            } else {
                assert!(matches!(
                    fixture.store.type_payload(resolved).map(TypeRecord::data),
                    Some(TypeData::Literal(data))
                        if data.value == LiteralValue::String("ok".to_owned())
                ));
            }
        }

        let text_parameter = fixture
            .store
            .type_alias_links(text)
            .unwrap()
            .type_parameters
            .as_ref()
            .unwrap()[0];
        let dependent_parameters = fixture
            .store
            .type_alias_links(dependent)
            .unwrap()
            .type_parameters
            .as_ref()
            .unwrap();
        let anything_parameter = fixture
            .store
            .type_alias_links(anything)
            .unwrap()
            .type_parameters
            .as_ref()
            .unwrap()[0];
        let scalar_parameter = fixture
            .store
            .type_alias_links(scalar)
            .unwrap()
            .type_parameters
            .as_ref()
            .unwrap()[0];
        let constraint = |parameter| match fixture.store.type_payload(parameter).unwrap().data() {
            TypeData::TypeParameter(data) => data.constraint,
            _ => unreachable!(),
        };
        assert_eq!(constraint(text_parameter), Some(string_type));
        assert_eq!(constraint(dependent_parameters[0]), Some(string_type));
        assert_eq!(
            constraint(dependent_parameters[1]),
            Some(dependent_parameters[0]),
        );
        assert_eq!(constraint(anything_parameter), Some(unknown_type));
        assert_eq!(
            union_types(&fixture.store, constraint(scalar_parameter).unwrap()),
            [string_type, number_type],
        );
        assert!(diagnostics.is_empty());

        let warm = union_state(&fixture.store);
        for name in ["Word", "Matched", "Number", "ScalarNumber"] {
            let symbol = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
            query_declared(
                &mut fixture,
                symbol,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
        }
        assert_eq!(union_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

