    #[test]
    fn concrete_conditionals_do_not_resolve_the_unselected_branch() {
        let mut fixture = fixture(concat!(
            "type OnlyText<T extends string> = T; ",
            "type SelectedTrue = string extends string ? string : OnlyText<number>; ",
            "type SelectedFalse = string extends number ? OnlyText<number> : number;",
        ));
        let unused_alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "OnlyText");
        let selected_true =
            named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "SelectedTrue");
        let selected_false =
            named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "SelectedFalse");
        let (string_type, number_type) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.number_type)
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        assert_eq!(
            query_declared(
                &mut fixture,
                selected_true,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(string_type),
        );
        assert_eq!(
            query_declared(
                &mut fixture,
                selected_false,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(number_type),
        );
        assert!(fixture.store.type_alias_links(unused_alias).is_none());
        assert!(diagnostics.is_empty());

        for (name, false_branch) in [("SelectedTrue", true), ("SelectedFalse", false)] {
            let conditional = alias_parts(&fixture, name).2;
            let NodeData::ConditionalTypeNode(data) =
                &fixture.parsed.arena.get(conditional.node).unwrap().data
            else {
                unreachable!()
            };
            let unselected = if false_branch {
                data.false_type
            } else {
                data.true_type
            };
            let unselected = NodeRef::new(conditional.arena, conditional.file, unselected);
            assert!(fixture.store.type_node_links(unselected).is_none());
        }
    }

    #[test]
    fn conditional_alias_warm_queries_reject_changed_owners_and_arguments_before_allocation() {
        for corruption in 0..4 {
            let mut fixture = fixture(concat!(
                "type Select<T> = ((T extends string ? number : boolean)); ",
                "type Other<U> = U;",
            ));
            let symbol = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Select");
            let other = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Other");
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let declared = query_declared(
                &mut fixture,
                symbol,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let root = match fixture.store.type_payload(declared).unwrap().data() {
                TypeData::Conditional(data) => data.root,
                _ => panic!("the generic declaration must retain its conditional root"),
            };
            let alias = fixture
                .store
                .conditional_root(root)
                .unwrap()
                .alias()
                .unwrap();
            match corruption {
                0 => assert!(fixture.store.set_type_alias(declared, None)),
                1 => assert!(fixture.store.set_conditional_root_alias(root, None)),
                2 => {
                    let number = fixture.store.intrinsic_bootstrap().unwrap().number_type;
                    assert!(
                        fixture
                            .store
                            .set_type_alias_arguments(alias, Some(vec![number]))
                    );
                }
                3 => {
                    let wrong = fixture.store.alloc_type_alias(Some(other)).unwrap();
                    assert!(fixture.store.set_conditional_root_alias(root, Some(wrong)));
                    assert!(fixture.store.set_type_alias(declared, Some(wrong)));
                }
                _ => unreachable!(),
            }
            let before = (
                union_state(&fixture.store),
                fixture.store.conditional_root_len(),
            );
            assert!(
                query_declared(
                    &mut fixture,
                    symbol,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .is_err()
            );
            assert_eq!(
                (
                    union_state(&fixture.store),
                    fixture.store.conditional_root_len()
                ),
                before,
            );
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn conditional_callable_inference_preserves_outer_signature_identity_and_warm_caches() {
        let mut fixture = fixture(concat!(
            "type Extract<Value> = ",
            "(<Inner extends Value>() => Inner) extends (() => infer Result) ",
            "? Result : never; ",
            "type Text = Extract<string>;",
        ));
        let extract = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Extract");
        let text = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Text");
        let functions = fixture
            .parsed
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::FunctionType).then_some(NodeRef::new(
                    fixture.parsed.arena.id(),
                    fixture.file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        assert_eq!(functions.len(), 2);
        let generic = functions
            .iter()
            .copied()
            .find(|node| {
                matches!(
                    &fixture.parsed.arena.get(node.node).unwrap().data,
                    NodeData::FunctionTypeNode(function) if function.type_parameters.is_some()
                )
            })
            .unwrap();
        let inferred = functions
            .iter()
            .copied()
            .find(|node| *node != generic)
            .unwrap();
        let inferred_return = function_return_node(&fixture, inferred);
        let expected = fixture.store.intrinsic_bootstrap().unwrap().string_type;
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        assert_eq!(
            query_declared(
                &mut fixture,
                text,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(expected),
        );

        let outer = fixture
            .store
            .type_alias_links(extract)
            .unwrap()
            .type_parameters
            .as_ref()
            .unwrap()[0];
        let generic_signature = function_signature(&fixture.store, generic);
        let [inner] = fixture
            .store
            .signature(generic_signature)
            .unwrap()
            .type_parameters()
        else {
            panic!("the source callable must retain its generic signature parameter")
        };
        let inner = *inner;
        let TypeData::TypeParameter(parameter) = fixture.store.type_payload(inner).unwrap().data()
        else {
            panic!("the generic signature parameter must retain its type identity")
        };
        assert_eq!(parameter.constraint, Some(outer));
        assert_eq!(
            fixture
                .store
                .signature(generic_signature)
                .and_then(Signature::resolved_return_type),
            Some(inner),
        );

        let inferred_signature = function_signature(&fixture.store, inferred);
        let inferred_type = fixture
            .store
            .signature(inferred_signature)
            .and_then(Signature::resolved_return_type)
            .unwrap();
        assert_eq!(
            fixture
                .store
                .type_node_links(inferred_return)
                .and_then(|links| links.resolved_type),
            Some(inferred_type),
        );
        let declared = fixture
            .store
            .type_alias_links(extract)
            .unwrap()
            .declared_type
            .unwrap();
        let TypeData::Conditional(conditional) =
            fixture.store.type_payload(declared).unwrap().data()
        else {
            panic!("the generic alias must retain its conditional root")
        };
        let root = fixture.store.conditional_root(conditional.root).unwrap();
        assert_eq!(root.infer_type_parameters(), Some(&[inferred_type][..]));
        assert_eq!(root.outer_type_parameters(), Some(&[outer][..]));

        let warm = (
            function_store_state(&fixture.store),
            fixture.store.conditional_root_len(),
        );
        assert_eq!(
            query_declared(
                &mut fixture,
                text,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(expected),
        );
        assert_eq!(
            (
                function_store_state(&fixture.store),
                fixture.store.conditional_root_len(),
            ),
            warm,
        );
        assert!(diagnostics.is_empty());
    }

    fn constrained_inferred_parameter_nodes(
        fixture: &Fixture,
        name: &str,
    ) -> (NodeRef, NodeRef, SemanticSymbolId) {
        let parameter = named_node(fixture, SyntaxKind::TypeParameter, name);
        let record = fixture.parsed.arena.get(parameter.node).unwrap();
        let NodeData::TypeParameterDeclaration(data) = &record.data else {
            unreachable!()
        };
        let infer = NodeRef::new(
            parameter.arena,
            parameter.file,
            record
                .parent
                .expect("an inferred parameter has an infer node"),
        );
        let constraint = NodeRef::new(
            parameter.arena,
            parameter.file,
            data.constraint
                .expect("the inferred parameter is constrained"),
        );
        (infer, constraint, node_symbol(fixture, parameter))
    }

    #[test]
    fn inferred_parameter_publishes_fixed_tuple_constraint_once() {
        let mut fixture =
            fixture("type Capture<T> = T extends infer Last extends [any, any] ? Last : never;");
        let (infer, constraint, symbol) = constrained_inferred_parameter_nodes(&fixture, "Last");
        let any = fixture.store.intrinsic_bootstrap().unwrap().any_type;
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let inferred = query_node(&mut fixture, infer, &mut diagnostics).unwrap();
        assert_eq!(
            cached_ordinary_type_parameter_owner(&fixture.store, inferred),
            Some(symbol),
        );
        let TypeData::TypeParameter(parameter) =
            fixture.store.type_payload(inferred).unwrap().data()
        else {
            panic!("infer must publish a type parameter")
        };
        let tuple = parameter
            .constraint
            .expect("the fixed tuple must be stored");
        assert_eq!(
            fixture
                .store
                .type_node_links(constraint)
                .and_then(|links| links.resolved_type),
            Some(tuple),
        );
        let shape = fixture.store.canonical_tuple_shape(tuple).unwrap().unwrap();
        assert_eq!(shape.element_types(), [any, any]);
        assert!(
            shape
                .element_infos()
                .iter()
                .all(|element| element.flags() == ElementFlags::REQUIRED)
        );

        let warm = (
            store_state(&fixture.store),
            fixture.store.canonical_tuple_target_len(),
            fixture.store.declared_type_links(symbol).cloned(),
            fixture.store.type_node_links(constraint).cloned(),
        );
        assert_eq!(
            query_node(&mut fixture, infer, &mut diagnostics),
            Ok(inferred),
        );
        assert_eq!(
            (
                store_state(&fixture.store),
                fixture.store.canonical_tuple_target_len(),
                fixture.store.declared_type_links(symbol).cloned(),
                fixture.store.type_node_links(constraint).cloned(),
            ),
            warm,
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn template_inferred_parameters_publish_primitive_constraints_and_replay_warm() {
        for bound in ["string", "number", "bigint", "boolean", "string | number"] {
            let source = format!(
                "type Capture<Input> = Input extends `${{infer Value extends {bound}}}` \
                 ? Value : never;"
            );
            let mut fixture = fixture(&source);
            let (infer, _, symbol) = constrained_inferred_parameter_nodes(&fixture, "Value");
            let mut diagnostics = CanonicalCheckerDiagnostics::default();

            let inferred = query_node(&mut fixture, infer, &mut diagnostics).unwrap();
            assert_eq!(
                cached_ordinary_type_parameter_owner(&fixture.store, inferred),
                Some(symbol),
            );
            let TypeData::TypeParameter(parameter) =
                fixture.store.type_payload(inferred).unwrap().data()
            else {
                panic!("{bound} must retain its inferred template type parameter")
            };
            let constraint = parameter
                .constraint
                .unwrap_or_else(|| panic!("{bound} must retain its exact inferred constraint"));
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            match bound {
                "string" => assert_eq!(constraint, bootstrap.string_type),
                "number" => assert_eq!(constraint, bootstrap.number_type),
                "bigint" => assert_eq!(constraint, bootstrap.bigint_type),
                "boolean" => assert_eq!(constraint, bootstrap.boolean_type),
                "string | number" => assert_eq!(
                    union_types(&fixture.store, constraint),
                    [bootstrap.string_type, bootstrap.number_type],
                ),
                _ => unreachable!("the template constraint matrix is closed"),
            }

            let warm = store_state(&fixture.store);
            assert_eq!(
                query_node(&mut fixture, infer, &mut diagnostics),
                Ok(inferred),
            );
            assert_eq!(store_state(&fixture.store), warm);
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn constrained_template_aliases_infer_numeric_values_and_complete_unicode_code_points() {
        let mut fixture = fixture(concat!(
            "type ParseNumber<Input> = ",
            "Input extends `${infer Value extends number}` ? Value : never; ",
            "type NumberResult = ParseNumber<'42'>; ",
            "type ParseBoolean<Input> = ",
            "Input extends `${infer Value extends boolean}` ? Value : never; ",
            "type BooleanResult = ParseBoolean<'true'>; ",
            "type ParseHead<Input> = ",
            "Input extends `${infer Head}${infer Rest}` ? Head : never; ",
            "type UnicodeResult = ParseHead<'\\u{1F600}tail'>;",
        ));
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        for (name, expected) in [
            ("NumberResult", LiteralValue::Number(Number::new(42.0))),
            ("BooleanResult", LiteralValue::Boolean(true)),
            (
                "UnicodeResult",
                LiteralValue::String("\u{1F600}".to_owned()),
            ),
        ] {
            let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
            let resolved = query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let TypeData::Literal(literal) = fixture.store.type_payload(resolved).unwrap().data()
            else {
                panic!("{name} must retain its inferred literal identity")
            };
            assert_eq!(literal.value, expected, "alias: {name}");
        }

        let warm = store_state(&fixture.store);
        for name in ["NumberResult", "BooleanResult", "UnicodeResult"] {
            let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
        }
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn inferred_parameter_rejects_poisoned_fixed_tuple_constraint_before_writes() {
        let mut fixture =
            fixture("type Capture<T> = T extends infer Last extends [any, any] ? Last : never;");
        let (infer, constraint, symbol) = constrained_inferred_parameter_nodes(&fixture, "Last");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let inferred = query_node(&mut fixture, infer, &mut diagnostics).unwrap();
        let poison = fixture.store.intrinsic_bootstrap().unwrap().number_type;
        assert!(fixture.store.set_type_parameter_resolution(
            inferred,
            Some(poison),
            None,
            None,
            None,
        ));

        let before = (
            store_state(&fixture.store),
            fixture.store.declared_type_links(symbol).cloned(),
            fixture.store.type_node_links(constraint).cloned(),
            diagnostics.clone(),
        );
        for _ in 0..2 {
            assert_eq!(
                query_node(&mut fixture, infer, &mut diagnostics),
                Err(type_node_unavailable(
                    TypeNodeUnavailable::InvalidTypeReference(infer)
                )),
            );
            assert_eq!(
                (
                    store_state(&fixture.store),
                    fixture.store.declared_type_links(symbol).cloned(),
                    fixture.store.type_node_links(constraint).cloned(),
                    diagnostics.clone(),
                ),
                before,
            );
        }
    }

    #[test]
    fn inferred_parameter_rejects_non_fixed_tuple_constraints_without_writes() {
        for (source, expected_kind) in [
            (
                "type Capture<T> = T extends infer Last extends string ? Last : never;",
                SyntaxKind::StringKeyword,
            ),
            (
                "type Capture<T> = T extends infer Last extends [any?] ? Last : never;",
                SyntaxKind::OptionalType,
            ),
            (
                "type Capture<T> = T extends infer Last extends [...any[]] ? Last : never;",
                SyntaxKind::RestType,
            ),
        ] {
            let mut fixture = fixture(source);
            let (infer, _, _) = constrained_inferred_parameter_nodes(&fixture, "Last");
            let before = store_state(&fixture.store);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            assert!(matches!(
                query_node(&mut fixture, infer, &mut diagnostics),
                Err(DeclaredTypeError::TypeNodeUnavailable(
                    TypeNodeUnavailable::UnsupportedSyntax { kind, .. }
                )) if kind == expected_kind
            ));
            assert_eq!(store_state(&fixture.store), before);
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn tuple_wrapped_any_conditional_uses_only_the_true_branch() {
        let mut fixture = fixture(concat!(
            "type Naked = any extends number ? 1 : 0; ",
            "type Wrapped = [any] extends [number] ? 1 : 0; ",
            "type Expected = 1;",
        ));
        let naked = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Naked");
        let wrapped = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Wrapped");
        let expected = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Expected");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let one = query_declared(
            &mut fixture,
            expected,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let naked_type = query_declared(
            &mut fixture,
            naked,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let TypeData::Union(union) = fixture.store.type_payload(naked_type).unwrap().data() else {
            panic!("a naked any conditional must retain both branches")
        };
        assert_eq!(union.union.types.len(), 2);
        assert!(union.union.types.contains(&one));
        assert_eq!(
            query_declared(
                &mut fixture,
                wrapped,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(one),
        );
        assert!(diagnostics.is_empty());
    }

