    #[test]
    fn recursive_indexed_aliases_reject_poisoned_warm_node_identities() {
        let mut fixture = fixture(concat!(
            "type Recursive = Box<'value', Recursive['item']>; ",
            "interface Box<Value, Result> { item: Value; result: Result; }",
        ));
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Recursive");
        let (_, _, reference) = alias_parts(&fixture, "Recursive");
        let (error_type, number) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.error_type, bootstrap.number_type)
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(error_type),
        );
        let original = fixture.store.type_node_links(reference).unwrap().clone();
        assert!(fixture.store.set_type_node_links(
            reference,
            TypeNodeLinks {
                resolved_type: Some(number),
                ..original.clone()
            },
        ));
        let poisoned = store_state(&fixture.store);

        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidIndexedAccessType(reference),
            )),
        );
        assert_eq!(store_state(&fixture.store), poisoned);

        assert!(fixture.store.set_type_node_links(reference, original));
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(error_type),
        );
        assert_eq!(diagnostics.len(), 1);
    }

    #[test]
    fn generic_builtin_iterator_return_accepts_its_marker_seed_on_retry() {
        for strict in [false, true] {
            let mut fixture = fixture("type BuiltinIteratorReturn<T> = intrinsic;");
            let alias = named_symbol(
                &fixture,
                SyntaxKind::TypeAliasDeclaration,
                "BuiltinIteratorReturn",
            );
            let (expected, marker) = {
                let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
                (
                    if strict {
                        bootstrap.undefined_type
                    } else {
                        bootstrap.any_type
                    },
                    bootstrap.intrinsic_marker_type,
                )
            };
            let options = CanonicalTypeQueryOptions {
                strict_builtin_iterator_return: strict,
                ..CanonicalTypeQueryOptions::default()
            };
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            assert_eq!(
                query_declared(&mut fixture, alias, options, &mut diagnostics),
                Ok(expected)
            );
            assert_eq!(
                query_declared(&mut fixture, alias, options, &mut diagnostics),
                Ok(expected)
            );

            let links = fixture.store.type_alias_links(alias).unwrap();
            let parameters = links.type_parameters.as_deref().unwrap();
            assert_eq!(parameters.len(), 1);
            assert_eq!(links.declared_type, Some(expected));
            assert_eq!(
                links
                    .instantiations
                    .as_ref()
                    .unwrap()
                    .get(&type_list_key(parameters)),
                Some(&marker)
            );
            assert!(diagnostics.is_empty());
        }
    }

