    #[test]
    fn source_generic_class_defaults_forward_earlier_parameters_and_replay_warm() {
        let mut fixture = fixture(concat!(
            "declare class Model<Attrs extends {} = any, Create extends {} = Attrs> {} ",
            "interface Payload { value: string; } ",
            "let defaults: Model; ",
            "let forwarded: Model<Payload>; ",
            "let explicit: Model<Payload, Payload>; ",
            "type Wrapped = Model<Payload>;",
        ));
        let owner = named_symbol(&fixture, SyntaxKind::ClassDeclaration, "Model");
        let payload = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Payload");
        let wrapped = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Wrapped");
        let defaults = variable_type_node(&fixture, "defaults");
        let forwarded = variable_type_node(&fixture, "forwarded");
        let explicit = variable_type_node(&fixture, "explicit");
        let any = fixture.store.intrinsic_bootstrap().unwrap().any_type;
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let defaults_type = query_node(&mut fixture, defaults, &mut diagnostics).unwrap();
        let forwarded_type = query_node(&mut fixture, forwarded, &mut diagnostics).unwrap();
        assert_eq!(
            query_node(&mut fixture, explicit, &mut diagnostics),
            Ok(forwarded_type),
        );
        assert_eq!(
            query_declared(
                &mut fixture,
                wrapped,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(forwarded_type),
        );

        let payload_type = fixture
            .store
            .declared_type_links(payload)
            .and_then(|links| links.declared_type)
            .unwrap();
        let target = fixture
            .store
            .declared_type_links(owner)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_eq!(
            validate_direct_generic_reference(&fixture.store, defaults_type)
                .unwrap()
                .type_arguments,
            [any, any],
        );
        assert_eq!(
            validate_direct_generic_reference(&fixture.store, forwarded_type)
                .unwrap()
                .type_arguments,
            [payload_type, payload_type],
        );
        let parameters = validate_direct_generic_reference(&fixture.store, target)
            .unwrap()
            .type_arguments;
        let parameter_default =
            |parameter| match fixture.store.type_payload(parameter).unwrap().data() {
                TypeData::TypeParameter(parameter) => parameter.resolved_default_type,
                _ => panic!("the class must retain its declaration-owned parameters"),
            };
        assert_eq!(parameter_default(parameters[0]), Some(any));
        assert_eq!(parameter_default(parameters[1]), Some(parameters[0]));

        let warm = store_state(&fixture.store);
        for (node, expected) in [
            (defaults, defaults_type),
            (forwarded, forwarded_type),
            (explicit, forwarded_type),
        ] {
            assert_eq!(
                query_node(&mut fixture, node, &mut diagnostics),
                Ok(expected)
            );
        }
        assert_eq!(
            query_declared(
                &mut fixture,
                wrapped,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(forwarded_type),
        );
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());

        let TypeData::TypeParameter(second) =
            fixture.store.type_payload(parameters[1]).unwrap().data()
        else {
            panic!("the second class parameter must remain canonical")
        };
        let constraint = second.constraint;
        assert!(fixture.store.set_type_parameter_resolution(
            parameters[1],
            constraint,
            None,
            None,
            Some(any),
        ));
        let poisoned = store_state(&fixture.store);
        assert_eq!(
            query_node(&mut fixture, forwarded, &mut diagnostics),
            Err(type_node_unavailable(
                TypeNodeUnavailable::InvalidTypeReference(forwarded),
            )),
        );
        assert_eq!(store_state(&fixture.store), poisoned);
        assert!(fixture.store.set_type_parameter_resolution(
            parameters[1],
            constraint,
            None,
            None,
            Some(parameters[0]),
        ));
        assert_eq!(
            query_node(&mut fixture, forwarded, &mut diagnostics),
            Ok(forwarded_type),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn direct_generic_interface_references_use_real_iterable_library_defaults() {
        let library = parse_source_file(include_str!(
            "../../../ts_bundled/libs/lib.es2015.iterable.d.ts"
        ));
        let source = parse_source_file(concat!(
            "let explicit: Iterable<number, string, undefined>; ",
            "let second: Iterable<string, void, number>; ",
            "let defaults: Iterable<number>; ",
            "let partial: Iterable<number, string>; ",
            "let iterator: Iterator<number>;",
        ));
        let (mut context, library_file, source_file) =
            default_library_interface_context(&library, &source, true);
        let nodes = source
            .arena
            .iter()
            .filter_map(|(_, record)| {
                let NodeData::VariableDeclaration(variable) = &record.data else {
                    return None;
                };
                Some((
                    identifier_text(&source.arena, variable.name)?.to_owned(),
                    NodeRef::new(source.arena.id(), source_file, variable.type_?),
                ))
            })
            .collect::<BTreeMap<_, _>>();
        let (any, string, number, undefined, void) = {
            let bootstrap = context.store().intrinsic_bootstrap().unwrap();
            (
                bootstrap.any_type,
                bootstrap.string_type,
                bootstrap.number_type,
                bootstrap.undefined_type,
                bootstrap.void_type,
            )
        };
        let mut resolved = Vec::new();
        for (name, arguments) in [
            ("explicit", [number, string, undefined]),
            ("second", [string, void, number]),
            ("defaults", [number, any, any]),
            ("partial", [number, string, any]),
            ("iterator", [number, any, any]),
        ] {
            let node = nodes[name];
            let type_ = context.get_type_from_type_node(node).unwrap();
            let reference = validate_direct_generic_reference(context.store(), type_).unwrap();
            assert_eq!(reference.type_arguments, arguments, "reference: {name}");
            let target = context.store().type_payload(reference.target).unwrap();
            let owner = context.store().symbol(target.symbol().unwrap()).unwrap();
            assert_eq!(owner.declarations().unwrap()[0].file, library_file);
            let TypeData::Interface(interface) = target.data() else {
                panic!("the library reference must retain its interface target")
            };
            assert!(!interface.declared_members_resolved);
            let parameters = interface
                .reference
                .resolved_type_arguments
                .as_ref()
                .unwrap();
            for parameter in &parameters[1..] {
                let TypeData::TypeParameter(parameter) =
                    context.store().type_payload(*parameter).unwrap().data()
                else {
                    panic!("the target must retain its declaration-owned parameter")
                };
                assert_eq!(
                    parameter.resolved_default_type,
                    (!matches!(name, "explicit" | "second")).then_some(any),
                );
            }
            resolved.push((node, type_));
        }
        assert!(context.diagnostics().is_empty());

        let warm = store_state(context.store());
        for (node, expected) in resolved {
            assert_eq!(context.get_type_from_type_node(node), Ok(expected));
        }
        assert_eq!(store_state(context.store()), warm);
        assert!(context.diagnostics().is_empty());
    }

    #[test]
    fn direct_generic_interface_defaults_forward_parameters_without_library_name_rules() {
        let library = parse_source_file(concat!(
            "interface Channel<Value = number[], Result = unknown, Next = Value> {} ",
            "interface Empty<Value = {}> {} ",
            "interface Scalar<Value = string, Other = number, Last = undefined> {}",
        ));
        let source = parse_source_file(concat!(
            "let channel: Channel<string>; ",
            "let explicit: Channel<string, unknown, string>; ",
            "let empty: Empty; ",
            "let scalar: Scalar;",
        ));
        let (mut context, _, source_file) =
            default_library_interface_context(&library, &source, false);
        let nodes = source
            .arena
            .iter()
            .filter_map(|(_, record)| {
                let NodeData::VariableDeclaration(variable) = &record.data else {
                    return None;
                };
                Some((
                    identifier_text(&source.arena, variable.name)?.to_owned(),
                    NodeRef::new(source.arena.id(), source_file, variable.type_?),
                ))
            })
            .collect::<BTreeMap<_, _>>();
        let (unknown, string, number, undefined, empty) = {
            let bootstrap = context.store().intrinsic_bootstrap().unwrap();
            (
                bootstrap.unknown_type,
                bootstrap.string_type,
                bootstrap.number_type,
                bootstrap.undefined_type,
                bootstrap.empty_type_literal_type,
            )
        };
        let channel = context.get_type_from_type_node(nodes["channel"]).unwrap();
        assert_eq!(
            context.get_type_from_type_node(nodes["explicit"]),
            Ok(channel),
        );
        assert_eq!(
            validate_direct_generic_reference(context.store(), channel)
                .unwrap()
                .type_arguments,
            [string, unknown, string],
        );
        let empty_type = context.get_type_from_type_node(nodes["empty"]).unwrap();
        assert_eq!(
            validate_direct_generic_reference(context.store(), empty_type)
                .unwrap()
                .type_arguments,
            [empty],
        );
        let scalar = context.get_type_from_type_node(nodes["scalar"]).unwrap();
        assert_eq!(
            validate_direct_generic_reference(context.store(), scalar)
                .unwrap()
                .type_arguments,
            [string, number, undefined],
        );
        let warm = store_state(context.store());
        assert_eq!(
            context.get_type_from_type_node(nodes["channel"]),
            Ok(channel)
        );
        assert_eq!(
            context.get_type_from_type_node(nodes["empty"]),
            Ok(empty_type)
        );
        assert_eq!(context.get_type_from_type_node(nodes["scalar"]), Ok(scalar));
        assert_eq!(store_state(context.store()), warm);
        assert!(context.diagnostics().is_empty());
    }

