    #[test]
    #[allow(clippy::too_many_lines)] // Factory alias ownership, optional/rest syntax, and warm poison form one proof.
    fn ambient_react_html_factory_alias_heritage_remains_authenticated_and_lazy() {
        let mut fixture = fixture(concat!(
            "declare module 'react' { ",
            "export = React; ",
            "namespace React { ",
            "type ReactNode = string; ",
            "type DOMFactory<P, T> = (props?: P, ...children: ReactNode[]) => T; ",
            "interface DetailedHTMLFactory<P, T> extends DOMFactory<P, T> { ",
            "(props?: P, ...children: ReactNode[]): T; ",
            "} } }",
        ));
        let factory = named_symbol(
            &fixture,
            SyntaxKind::InterfaceDeclaration,
            "DetailedHTMLFactory",
        );
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "DOMFactory");
        let namespace = fixture.store.get_parent_of_symbol(factory).unwrap();
        let exports = fixture.store.symbol(namespace).unwrap().exports().unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let target = query_declared(
            &mut fixture,
            factory,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let TypeData::Interface(interface) = fixture.store.type_payload(target).unwrap().data()
        else {
            panic!("DetailedHTMLFactory must retain its canonical generic interface")
        };
        assert!(!interface.base_types_resolved);
        assert!(interface.resolved_base_types.is_none());
        assert!(!interface.declared_members_resolved);
        assert!(fixture.store.type_alias_links(alias).is_none());
        let call = fixture
            .store
            .symbol(factory)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| fixture.store.symbol_table(members))
            .and_then(|members| members.get(InternalSymbolName::Call.as_ref()))
            .unwrap();
        assert!(fixture.store.value_symbol_links(call).is_none());

        let warm = store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                factory,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(target),
        );
        assert_eq!(store_state(&fixture.store), warm);

        assert_eq!(
            fixture
                .store
                .insert_symbol(exports, EscapedName::source("DOMFactory"), factory),
            Some(Some(alias)),
        );
        let poisoned = store_state(&fixture.store);
        assert!(
            query_declared(
                &mut fixture,
                factory,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .is_err(),
        );
        assert_eq!(store_state(&fixture.store), poisoned);
        assert_eq!(
            fixture
                .store
                .insert_symbol(exports, EscapedName::source("DOMFactory"), alias),
            Some(Some(factory)),
        );

        assert!(
            fixture
                .store
                .set_interface_base_resolution(target, true, None, None),
        );
        let poisoned = store_state(&fixture.store);
        assert!(
            query_declared(
                &mut fixture,
                factory,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .is_err(),
        );
        assert_eq!(store_state(&fixture.store), poisoned);
        assert!(
            fixture
                .store
                .set_interface_base_resolution(target, false, None, None),
        );
        assert_eq!(
            query_declared(
                &mut fixture,
                factory,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(target),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // SVG alias ownership, cold DOM arguments, and poisoned exports share one proof.
    fn ambient_react_svg_factory_alias_heritage_remains_authenticated_and_lazy() {
        let library = parse_source_file(concat!(
            "interface Element { self: this; } declare var Element: unknown; ",
            "interface SVGElement extends Element { ",
            "addEventListener<Value extends string>(type: Value): void; ",
            "} declare var SVGElement: unknown;",
        ));
        let react = parse_source_file(concat!(
            "declare module 'react' { export = React; namespace React { ",
            "interface DOMAttributes<T> {} ",
            "interface SVGAttributes<T> extends DOMAttributes<T> {} ",
            "interface ClassAttributes<T> {} interface ReactSVGElement {} ",
            "type ReactNode = unknown; ",
            "type DOMFactory<P, T> = ",
            "(props?: ClassAttributes<T> & P | null, ...children: ReactNode[]) => ReactSVGElement; ",
            "interface SVGFactory extends DOMFactory<SVGAttributes<SVGElement>, SVGElement> { ",
            "(props?: ClassAttributes<SVGElement> & SVGAttributes<SVGElement> | null, ",
            "...children: ReactNode[]): ReactSVGElement; } ",
            "interface ReactSVG { animate: SVGFactory; circle: SVGFactory; } ",
            "} }",
        ));
        let (mut context, library_file, react_file) =
            default_library_interface_context(&library, &react, true);
        let library_bound = context.file(library_file).unwrap().1.clone();
        let react_bound = context.file(react_file).unwrap().1.clone();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, &library_bound),
                (&react.arena, &react_bound),
            ],
            GlobalMergeCompletion::for_test(context.options().name_resolution),
        )
        .unwrap();
        let globals = context.store().intrinsic_bootstrap().unwrap().globals;
        let svg = context
            .store()
            .symbol_table(globals)
            .and_then(|globals| globals.get_source("SVGElement"))
            .unwrap();
        let element = context
            .store()
            .symbol_table(globals)
            .and_then(|globals| globals.get_source("Element"))
            .unwrap();
        let references = react_dom_type_references(&react, react_file, "SVGElement");
        let aliases = HashMap::new();
        for reference in &references {
            assert!(
                TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                    .is_default_library_dom_interface_argument(*reference, svg)
            );
        }
        let animate = react_dom_property_annotation(&react, react_file, "animate");
        let circle = react_dom_property_annotation(&react, react_file, "circle");
        let resolved = context.get_type_from_type_node(animate).unwrap();
        assert_eq!(context.get_type_from_type_node(circle), Ok(resolved));
        let factory = context
            .store()
            .symbol_node_links(animate)
            .and_then(|links| links.resolved_symbol)
            .unwrap();
        let namespace = context.store().get_parent_of_symbol(factory).unwrap();
        let exports = context
            .store()
            .symbol(namespace)
            .unwrap()
            .exports()
            .unwrap();
        let dom_factory = context
            .store()
            .symbol_table(exports)
            .and_then(|exports| exports.get_source("DOMFactory"))
            .unwrap();
        let attributes = context
            .store()
            .symbol_table(exports)
            .and_then(|exports| exports.get_source("SVGAttributes"))
            .unwrap();
        let record = context.store().type_payload(resolved).unwrap();
        let TypeData::Interface(interface) = record.data() else {
            panic!("SVGFactory must retain its canonical interface identity")
        };
        assert_eq!(record.symbol(), Some(factory));
        assert!(!interface.base_types_resolved);
        assert!(!interface.declared_members_resolved);
        assert!(interface.resolved_base_types.is_none());
        assert!(context.store().type_alias_links(dom_factory).is_none());
        assert!(context.store().declared_type_links(svg).is_none());
        let signature = context
            .store()
            .symbol(factory)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| context.store().symbol_table(members))
            .and_then(|members| members.get(InternalSymbolName::Call.as_ref()))
            .unwrap();
        assert!(context.store().value_symbol_links(signature).is_none());

        let warm = store_state(context.store());
        assert_eq!(context.get_type_from_type_node(animate), Ok(resolved));
        assert_eq!(context.get_type_from_type_node(circle), Ok(resolved));
        assert_eq!(context.get_declared_type_of_symbol(factory), Ok(resolved));
        assert_eq!(store_state(context.store()), warm);

        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("DOMFactory"),
                attributes,
            ),
            Some(Some(dom_factory)),
        );
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(animate).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("DOMFactory"),
                dom_factory,
            ),
            Some(Some(attributes)),
        );

        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("SVGAttributes"),
                factory,
            ),
            Some(Some(attributes)),
        );
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(animate).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("SVGAttributes"),
                attributes,
            ),
            Some(Some(factory)),
        );

        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                globals,
                EscapedName::source("SVGElement"),
                element,
            ),
            Some(Some(svg)),
        );
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(animate).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                globals,
                EscapedName::source("SVGElement"),
                svg,
            ),
            Some(Some(element)),
        );
        assert_eq!(context.get_type_from_type_node(animate), Ok(resolved));
    }

    #[test]
    fn react_generic_heritage_rejects_forged_exports_and_poisoned_warm_bases() {
        let mut fixture = fixture(concat!(
            "declare namespace React { ",
            "interface Attributes { key: string; } ",
            "interface ClassAttributes<T> extends Attributes { ref: T; } ",
            "}",
        ));
        let attributes = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Attributes");
        let class = named_symbol(
            &fixture,
            SyntaxKind::InterfaceDeclaration,
            "ClassAttributes",
        );
        let namespace = fixture.store.get_parent_of_symbol(class).unwrap();
        let exports = fixture.store.symbol(namespace).unwrap().exports().unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let target = query_declared(
            &mut fixture,
            class,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let original = fixture
            .store
            .type_payload(target)
            .and_then(|record| match record.data() {
                TypeData::Interface(interface) => interface.resolved_base_types.clone(),
                _ => None,
            })
            .unwrap();

        for (name, replacement, expected) in [
            ("ClassAttributes", attributes, class),
            ("Attributes", class, attributes),
        ] {
            assert_eq!(
                fixture
                    .store
                    .insert_symbol(exports, EscapedName::source(name), replacement),
                Some(Some(expected)),
            );
            let poisoned = store_state(&fixture.store);
            assert!(
                query_declared(
                    &mut fixture,
                    class,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .is_err(),
            );
            assert_eq!(store_state(&fixture.store), poisoned);
            assert_eq!(
                fixture
                    .store
                    .insert_symbol(exports, EscapedName::source(name), expected),
                Some(Some(replacement)),
            );
        }

        let wrong = fixture.store.intrinsic_bootstrap().unwrap().number_type;
        assert!(
            fixture
                .store
                .set_interface_base_resolution(target, true, None, Some(vec![wrong])),
        );
        let poisoned = store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                class,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(DeclaredTypeError::Unavailable(
                DeclaredTypeUnavailable::InvalidCachedDeclaredType {
                    symbol: class,
                    declared_type: target,
                },
            )),
        );
        assert_eq!(store_state(&fixture.store), poisoned);
        assert!(
            fixture
                .store
                .set_interface_base_resolution(target, true, None, Some(original),)
        );
        assert_eq!(
            query_declared(
                &mut fixture,
                class,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(target),
        );
        assert!(diagnostics.is_empty());
    }

