    #[test]
    fn poisoned_generic_heritage_and_cycles_fail_before_additional_writes() {
        let mut inherited = fixture(concat!(
            "interface Base<Value> { inherited: Value; } ",
            "interface Derived<Value> extends Base<Value> { own: Value; }",
        ));
        let derived = named_symbol(&inherited, SyntaxKind::InterfaceDeclaration, "Derived");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let target = query_declared(
            &mut inherited,
            derived,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let original = inherited
            .store
            .type_payload(target)
            .and_then(|record| match record.data() {
                TypeData::Interface(interface) => interface.resolved_base_types.clone(),
                _ => None,
            })
            .unwrap();
        assert!(
            inherited
                .store
                .set_interface_base_resolution(target, true, None, None)
        );
        let poisoned = store_state(&inherited.store);

        assert_eq!(
            query_declared(
                &mut inherited,
                derived,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(DeclaredTypeError::Unavailable(
                DeclaredTypeUnavailable::InvalidCachedDeclaredType {
                    symbol: derived,
                    declared_type: target,
                },
            )),
        );
        assert_eq!(store_state(&inherited.store), poisoned);
        assert!(
            inherited
                .store
                .set_interface_base_resolution(target, true, None, Some(original),)
        );

        let mut cycle = fixture(concat!(
            "interface Left<Value> extends Right<Value> {} ",
            "interface Right<Value> extends Left<Value> {}",
        ));
        let left = named_symbol(&cycle, SyntaxKind::InterfaceDeclaration, "Left");
        let before = store_state(&cycle.store);
        assert!(
            query_declared(
                &mut cycle,
                left,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .is_err(),
        );
        assert_eq!(store_state(&cycle.store), before);
    }

    #[test]
    fn keyof_reopened_interfaces_includes_inherited_property_symbols() {
        let mut fixture = fixture(concat!(
            "interface Base { inherited: string; } ",
            "interface Derived { first: number; } ",
            "interface Derived extends Base { second: boolean; } ",
            "type Keys = keyof Derived;",
        ));
        let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Keys");
        let base = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Base");
        let derived = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Derived");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let keys = query_declared(
            &mut fixture,
            alias,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let TypeData::Union(union) = fixture.store.type_payload(keys).unwrap().data() else {
            panic!("three declared property keys must retain a literal union")
        };
        let mut names = union
            .union
            .types
            .iter()
            .map(
                |key| match fixture.store.type_payload(*key).unwrap().data() {
                    TypeData::Literal(literal) => match &literal.value {
                        LiteralValue::String(value) => value.as_str(),
                        _ => panic!("interface keys must remain string literals"),
                    },
                    _ => panic!("interface keys must remain string literals"),
                },
            )
            .collect::<Vec<_>>();
        names.sort_unstable();
        assert_eq!(names, ["first", "inherited", "second"]);

        let derived_type = fixture
            .store
            .declared_type_links(derived)
            .and_then(|links| links.declared_type)
            .unwrap();
        let inherited = fixture
            .store
            .type_payload(derived_type)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.properties.as_deref())
            .and_then(|properties| properties.last())
            .copied()
            .unwrap();
        assert_eq!(fixture.store.get_parent_of_symbol(inherited), Some(base));

        let warm = store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(keys),
        );
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn callable_interface_heritage_keeps_derived_signatures_before_base_signatures() {
        let mut fixture = fixture(concat!(
            "interface Base { (): string; } ",
            "interface Derived extends Base { (value: string): string; } ",
            "let value: Derived;",
        ));
        let base = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Base");
        let derived = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Derived");
        let annotation = variable_type_node(&fixture, "value");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let derived_type = query_node(&mut fixture, annotation, &mut diagnostics).unwrap();
        let base_type = fixture
            .store
            .declared_type_links(base)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_eq!(
            fixture
                .store
                .declared_type_links(derived)
                .and_then(|links| links.declared_type),
            Some(derived_type),
        );
        let TypeData::Interface(base_interface) =
            fixture.store.type_payload(base_type).unwrap().data()
        else {
            panic!("the base must retain its interface identity")
        };
        let [base_signature] = base_interface.declared_call_signatures.as_deref().unwrap() else {
            panic!("the base must own one call signature")
        };
        let TypeData::Interface(derived_interface) =
            fixture.store.type_payload(derived_type).unwrap().data()
        else {
            panic!("the derived type must retain its interface identity")
        };
        let [declared_signature] = derived_interface
            .declared_call_signatures
            .as_deref()
            .unwrap()
        else {
            panic!("the derived declaration must own one call signature")
        };
        assert_eq!(
            derived_interface
                .reference
                .object
                .structured
                .signatures
                .as_deref(),
            Some(&[*declared_signature, *base_signature][..]),
        );
        assert_eq!(
            derived_interface
                .reference
                .object
                .structured
                .call_signature_count,
            2,
        );

        let warm = (
            store_state(&fixture.store),
            fixture.store.signature_len(),
            diagnostics.clone(),
        );
        assert_eq!(
            query_node(&mut fixture, annotation, &mut diagnostics),
            Ok(derived_type),
        );
        assert_eq!(
            (
                store_state(&fixture.store),
                fixture.store.signature_len(),
                diagnostics.clone(),
            ),
            warm,
        );
    }

    #[test]
    fn default_library_interface_bases_keep_source_and_dom_members_cold() {
        let library = parse_source_file(concat!(
            "interface DomRoot { inherited: string; } ",
            "interface DomExtra {} ",
            "interface DomMore {} ",
            "interface HTMLElement extends DomRoot, DomExtra, DomMore { ",
            "self: this; addEventListener(value: string): void; } ",
            "declare var HTMLElement: unknown;",
        ));
        let source = parse_source_file(concat!(
            "interface HTMLWebViewElement extends HTMLElement {} ",
            "type View = HTMLWebViewElement;",
        ));
        let (mut context, _, source_file) =
            default_library_interface_context(&library, &source, true);
        let globals = context.store().intrinsic_bootstrap().unwrap().globals;
        let base = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("HTMLElement"))
            .unwrap();
        let root = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("DomRoot"))
            .unwrap();
        let derived = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("HTMLWebViewElement"))
            .unwrap();
        let members = context.store().symbol(base).unwrap().members().unwrap();
        let method = context
            .store()
            .symbol_table(members)
            .and_then(|members| members.get_source("addEventListener"))
            .unwrap();
        let reference = source
            .arena
            .iter()
            .find_map(|(_, record)| match &record.data {
                NodeData::TypeAliasDeclaration(alias)
                    if identifier_text(&source.arena, alias.name) == Some("View") =>
                {
                    Some(NodeRef::new(source.arena.id(), source_file, alias.type_))
                }
                _ => None,
            })
            .unwrap();

        let derived_type = context.get_declared_type_of_symbol(derived).unwrap();
        let base_type = context
            .store()
            .declared_type_links(base)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_ne!(derived_type, base_type);
        assert!(context.store().declared_type_links(root).is_none());
        assert!(context.store().value_symbol_links(method).is_none());
        for (symbol, type_) in [(derived, derived_type), (base, base_type)] {
            let record = context.store().type_payload(type_).unwrap();
            let TypeData::Interface(interface) = record.data() else {
                panic!("an authenticated interface must retain its declared identity")
            };
            assert_eq!(record.symbol(), Some(symbol));
            assert!(!interface.base_types_resolved);
            assert!(!interface.declared_members_resolved);
            assert!(interface.resolved_base_types.is_none());
            assert!(interface.reference.object.structured.properties.is_none());
            assert!(interface.reference.object.structured.signatures.is_none());
            assert!(
                context
                    .store()
                    .direct_interface_heritage_provenance(type_)
                    .is_none()
            );
        }

        assert_eq!(context.get_type_from_type_node(reference), Ok(derived_type));
        let warm = (
            store_state(context.store()),
            context.store().signature_len(),
            context.store().index_info_len(),
        );
        assert_eq!(
            context.get_declared_type_of_symbol(derived),
            Ok(derived_type)
        );
        assert_eq!(context.get_type_from_type_node(reference), Ok(derived_type));
        assert_eq!(
            (
                store_state(context.store()),
                context.store().signature_len(),
                context.store().index_info_len(),
            ),
            warm,
        );
        assert!(context.diagnostics().is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // DOM roots, native method caches, and library rejection share one proof.
    fn default_library_dom_root_arguments_keep_multibase_heritage_cold() {
        let library = parse_source_file(concat!(
            "interface DomRoot {} interface DomExtra {} interface DomMore {} ",
            "interface Element extends DomRoot, DomExtra, DomMore { ",
            "self: this; native(value: string): void; } ",
            "declare var Element: unknown; ",
            "interface HTMLElement extends Element, DomExtra, DomMore {} ",
            "declare var HTMLElement: unknown; ",
            "interface SVGElement extends Element, DomExtra, DomMore {} ",
            "declare var SVGElement: unknown; ",
            "interface Document extends DomRoot, DomExtra, DomMore { self: this; } ",
            "declare var Document: unknown; ",
            "interface Event { stopPropagation(): void; } ",
            "declare var Event: unknown; ",
            "interface EventTarget { ",
            "addEventListener(type: string, callback: Event | null, options?: boolean): void; ",
            "dispatchEvent(event: Event): boolean; ",
            "} declare var EventTarget: unknown; ",
            "interface DataTransfer { ",
            "clearData(format?: string): void; ",
            "setData(format: string, data: string): void; ",
            "} declare var DataTransfer: unknown;",
        ));
        let source = parse_source_file(concat!(
            "interface Box<Value> {} ",
            "type Root = Box<Element>; ",
            "type Html = Box<HTMLElement>; ",
            "type Svg = Box<SVGElement>; ",
            "type DomDocument = Box<Document>; ",
            "type NativeEvent = Box<Event>; ",
            "type EventReceiver = Box<EventTarget>; ",
            "type ClipboardData = Box<DataTransfer>; ",
            "interface AbstractView { ",
            "document: Document; event: Event; target: EventTarget; ",
            "clipboardData: DataTransfer; ",
            "}",
        ));

        for is_default_library in [false, true] {
            let (mut context, _, _) =
                default_library_interface_context(&library, &source, is_default_library);
            let globals = context.store().intrinsic_bootstrap().unwrap().globals;
            let aliases = [
                ("Root", "Element"),
                ("Html", "HTMLElement"),
                ("Svg", "SVGElement"),
                ("DomDocument", "Document"),
                ("NativeEvent", "Event"),
                ("EventReceiver", "EventTarget"),
                ("ClipboardData", "DataTransfer"),
            ]
            .map(|(alias, element)| {
                let symbols = context.store().symbol_table(globals).unwrap();
                (
                    symbols.get_source(alias).unwrap(),
                    symbols.get_source(element).unwrap(),
                )
            });

            if !is_default_library {
                let before = store_state(context.store());
                assert!(context.get_declared_type_of_symbol(aliases[0].0).is_err());
                assert_eq!(store_state(context.store()), before);
                continue;
            }

            let native_methods = [
                ("Event", "stopPropagation"),
                ("EventTarget", "addEventListener"),
                ("EventTarget", "dispatchEvent"),
                ("DataTransfer", "clearData"),
                ("DataTransfer", "setData"),
            ]
            .map(|(owner, name)| {
                context
                    .store()
                    .symbol_table(globals)
                    .and_then(|globals| globals.get_source(owner))
                    .and_then(|owner| context.store().symbol(owner))
                    .and_then(ts_binder::semantic::Symbol::members)
                    .and_then(|members| context.store().symbol_table(members))
                    .and_then(|members| members.get_source(name))
                    .unwrap()
            });

            let mut resolved = Vec::new();
            for (alias, element) in aliases {
                let type_ = context.get_declared_type_of_symbol(alias).unwrap();
                let reference = validate_direct_generic_reference(context.store(), type_).unwrap();
                let expected = context
                    .store()
                    .declared_type_links(element)
                    .and_then(|links| links.declared_type)
                    .unwrap();
                assert_eq!(reference.type_arguments, [expected]);
                let TypeData::Interface(interface) =
                    context.store().type_payload(expected).unwrap().data()
                else {
                    panic!("DOM roots must retain their authenticated interface identity")
                };
                assert!(!interface.base_types_resolved);
                assert!(!interface.declared_members_resolved);
                resolved.push((alias, type_));
            }

            let view = context
                .store()
                .symbol_table(globals)
                .and_then(|symbols| symbols.get_source("AbstractView"))
                .unwrap();
            context.get_declared_type_of_symbol(view).unwrap();
            for (name, root) in [
                ("document", "Document"),
                ("event", "Event"),
                ("target", "EventTarget"),
                ("clipboardData", "DataTransfer"),
            ] {
                let expected = context
                    .store()
                    .symbol_table(globals)
                    .and_then(|symbols| symbols.get_source(root))
                    .and_then(|symbol| context.store().declared_type_links(symbol))
                    .and_then(|links| links.declared_type)
                    .unwrap();
                let property = context
                    .store()
                    .symbol(view)
                    .and_then(ts_binder::semantic::Symbol::members)
                    .and_then(|members| context.store().symbol_table(members))
                    .and_then(|members| members.get_source(name))
                    .unwrap();
                assert_eq!(
                    context
                        .store()
                        .value_symbol_links(property)
                        .and_then(|links| links.resolved_type),
                    Some(expected),
                );
            }
            assert!(native_methods.iter().all(|method| {
                context.store().value_symbol_links(*method).is_none()
                    && context
                        .store()
                        .symbol(*method)
                        .and_then(ts_binder::semantic::Symbol::value_declaration)
                        .is_some_and(|declaration| {
                            context.store().signature_links(declaration).is_none()
                        })
            }));

            let warm = store_state(context.store());
            for (alias, expected) in resolved {
                assert_eq!(context.get_declared_type_of_symbol(alias), Ok(expected));
            }
            context.get_declared_type_of_symbol(view).unwrap();
            assert_eq!(store_state(context.store()), warm);
            assert!(context.diagnostics().is_empty());
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Factory arguments, lazy DOM methods, and poisoned exports share one proof.
    fn react_html_factory_arguments_keep_default_library_element_methods_lazy() {
        let library = parse_source_file(concat!(
            "interface HTMLElement { self: this; } ",
            "declare var HTMLElement: unknown; ",
            "interface HTMLHyperlinkElementUtils { href: string; } ",
            "interface HTMLAnchorElement extends HTMLElement, HTMLHyperlinkElementUtils { ",
            "addEventListener<Value extends string>(type: Value): void; ",
            "} declare var HTMLAnchorElement: unknown; ",
            "interface HTMLHeadElement extends HTMLElement { ",
            "addEventListener<Value extends string>(type: Value): void; ",
            "} declare var HTMLHeadElement: unknown;",
        ));
        let react = parse_source_file(concat!(
            "declare module 'react' { ",
            "export = React; namespace React { ",
            "interface HTMLAttributes<Value> {} ",
            "interface HTMLAttributes<Value> {} ",
            "interface AnchorHTMLAttributes<Value> extends HTMLAttributes<Value> {} ",
            "interface ClassAttributes<Value> {} ",
            "type ReactNode = unknown; ",
            "type DOMFactory<P, T> = ",
            "(props?: ClassAttributes<T> & P | null, ...children: ReactNode[]) => unknown; ",
            "interface DetailedHTMLFactory<",
            "P extends HTMLAttributes<T>, T extends HTMLElement",
            "> extends DOMFactory<P, T> { ",
            "(props?: ClassAttributes<T> & P | null, ...children: ReactNode[]): unknown; ",
            "} ",
            "interface ReactHTML { ",
            "a: DetailedHTMLFactory<AnchorHTMLAttributes<HTMLAnchorElement>, HTMLAnchorElement>; ",
            "head: DetailedHTMLFactory<HTMLAttributes<HTMLElement>, HTMLHeadElement>; ",
            "} } }",
        ));
        let (mut context, library_file, react_file) =
            default_library_interface_context(&library, &react, true);
        let library_bound = context.file(library_file).unwrap().1.clone();
        let react_bound = context.file(react_file).unwrap().1.clone();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, &library_bound),
                (&react.arena, &react_bound),
            ],
            GlobalMergeCompletion::for_test(context.options().name_resolution),
        )
        .unwrap();
        let globals = context.store().intrinsic_bootstrap().unwrap().globals;
        let anchor = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("HTMLAnchorElement"))
            .unwrap();
        let head = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("HTMLHeadElement"))
            .unwrap();
        let html_element = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("HTMLElement"))
            .unwrap();
        let references = react_dom_type_references(&react, react_file, "HTMLAnchorElement");
        assert_eq!(references.len(), 2);
        let aliases = HashMap::new();
        for reference in &references {
            assert!(
                TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                    .is_default_library_dom_interface_argument(*reference, anchor)
            );
        }

        let annotation = react_dom_property_annotation(&react, react_file, "a");
        let resolved = context.get_type_from_type_node(annotation).unwrap();
        let reference = validate_direct_generic_reference(context.store(), resolved).unwrap();
        let anchor_type = context
            .store()
            .declared_type_links(anchor)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_eq!(reference.type_arguments[1], anchor_type);
        assert_eq!(
            validate_direct_generic_reference(context.store(), reference.type_arguments[0])
                .unwrap()
                .type_arguments,
            [anchor_type],
        );
        let TypeData::Interface(interface) =
            context.store().type_payload(anchor_type).unwrap().data()
        else {
            panic!("the HTML factory must retain the declared DOM element identity")
        };
        assert!(!interface.declared_members_resolved);
        let method = context
            .store()
            .symbol(anchor)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| context.store().symbol_table(members))
            .and_then(|members| members.get_source("addEventListener"))
            .unwrap();
        assert!(context.store().value_symbol_links(method).is_none());

        let head_annotation = react_dom_property_annotation(&react, react_file, "head");
        let head_resolved = context.get_type_from_type_node(head_annotation).unwrap();
        let head_reference =
            validate_direct_generic_reference(context.store(), head_resolved).unwrap();
        let head_type = context
            .store()
            .declared_type_links(head)
            .and_then(|links| links.declared_type)
            .unwrap();
        let html_element_type = context
            .store()
            .declared_type_links(html_element)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_eq!(head_reference.type_arguments[1], head_type);
        assert_eq!(
            validate_direct_generic_reference(context.store(), head_reference.type_arguments[0])
                .unwrap()
                .type_arguments,
            [html_element_type],
        );
        let TypeData::Interface(head_interface) =
            context.store().type_payload(head_type).unwrap().data()
        else {
            panic!("the head factory must retain its exact DOM element identity")
        };
        assert!(!head_interface.declared_members_resolved);
        let head_method = context
            .store()
            .symbol(head)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| context.store().symbol_table(members))
            .and_then(|members| members.get_source("addEventListener"))
            .unwrap();
        assert!(context.store().value_symbol_links(head_method).is_none());

        let warm = store_state(context.store());
        assert_eq!(context.get_type_from_type_node(annotation), Ok(resolved));
        assert_eq!(
            context.get_type_from_type_node(head_annotation),
            Ok(head_resolved),
        );
        assert_eq!(store_state(context.store()), warm);

        let factory = context
            .store()
            .symbol_node_links(annotation)
            .and_then(|links| links.resolved_symbol)
            .unwrap();
        let namespace = context.store().get_parent_of_symbol(factory).unwrap();
        let exports = context
            .store()
            .symbol(namespace)
            .unwrap()
            .exports()
            .unwrap();
        let attributes = context
            .store()
            .symbol_table(exports)
            .and_then(|exports| exports.get_source("AnchorHTMLAttributes"))
            .unwrap();
        let react_html = context
            .store()
            .symbol_table(exports)
            .and_then(|exports| exports.get_source("ReactHTML"))
            .unwrap();
        let factory_property = context
            .store()
            .symbol(react_html)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| context.store().symbol_table(members))
            .and_then(|members| members.get_source("a"))
            .unwrap();
        assert!(
            context
                .store_mut_for_test()
                .set_source_property_readonly(factory_property, true)
        );
        for reference in &references {
            assert!(
                !TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                    .is_default_library_dom_interface_argument(*reference, anchor)
            );
        }
        assert!(
            context
                .store_mut_for_test()
                .set_source_property_readonly(factory_property, false)
        );
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("DetailedHTMLFactory"),
                attributes,
            ),
            Some(Some(factory)),
        );
        for reference in &references {
            assert!(
                !TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                    .is_default_library_dom_interface_argument(*reference, anchor)
            );
        }
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(annotation).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("DetailedHTMLFactory"),
                factory,
            ),
            Some(Some(attributes)),
        );
        assert_eq!(context.get_type_from_type_node(annotation), Ok(resolved));

        let NodeData::TypeReferenceNode(factory_reference) =
            &react.arena.get(head_annotation.node).unwrap().data
        else {
            panic!("the head property must retain its factory reference")
        };
        let attributes = NodeRef::new(
            head_annotation.arena,
            head_annotation.file,
            factory_reference.type_arguments.as_ref().unwrap().nodes[0],
        );
        let NodeData::TypeReferenceNode(attribute_reference) =
            &react.arena.get(attributes.node).unwrap().data
        else {
            panic!("the head property must retain its nested HTMLAttributes reference")
        };
        let nested_element = NodeRef::new(
            attributes.arena,
            attributes.file,
            attribute_reference.type_arguments.as_ref().unwrap().nodes[0],
        );
        let original = context
            .store()
            .type_node_links(nested_element)
            .unwrap()
            .clone();
        let mut forged = original.clone();
        forged.resolved_type = Some(head_type);
        assert!(
            context
                .store_mut_for_test()
                .set_type_node_links(nested_element, forged),
        );
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(head_annotation).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert!(
            context
                .store_mut_for_test()
                .set_type_node_links(nested_element, original),
        );
        assert_eq!(
            context.get_type_from_type_node(head_annotation),
            Ok(head_resolved),
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Transitive React and DOM ownership share cold and poisoned proofs.
    fn react_html_factory_transitive_attribute_and_dom_bases_remain_authenticated() {
        let library = parse_source_file(concat!(
            "interface HTMLElement { self: this; } declare var HTMLElement: unknown; ",
            "interface HTMLMediaElement extends HTMLElement { media: string; } ",
            "declare var HTMLMediaElement: unknown; ",
            "interface HTMLAudioElement extends HTMLMediaElement { ",
            "addEventListener<Value extends string>(type: Value): void; ",
            "} declare var HTMLAudioElement: unknown; ",
            "interface HTMLVideoElement extends HTMLMediaElement { ",
            "addEventListener<Value extends string>(type: Value): void; ",
            "} declare var HTMLVideoElement: unknown; ",
            "interface HTMLTableCellElement extends HTMLElement { cell: string; } ",
            "declare var HTMLTableCellElement: unknown; ",
            "interface HTMLTableDataCellElement extends HTMLTableCellElement { ",
            "addEventListener<Value extends string>(type: Value): void; } ",
            "interface HTMLTableHeaderCellElement extends HTMLTableCellElement { ",
            "addEventListener<Value extends string>(type: Value): void; } ",
            "interface HTMLFormElement extends HTMLElement { ",
            "addEventListener<Value extends string>(type: Value): void; } ",
            "interface HTMLFormElement { [name: string]: unknown; } ",
            "declare var HTMLFormElement: unknown; ",
            "interface HTMLSelectElement extends HTMLElement { ",
            "addEventListener<Value extends string>(type: Value): void; } ",
            "interface HTMLSelectElement { [index: number]: unknown; } ",
            "declare var HTMLSelectElement: unknown;",
        ));
        let react = parse_source_file(concat!(
            "declare module 'react' { export = React; namespace React { ",
            "interface DOMAttributes<T> {} ",
            "interface HTMLAttributes<T> extends DOMAttributes<T> {} ",
            "interface HTMLAttributes<T> extends DOMAttributes<T> {} ",
            "interface MediaHTMLAttributes<T> extends HTMLAttributes<T> {} ",
            "interface AudioHTMLAttributes<T> extends MediaHTMLAttributes<T> {} ",
            "interface VideoHTMLAttributes<T> extends MediaHTMLAttributes<T> {} ",
            "interface TdHTMLAttributes<T> extends HTMLAttributes<T> {} ",
            "interface ThHTMLAttributes<T> extends HTMLAttributes<T> {} ",
            "interface FormHTMLAttributes<T> extends HTMLAttributes<T> {} ",
            "interface SelectHTMLAttributes<T> extends HTMLAttributes<T> {} ",
            "interface ClassAttributes<T> {} type ReactNode = unknown; ",
            "type DOMFactory<P, T> = ",
            "(props?: ClassAttributes<T> & P | null, ...children: ReactNode[]) => unknown; ",
            "interface DetailedHTMLFactory<",
            "P extends HTMLAttributes<T>, T extends HTMLElement",
            "> extends DOMFactory<P, T> { ",
            "(props?: ClassAttributes<T> & P | null, ...children: ReactNode[]): unknown; } ",
            "interface ReactHTML { ",
            "audio: DetailedHTMLFactory<AudioHTMLAttributes<HTMLAudioElement>, HTMLAudioElement>; ",
            "video: DetailedHTMLFactory<VideoHTMLAttributes<HTMLVideoElement>, HTMLVideoElement>; ",
            "td: DetailedHTMLFactory<TdHTMLAttributes<HTMLTableDataCellElement>, HTMLTableDataCellElement>; ",
            "th: DetailedHTMLFactory<ThHTMLAttributes<HTMLTableHeaderCellElement>, HTMLTableHeaderCellElement>; ",
            "form: DetailedHTMLFactory<FormHTMLAttributes<HTMLFormElement>, HTMLFormElement>; ",
            "select: DetailedHTMLFactory<SelectHTMLAttributes<HTMLSelectElement>, HTMLSelectElement>; ",
            "} } }",
        ));
        let (mut context, library_file, react_file) =
            default_library_interface_context(&library, &react, true);
        let library_bound = context.file(library_file).unwrap().1.clone();
        let react_bound = context.file(react_file).unwrap().1.clone();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, &library_bound),
                (&react.arena, &react_bound),
            ],
            GlobalMergeCompletion::for_test(context.options().name_resolution),
        )
        .unwrap();
        let globals = context.store().intrinsic_bootstrap().unwrap().globals;
        let html = context
            .store()
            .symbol_table(globals)
            .and_then(|globals| globals.get_source("HTMLElement"))
            .unwrap();
        let media = context
            .store()
            .symbol_table(globals)
            .and_then(|globals| globals.get_source("HTMLMediaElement"))
            .unwrap();
        let audio_annotation = react_dom_property_annotation(&react, react_file, "audio");
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                globals,
                EscapedName::source("HTMLMediaElement"),
                html,
            ),
            Some(Some(media)),
        );
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(audio_annotation).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                globals,
                EscapedName::source("HTMLMediaElement"),
                media,
            ),
            Some(Some(html)),
        );

        let mut resolved = Vec::new();
        for (property, element) in [
            ("audio", "HTMLAudioElement"),
            ("video", "HTMLVideoElement"),
            ("td", "HTMLTableDataCellElement"),
            ("th", "HTMLTableHeaderCellElement"),
            ("form", "HTMLFormElement"),
            ("select", "HTMLSelectElement"),
        ] {
            let annotation = react_dom_property_annotation(&react, react_file, property);
            let actual = context.get_type_from_type_node(annotation).unwrap();
            let element_symbol = context
                .store()
                .symbol_table(globals)
                .and_then(|globals| globals.get_source(element))
                .unwrap();
            let element_type = context
                .store()
                .declared_type_links(element_symbol)
                .and_then(|links| links.declared_type)
                .unwrap();
            let factory = validate_direct_generic_reference(context.store(), actual).unwrap();
            assert_eq!(factory.type_arguments[1], element_type);
            if matches!(property, "form" | "select") {
                assert_eq!(
                    context
                        .store()
                        .symbol(element_symbol)
                        .and_then(ts_binder::semantic::Symbol::declarations)
                        .unwrap()
                        .iter()
                        .filter(|declaration| {
                            host.node(**declaration).is_some_and(|record| {
                                record.kind == SyntaxKind::InterfaceDeclaration
                            })
                        })
                        .count(),
                    2,
                );
                let TypeData::Interface(interface) =
                    context.store().type_payload(element_type).unwrap().data()
                else {
                    panic!("reopened DOM declarations must retain their interface identity")
                };
                assert!(!interface.base_types_resolved);
                assert!(!interface.declared_members_resolved);
                assert!(interface.resolved_base_types.is_none());
            }
            assert_eq!(
                validate_direct_generic_reference(context.store(), factory.type_arguments[0])
                    .unwrap()
                    .type_arguments,
                [element_type],
            );
            let method = context
                .store()
                .symbol(element_symbol)
                .and_then(ts_binder::semantic::Symbol::members)
                .and_then(|members| context.store().symbol_table(members))
                .and_then(|members| members.get_source("addEventListener"))
                .unwrap();
            assert!(context.store().value_symbol_links(method).is_none());
            let references = react_dom_type_references(&react, react_file, element);
            assert_eq!(references.len(), 2);
            let aliases = HashMap::new();
            for reference in references {
                assert!(
                    TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                        .is_default_library_dom_interface_argument(reference, element_symbol)
                );
            }
            resolved.push((annotation, actual));
        }
        for intermediate in ["HTMLMediaElement", "HTMLTableCellElement"] {
            let symbol = context
                .store()
                .symbol_table(globals)
                .and_then(|globals| globals.get_source(intermediate))
                .unwrap();
            let declared = context
                .store()
                .declared_type_links(symbol)
                .and_then(|links| links.declared_type)
                .unwrap();
            let record = context.store().type_payload(declared).unwrap();
            let TypeData::Interface(interface) = record.data() else {
                panic!("intermediate DOM bases must retain their interface identities")
            };
            assert_eq!(record.symbol(), Some(symbol));
            assert!(!interface.base_types_resolved);
            assert!(!interface.declared_members_resolved);
            assert!(interface.resolved_base_types.is_none());
            assert!(interface.reference.object.structured.properties.is_none());
            assert!(interface.reference.object.structured.signatures.is_none());
        }
        let warm = store_state(context.store());
        for (annotation, expected) in &resolved {
            assert_eq!(context.get_type_from_type_node(*annotation), Ok(*expected));
        }
        assert_eq!(store_state(context.store()), warm);

        let factory = context
            .store()
            .symbol_node_links(audio_annotation)
            .and_then(|links| links.resolved_symbol)
            .unwrap();
        let namespace = context.store().get_parent_of_symbol(factory).unwrap();
        let exports = context
            .store()
            .symbol(namespace)
            .unwrap()
            .exports()
            .unwrap();
        let media_attributes = context
            .store()
            .symbol_table(exports)
            .and_then(|exports| exports.get_source("MediaHTMLAttributes"))
            .unwrap();
        let html_attributes = context
            .store()
            .symbol_table(exports)
            .and_then(|exports| exports.get_source("HTMLAttributes"))
            .unwrap();
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("MediaHTMLAttributes"),
                html_attributes,
            ),
            Some(Some(media_attributes)),
        );
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(audio_annotation).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("MediaHTMLAttributes"),
                media_attributes,
            ),
            Some(Some(html_attributes)),
        );
        assert_eq!(
            context.get_type_from_type_node(audio_annotation),
            Ok(resolved[0].1),
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)] // WebView source ownership, cold DOM heritage, and forged exports share one proof.
    fn react_html_factory_webview_arguments_keep_source_and_dom_heritage_lazy() {
        let library = parse_source_file(concat!(
            "interface HTMLElement { ",
            "addEventListener<Value extends string>(type: Value): void; ",
            "} declare var HTMLElement: unknown;",
        ));
        let react = parse_source_file(concat!(
            "interface HTMLWebViewElement extends HTMLElement {} ",
            "declare module 'react' { ",
            "export = React; namespace React { ",
            "interface HTMLAttributes<Value> {} ",
            "interface WebViewHTMLAttributes<Value> extends HTMLAttributes<Value> {} ",
            "interface ClassAttributes<Value> {} ",
            "type ReactNode = unknown; ",
            "type DOMFactory<P, T> = ",
            "(props?: ClassAttributes<T> & P | null, ...children: ReactNode[]) => unknown; ",
            "interface DetailedHTMLFactory<",
            "P extends HTMLAttributes<T>, T extends HTMLElement",
            "> extends DOMFactory<P, T> { ",
            "(props?: ClassAttributes<T> & P | null, ...children: ReactNode[]): unknown; ",
            "} ",
            "interface ReactHTML { ",
            "webview: DetailedHTMLFactory<",
            "WebViewHTMLAttributes<HTMLWebViewElement>, HTMLWebViewElement>; ",
            "} } }",
        ));
        let (mut context, library_file, react_file) =
            default_library_interface_context(&library, &react, true);
        let library_bound = context.file(library_file).unwrap().1.clone();
        let react_bound = context.file(react_file).unwrap().1.clone();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, &library_bound),
                (&react.arena, &react_bound),
            ],
            GlobalMergeCompletion::for_test(context.options().name_resolution),
        )
        .unwrap();
        let globals = context.store().intrinsic_bootstrap().unwrap().globals;
        let element = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("HTMLElement"))
            .unwrap();
        let webview = context
            .store()
            .symbol_table(globals)
            .and_then(|symbols| symbols.get_source("HTMLWebViewElement"))
            .unwrap();
        let references = react_dom_type_references(&react, react_file, "HTMLWebViewElement");
        assert_eq!(references.len(), 2);
        let aliases = HashMap::new();
        for reference in &references {
            assert!(
                TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                    .is_default_library_dom_interface_argument(*reference, webview)
            );
        }

        let annotation = react_dom_property_annotation(&react, react_file, "webview");
        let resolved = context.get_type_from_type_node(annotation).unwrap();
        let reference = validate_direct_generic_reference(context.store(), resolved).unwrap();
        let webview_type = context
            .store()
            .declared_type_links(webview)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_eq!(reference.type_arguments[1], webview_type);
        assert_eq!(
            validate_direct_generic_reference(context.store(), reference.type_arguments[0])
                .unwrap()
                .type_arguments,
            [webview_type],
        );
        for symbol in [webview, element] {
            let target = context
                .store()
                .declared_type_links(symbol)
                .and_then(|links| links.declared_type)
                .unwrap();
            let TypeData::Interface(interface) =
                context.store().type_payload(target).unwrap().data()
            else {
                panic!("the WebView and DOM base must retain their interface identities")
            };
            assert!(!interface.base_types_resolved);
            assert!(!interface.declared_members_resolved);
            assert!(interface.resolved_base_types.is_none());
        }
        let method = context
            .store()
            .symbol(element)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| context.store().symbol_table(members))
            .and_then(|members| members.get_source("addEventListener"))
            .unwrap();
        assert!(context.store().value_symbol_links(method).is_none());

        let warm = store_state(context.store());
        assert_eq!(context.get_type_from_type_node(annotation), Ok(resolved));
        assert_eq!(store_state(context.store()), warm);

        assert!(context.store_mut_for_test().set_symbol_flags(
            webview,
            SymbolFlags::INTERFACE | SymbolFlags::TRANSIENT,
            CheckFlags::NONE,
        ));
        for reference in &references {
            assert!(
                !TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                    .is_default_library_dom_interface_argument(*reference, webview)
            );
        }
        assert!(context.store_mut_for_test().set_symbol_flags(
            webview,
            SymbolFlags::INTERFACE,
            CheckFlags::NONE,
        ));

        let factory = context
            .store()
            .symbol_node_links(annotation)
            .and_then(|links| links.resolved_symbol)
            .unwrap();
        let namespace = context.store().get_parent_of_symbol(factory).unwrap();
        let exports = context
            .store()
            .symbol(namespace)
            .unwrap()
            .exports()
            .unwrap();
        let attributes = context
            .store()
            .symbol_table(exports)
            .and_then(|exports| exports.get_source("WebViewHTMLAttributes"))
            .unwrap();
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("DetailedHTMLFactory"),
                attributes,
            ),
            Some(Some(factory)),
        );
        for reference in &references {
            assert!(
                !TypeQueryPlanner::new(context.store(), &host, None, None, false, &aliases)
                    .is_default_library_dom_interface_argument(*reference, webview)
            );
        }
        let poisoned = store_state(context.store());
        assert!(context.get_type_from_type_node(annotation).is_err());
        assert_eq!(store_state(context.store()), poisoned);
        assert_eq!(
            context.store_mut_for_test().insert_symbol(
                exports,
                EscapedName::source("DetailedHTMLFactory"),
                factory,
            ),
            Some(Some(attributes)),
        );
        assert_eq!(context.get_type_from_type_node(annotation), Ok(resolved));
        assert!(context.diagnostics().is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Preserve private React aliases, event members, and forged warm links.
    fn private_react_native_event_aliases_keep_default_library_heritage_and_members_lazy() {
        let library = parse_source_file(concat!(
            "interface Event { readonly type: string; stopPropagation(): void; } ",
            "declare var Event: unknown; ",
            "interface AnimationEvent extends Event { readonly animationName: string; } ",
            "declare var AnimationEvent: unknown; ",
            "interface ClipboardEvent extends Event { readonly clipboardData: string; } ",
            "declare var ClipboardEvent: unknown;",
        ));
        let source = parse_source_file(concat!(
            "declare module 'react' { ",
            "type NativeAnimationEvent = AnimationEvent; ",
            "type NativeClipboardEvent = ClipboardEvent; ",
            "export = React; ",
            "namespace React {} ",
            "}",
        ));
        let (mut context, library_file, source_file) =
            default_library_interface_context(&library, &source, true);
        let library_bound = context.file(library_file).unwrap().1.clone();
        let source_bound = context.file(source_file).unwrap().1.clone();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, &library_bound),
                (&source.arena, &source_bound),
            ],
            GlobalMergeCompletion::for_test(context.options().name_resolution),
        )
        .unwrap();
        let globals = context.store().intrinsic_bootstrap().unwrap().globals;
        let base = context
            .store()
            .symbol_table(globals)
            .and_then(|globals| globals.get_source("Event"))
            .unwrap();
        let events = ["AnimationEvent", "ClipboardEvent"].map(|name| {
            context
                .store()
                .symbol_table(globals)
                .and_then(|globals| globals.get_source(name))
                .unwrap()
        });
        let aliases = ["NativeAnimationEvent", "NativeClipboardEvent"].map(|name| {
            let declaration = source
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::TypeAliasDeclaration(alias) = &record.data else {
                        return None;
                    };
                    (identifier_text(&source.arena, alias.name) == Some(name))
                        .then_some(NodeRef::new(source.arena.id(), source_file, node))
                })
                .unwrap();
            let NodeData::TypeAliasDeclaration(alias) =
                &source.arena.get(declaration.node).unwrap().data
            else {
                unreachable!("the declaration was selected by its alias syntax")
            };
            (
                source_bound.symbol(declaration).unwrap(),
                NodeRef::new(declaration.arena, declaration.file, alias.type_),
            )
        });
        let type_aliases = HashMap::new();
        let planner =
            TypeQueryPlanner::new(context.store(), &host, None, None, false, &type_aliases);
        for ((_, reference), event) in aliases.iter().zip(events) {
            assert!(planner.is_default_library_dom_interface_argument(*reference, event));
        }
        let method = context
            .store()
            .symbol(base)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| context.store().symbol_table(members))
            .and_then(|members| members.get_source("stopPropagation"))
            .unwrap();

        let mut resolved = Vec::new();
        for ((alias, reference), event) in aliases.iter().copied().zip(events) {
            let type_ = context.get_declared_type_of_symbol(alias).unwrap();
            assert_eq!(
                context
                    .store()
                    .declared_type_links(event)
                    .and_then(|links| links.declared_type),
                Some(type_),
            );
            assert_eq!(context.get_type_from_type_node(reference), Ok(type_));
            let record = context.store().type_payload(type_).unwrap();
            let TypeData::Interface(interface) = record.data() else {
                panic!("native DOM events must retain their default-library interface identity")
            };
            assert_eq!(record.symbol(), Some(event));
            assert!(!interface.base_types_resolved);
            assert!(!interface.declared_members_resolved);
            assert!(interface.resolved_base_types.is_none());
            assert!(interface.reference.object.structured.properties.is_none());
            resolved.push(type_);
        }
        let base_type = context
            .store()
            .declared_type_links(base)
            .and_then(|links| links.declared_type)
            .expect("recursive native-event planning retains the Event interface identity");
        let base_record = context.store().type_payload(base_type).unwrap();
        let TypeData::Interface(base_interface) = base_record.data() else {
            panic!("Event must retain its canonical interface identity")
        };
        assert_eq!(base_record.symbol(), Some(base));
        assert!(!base_interface.base_types_resolved);
        assert!(!base_interface.declared_members_resolved);
        assert!(base_interface.resolved_base_types.is_none());
        assert!(
            base_interface
                .reference
                .object
                .structured
                .properties
                .is_none()
        );
        assert!(
            base_interface
                .reference
                .object
                .structured
                .signatures
                .is_none()
        );
        assert!(
            context
                .store()
                .direct_interface_heritage_provenance(base_type)
                .is_none()
        );
        assert!(context.store().value_symbol_links(method).is_none());
        let warm = (
            store_state(context.store()),
            context.store().signature_len(),
            context.store().index_info_len(),
        );
        for ((alias, reference), expected) in aliases.iter().copied().zip(resolved) {
            assert_eq!(context.get_declared_type_of_symbol(alias), Ok(expected));
            assert_eq!(context.get_type_from_type_node(reference), Ok(expected));
        }
        assert_eq!(
            context
                .store()
                .declared_type_links(base)
                .and_then(|links| links.declared_type),
            Some(base_type),
        );
        assert!(context.store().value_symbol_links(method).is_none());
        assert_eq!(
            (
                store_state(context.store()),
                context.store().signature_len(),
                context.store().index_info_len(),
            ),
            warm,
        );
        assert!(context.diagnostics().is_empty());

        let animation = events[0];
        let original = context
            .store()
            .declared_type_links(animation)
            .unwrap()
            .clone();
        let mut forged = original.clone();
        forged.declared_type = Some(context.store().intrinsic_bootstrap().unwrap().string_type);
        assert!(
            context
                .store_mut_for_test()
                .set_declared_type_links(animation, forged)
        );
        let poisoned = (
            store_state(context.store()),
            context.store().signature_len(),
            context.store().index_info_len(),
        );
        assert!(context.get_type_from_type_node(aliases[0].1).is_err());
        assert_eq!(
            (
                store_state(context.store()),
                context.store().signature_len(),
                context.store().index_info_len(),
            ),
            poisoned,
        );
        assert!(
            context
                .store_mut_for_test()
                .set_declared_type_links(animation, original)
        );
    }

    #[test]
    fn lazy_default_library_interface_bases_reject_unsupported_source_shapes() {
        let library = parse_source_file(concat!(
            "interface HTMLElement { method(value: string): void; } ",
            "declare var HTMLElement: unknown; ",
            "interface Extra {}",
        ));
        for (is_default_library, declaration) in [
            (false, "interface HTMLWebViewElement extends HTMLElement {}"),
            (
                true,
                "interface HTMLWebViewElement extends HTMLElement { own: string; }",
            ),
            (
                true,
                "interface HTMLWebViewElement extends HTMLElement, Extra {}",
            ),
        ] {
            let source = parse_source_file(declaration);
            let (mut context, _, _) =
                default_library_interface_context(&library, &source, is_default_library);
            let globals = context.store().intrinsic_bootstrap().unwrap().globals;
            let derived = context
                .store()
                .symbol_table(globals)
                .and_then(|symbols| symbols.get_source("HTMLWebViewElement"))
                .unwrap();
            let before = (
                store_state(context.store()),
                context.store().signature_len(),
                context.store().index_info_len(),
            );

            assert!(
                context.get_declared_type_of_symbol(derived).is_err(),
                "accepted unsupported declaration: {declaration}",
            );
            assert_eq!(
                (
                    store_state(context.store()),
                    context.store().signature_len(),
                    context.store().index_info_len(),
                ),
                before,
                "published checker state for: {declaration}",
            );
            assert!(context.diagnostics().is_empty());
        }
    }

    #[test]
    fn default_library_awaited_unwraps_nested_promises_without_resolving_its_body() {
        let mut fixture = default_library_fixture(concat!(
            "interface Promise<T> {} ",
            "interface PromiseLike<T> {} ",
            "type Awaited<T> = T extends null | undefined ? T : ",
            "T extends object & { then(onfulfilled: infer F, ...args: infer _): any; } ? ",
            "F extends ((value: infer V, ...args: infer _) => any) ? Awaited<V> : never : T; ",
            "type Plain = Awaited<string>; ",
            "type Nested = Awaited<Promise<Promise<string>>>; ",
            "type Thenable = Awaited<PromiseLike<number>>; ",
            "type Missing = Awaited<undefined>;",
        ));
        let awaited = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Awaited");
        let awaited_body = alias_parts(&fixture, "Awaited").2;
        let (string, number, undefined) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (
                bootstrap.string_type,
                bootstrap.number_type,
                bootstrap.undefined_type,
            )
        };
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        let aliases = HashMap::new();
        let proof = TypeQueryPlanner::new(&fixture.store, &host, None, None, false, &aliases)
            .authenticated_default_library_awaited_alias(awaited)
            .unwrap();
        assert_eq!(
            fixture
                .store
                .symbol(proof.parameter)
                .and_then(|symbol| symbol.name().as_utf8()),
            Some("T"),
        );
        drop(host);

        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let aliases = [
            ("Plain", string),
            ("Nested", string),
            ("Thenable", number),
            ("Missing", undefined),
        ];
        for (name, expected) in aliases {
            let symbol = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
            assert_eq!(
                query_declared(
                    &mut fixture,
                    symbol,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
                "{name}",
            );
        }
        assert!(fixture.store.type_alias_links(awaited).is_none());
        assert!(fixture.store.type_node_links(awaited_body).is_none());

        let warm = store_state(&fixture.store);
        for (name, expected) in aliases {
            let symbol = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
            assert_eq!(
                query_declared(
                    &mut fixture,
                    symbol,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Bind independent library/source files and verify both warm identities.
    fn cross_file_awaited_unwraps_default_library_promises_and_inherited_promise_like() {
        let library = parse_source_file(concat!(
            "interface Promise<T> {} ",
            "interface PromiseLike<T> {} ",
            "type Awaited<T> = T extends null | undefined ? T : ",
            "T extends object & { then(onfulfilled: infer F, ...args: infer _): any; } ? ",
            "F extends ((value: infer V, ...args: infer _) => any) ? Awaited<V> : never : T;",
        ));
        let source = parse_source_file(concat!(
            "interface Thenable<T> extends PromiseLike<T> {} ",
            "type Nested = Awaited<Promise<PromiseLike<string>>>; ",
            "type Inherited = Awaited<Thenable<number>>;",
        ));
        let library_file = FileId::new(85);
        let source_file = FileId::new(86);
        let mut binder = CanonicalBinder::new();
        for (parsed, file, is_default_library) in [
            (&library, library_file, true),
            (&source, source_file, false),
        ] {
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            binder
                .bind_source_file_with_facts(
                    &parsed.arena,
                    parsed.source_file,
                    file,
                    CanonicalSourceFileFacts::new_with_default_library(
                        EscapedName::source(format!("\"/awaited-{}.ts\"", file.index())),
                        CanonicalSourceLanguage::TypeScript,
                        is_default_library,
                        is_default_library,
                        CanonicalModuleState::Script,
                    ),
                )
                .unwrap();
            binder
                .bind_typescript_declaration_slice(&parsed.arena, file)
                .unwrap();
        }
        let (symbols, files) = binder.finish().try_into_parts().unwrap();
        let mut store = CanonicalTypeMapperStore::from_symbol_store(symbols);
        for (parsed, file) in [(&library, library_file), (&source, source_file)] {
            assert!(
                store
                    .register_source_file(&parsed.arena, parsed.source_file, file)
                    .is_some()
            );
        }
        store
            .initialize_intrinsic_bootstrap(IntrinsicBootstrapOptions::default())
            .unwrap();
        let globals = store.intrinsic_bootstrap().unwrap().globals;
        for bound in files.values() {
            let symbols = store
                .symbol_table(bound.locals(bound.source_file()).unwrap())
                .unwrap()
                .iter()
                .map(|(_, symbol)| symbol)
                .collect::<Vec<_>>();
            for symbol in symbols {
                store.merge_global_symbol(globals, symbol).unwrap();
            }
        }
        let source_bound = files.get(&source_file).unwrap();
        let source_symbol = |name: &str| {
            source
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::TypeAliasDeclaration(alias) = &record.data else {
                        return None;
                    };
                    (identifier_text(&source.arena, alias.name) == Some(name))
                        .then(|| {
                            source_bound.symbol(NodeRef::new(source.arena.id(), source_file, node))
                        })
                        .flatten()
                })
                .unwrap()
        };
        let nested = source_symbol("Nested");
        let inherited = source_symbol("Inherited");
        let (string, number) = {
            let bootstrap = store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.number_type)
        };
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, files.get(&library_file).unwrap()),
                (&source.arena, source_bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        for (symbol, expected) in [(nested, string), (inherited, number)] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_declared_type_of_symbol(symbol),
                Ok(expected),
            );
        }

        let warm = store_state(&store);
        for (symbol, expected) in [(nested, string), (inherited, number)] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_declared_type_of_symbol(symbol),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn awaited_rejects_non_library_and_modified_library_aliases_before_publication() {
        let canonical = concat!(
            "interface Promise<T> {} ",
            "type Awaited<T> = T extends null | undefined ? T : ",
            "T extends object & { then(onfulfilled: infer F, ...args: infer _): any; } ? ",
            "F extends ((value: infer V, ...args: infer _) => any) ? Awaited<V> : never : T; ",
            "type Result = Awaited<Promise<string>>;",
        );
        let modified = concat!(
            "interface Promise<T> {} ",
            "type Awaited<T> = T extends null | undefined ? T : ",
            "T extends object & { then(onfulfilled: infer F, ...args: infer _): any; } ? ",
            "F extends ((value: infer V, ...args: infer _) => any) ? Awaited<V> : never : never; ",
            "type Result = Awaited<Promise<string>>;",
        );
        for mut fixture in [fixture(canonical), default_library_fixture(modified)] {
            let result = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Result");
            let before = store_state(&fixture.store);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();

            assert!(matches!(
                query_declared(
                    &mut fixture,
                    result,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Err(DeclaredTypeError::TypeNodeUnavailable(
                    TypeNodeUnavailable::GenericReferenceUnsupported { .. }
                )),
            ));
            assert_eq!(store_state(&fixture.store), before);
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn merged_default_library_promise_reuses_one_target_without_resolving_members() {
        let mut fixture = default_library_fixture(concat!(
            "interface Promise<Value> {} ",
            "interface Promise<Value> {} ",
            "declare var Promise: unknown; ",
            "let explicit: Promise<string>;",
        ));
        let symbol = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Promise");
        let explicit = variable_type_node(&fixture, "explicit");
        let (string, number) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.number_type)
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let explicit_type = query_node(&mut fixture, explicit, &mut diagnostics).unwrap();
        let target = fixture
            .store
            .declared_type_links(symbol)
            .and_then(|links| links.declared_type)
            .unwrap();
        let TypeData::Interface(interface) = fixture.store.type_payload(target).unwrap().data()
        else {
            panic!("Promise must retain its merged generic interface target")
        };
        assert!(!interface.declared_members_resolved);
        assert_eq!(
            validate_direct_generic_reference(&fixture.store, explicit_type)
                .unwrap()
                .type_arguments,
            [string],
        );

        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        let mut query = CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert_eq!(query.get_global_promise_type(string), Ok(explicit_type));
        let numeric = query.get_global_promise_type(number).unwrap();
        assert_ne!(numeric, explicit_type);
        drop(query);
        assert_eq!(
            validate_direct_generic_reference(&fixture.store, numeric)
                .unwrap()
                .type_arguments,
            [number],
        );

        let warm = store_state(&fixture.store);
        let mut query = CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert_eq!(query.get_global_promise_type(string), Ok(explicit_type));
        assert_eq!(query.get_global_promise_type(number), Ok(numeric));
        drop(query);
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Binds and validates four real merged source files.
    fn cross_file_default_library_promise_accepts_merged_transient_symbols() {
        let base = parse_source_file("interface Promise<T> { then(value: T): Promise<T>; }");
        let augmentation = parse_source_file("interface Promise<T> { finally(): Promise<T>; }");
        let constructor = parse_source_file("declare var Promise: unknown;");
        let source = parse_source_file("let explicit: Promise<string>;");
        let base_file = FileId::new(81);
        let augmentation_file = FileId::new(82);
        let constructor_file = FileId::new(83);
        let source_file = FileId::new(84);
        let mut binder = CanonicalBinder::new();

        for (parsed, file, is_default_library) in [
            (&base, base_file, true),
            (&augmentation, augmentation_file, true),
            (&constructor, constructor_file, true),
            (&source, source_file, false),
        ] {
            assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
            binder
                .bind_source_file_with_facts(
                    &parsed.arena,
                    parsed.source_file,
                    file,
                    CanonicalSourceFileFacts::new_with_default_library(
                        EscapedName::source(format!("\"/promise-{}.ts\"", file.index())),
                        CanonicalSourceLanguage::TypeScript,
                        is_default_library,
                        is_default_library,
                        CanonicalModuleState::Script,
                    ),
                )
                .unwrap();
            binder
                .bind_typescript_declaration_slice(&parsed.arena, file)
                .unwrap();
        }

        let (symbols, files) = binder.finish().try_into_parts().unwrap();
        let mut store = CanonicalTypeMapperStore::from_symbol_store(symbols);
        for (parsed, file) in [
            (&base, base_file),
            (&augmentation, augmentation_file),
            (&constructor, constructor_file),
            (&source, source_file),
        ] {
            assert!(
                store
                    .register_source_file(&parsed.arena, parsed.source_file, file)
                    .is_some()
            );
        }
        store
            .initialize_intrinsic_bootstrap(IntrinsicBootstrapOptions::default())
            .unwrap();
        let globals = store.intrinsic_bootstrap().unwrap().globals;
        for bound in files.values() {
            let symbols = store
                .symbol_table(bound.locals(bound.source_file()).unwrap())
                .unwrap()
                .iter()
                .map(|(_, symbol)| symbol)
                .collect::<Vec<_>>();
            for symbol in symbols {
                store.merge_global_symbol(globals, symbol).unwrap();
            }
        }

        let symbol = store
            .symbol_table(globals)
            .unwrap()
            .get_source("Promise")
            .unwrap();
        let owner = store.symbol(symbol).unwrap();
        assert_eq!(
            owner.flags(),
            SymbolFlags::INTERFACE | SymbolFlags::FUNCTION_SCOPED_VARIABLE | SymbolFlags::TRANSIENT,
        );
        let parameter = store
            .symbol_table(owner.members().unwrap())
            .unwrap()
            .get_source("T")
            .unwrap();
        assert_eq!(
            store.symbol(parameter).unwrap().flags(),
            SymbolFlags::TYPE_PARAMETER | SymbolFlags::TRANSIENT,
        );
        let explicit = source
            .arena
            .iter()
            .find_map(|(_, record)| match &record.data {
                NodeData::VariableDeclaration(variable)
                    if identifier_text(&source.arena, variable.name) == Some("explicit") =>
                {
                    variable
                        .type_
                        .map(|node| NodeRef::new(source.arena.id(), source_file, node))
                }
                _ => None,
            })
            .unwrap();
        let (string, number) = {
            let bootstrap = store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.number_type)
        };
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&base.arena, files.get(&base_file).unwrap()),
                (&augmentation.arena, files.get(&augmentation_file).unwrap()),
                (&constructor.arena, files.get(&constructor_file).unwrap()),
                (&source.arena, files.get(&source_file).unwrap()),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let mut query = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let explicit_type = query.get_type_from_type_node(explicit).unwrap();
        assert_eq!(query.get_global_promise_type(string), Ok(explicit_type));
        let numeric = query.get_global_promise_type(number).unwrap();
        drop(query);

        let target = store
            .declared_type_links(symbol)
            .and_then(|links| links.declared_type)
            .unwrap();
        let TypeData::Interface(interface) = store.type_payload(target).unwrap().data() else {
            panic!("the merged Promise must retain its generic interface identity")
        };
        assert!(!interface.declared_members_resolved);
        assert_eq!(
            validate_direct_generic_reference(&store, numeric)
                .unwrap()
                .type_arguments,
            [number],
        );

        let warm = store_state(&store);
        let mut query = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert_eq!(query.get_type_from_type_node(explicit), Ok(explicit_type));
        assert_eq!(query.get_global_promise_type(string), Ok(explicit_type));
        assert_eq!(query.get_global_promise_type(number), Ok(numeric));
        drop(query);
        assert_eq!(store_state(&store), warm);
        assert!(diagnostics.is_empty());
    }

