    #[test]
    #[allow(clippy::too_many_lines)] // Covers both query orders and forged warm identities.
    fn global_jsx_element_keeps_qualified_heritage_and_members_lazy() {
        for direct_first in [false, true] {
            let mut fixture = fixture(concat!(
                "declare namespace React { ",
                "interface ReactElement<Value> { value: Value; } ",
                "} ",
                "declare namespace JSX { ",
                "interface Element extends React.ReactElement<any> {} ",
                "} ",
                "namespace Ordinary { export interface Element { value: string; } } ",
                "type Rendered = JSX.Element; ",
                "type OrdinaryRendered = Ordinary.Element;",
            ));
            let element = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Element");
            let rendered = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Rendered");
            let ordinary = named_symbol(
                &fixture,
                SyntaxKind::TypeAliasDeclaration,
                "OrdinaryRendered",
            );
            let reference = alias_parts(&fixture, "Rendered").2;
            let mut diagnostics = CanonicalCheckerDiagnostics::default();

            let expected = if direct_first {
                query_declared(
                    &mut fixture,
                    element,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
            } else {
                query_declared(
                    &mut fixture,
                    rendered,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
            };
            assert_eq!(
                query_declared(
                    &mut fixture,
                    rendered,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
            );
            assert_eq!(
                query_declared(
                    &mut fixture,
                    element,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
            );
            assert_eq!(
                fixture
                    .store
                    .symbol_node_links(reference)
                    .and_then(|links| links.resolved_symbol),
                Some(element),
            );
            let TypeData::Interface(interface) =
                fixture.store.type_payload(expected).unwrap().data()
            else {
                panic!("JSX.Element must retain its declared interface identity")
            };
            assert!(!interface.declared_members_resolved);

            let ordinary_type = query_declared(
                &mut fixture,
                ordinary,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let TypeData::Interface(interface) =
                fixture.store.type_payload(ordinary_type).unwrap().data()
            else {
                panic!("the ordinary namespace must retain its interface identity")
            };
            assert!(interface.declared_members_resolved);

            let warm = store_state(&fixture.store);
            assert_eq!(
                query_node(&mut fixture, reference, &mut diagnostics),
                Ok(expected)
            );
            assert_eq!(
                query_declared(
                    &mut fixture,
                    element,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
            );
            assert_eq!(store_state(&fixture.store), warm);
            assert!(diagnostics.is_empty());

            let original_links = fixture.store.declared_type_links(element).unwrap().clone();
            let wrong = fixture.store.intrinsic_bootstrap().unwrap().string_type;
            let mut forged_links = original_links.clone();
            forged_links.declared_type = Some(wrong);
            assert!(fixture.store.set_declared_type_links(element, forged_links));
            let forged = store_state(&fixture.store);
            assert!(matches!(
                query_node(&mut fixture, reference, &mut diagnostics),
                Err(DeclaredTypeError::Unavailable(
                    DeclaredTypeUnavailable::InvalidCachedDeclaredType {
                        symbol,
                        declared_type,
                    }
                )) if symbol == element && declared_type == wrong
            ));
            assert_eq!(store_state(&fixture.store), forged);
            assert!(
                fixture
                    .store
                    .set_declared_type_links(element, original_links)
            );
            assert_eq!(
                query_node(&mut fixture, reference, &mut diagnostics),
                Ok(expected)
            );
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Checks export and parent rejection before a valid retry.
    fn global_jsx_element_rejects_forged_namespace_exports_and_parents() {
        let mut fixture = fixture(concat!(
            "declare namespace React { interface ReactElement<Value> {} } ",
            "declare namespace JSX { ",
            "interface Element extends React.ReactElement<any> {} ",
            "interface Decoy {} ",
            "} ",
            "type Rendered = JSX.Element; ",
            "declare const rendered: JSX.Element;",
        ));
        let element = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Element");
        let decoy = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Decoy");
        let rendered = named_symbol(&fixture, SyntaxKind::VariableDeclaration, "rendered");
        let reference = alias_parts(&fixture, "Rendered").2;
        let namespace = fixture
            .store
            .intrinsic_bootstrap()
            .and_then(|bootstrap| fixture.store.symbol_table(bootstrap.globals))
            .and_then(|globals| globals.get_source("JSX"))
            .unwrap();
        let exports = fixture.store.symbol(namespace).unwrap().exports().unwrap();
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        let aliases = HashMap::new();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        assert!(
            TypeQueryPlanner::new(&fixture.store, &host, None, None, false, &aliases)
                .is_canonical_global_jsx_element(element)
        );
        assert!(
            !TypeQueryPlanner::new(&fixture.store, &host, None, None, false, &aliases)
                .is_canonical_global_jsx_element(decoy)
        );

        assert_eq!(
            fixture
                .store
                .insert_symbol(exports, EscapedName::source("Element"), decoy),
            Some(Some(element)),
        );
        assert!(
            !TypeQueryPlanner::new(&fixture.store, &host, None, None, false, &aliases)
                .is_canonical_global_jsx_element(element)
        );
        let forged = store_state(&fixture.store);
        assert!(
            CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(reference)
            .is_err()
        );
        assert_eq!(store_state(&fixture.store), forged);
        assert!(diagnostics.is_empty());
        assert_eq!(
            fixture
                .store
                .insert_symbol(exports, EscapedName::source("Element"), element),
            Some(Some(decoy)),
        );

        let (members, owner_exports, parent, export_symbol) = {
            let record = fixture.store.symbol(element).unwrap();
            (
                record.members(),
                record.exports(),
                record.parent(),
                record.export_symbol(),
            )
        };
        assert!(fixture.store.set_symbol_relationships(
            element,
            members,
            owner_exports,
            None,
            export_symbol,
        ));
        assert!(
            !TypeQueryPlanner::new(&fixture.store, &host, None, None, false, &aliases)
                .is_canonical_global_jsx_element(element)
        );
        let forged = store_state(&fixture.store);
        assert!(query_node(&mut fixture, reference, &mut diagnostics).is_err());
        assert_eq!(store_state(&fixture.store), forged);
        assert!(
            query_declared(
                &mut fixture,
                element,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .is_err()
        );
        assert_eq!(store_state(&fixture.store), forged);
        assert!(query_declared_value(&mut fixture, rendered, &mut diagnostics).is_err());
        assert_eq!(store_state(&fixture.store), forged);
        assert!(diagnostics.is_empty());

        assert!(fixture.store.set_symbol_relationships(
            element,
            members,
            owner_exports,
            parent,
            export_symbol,
        ));
        assert!(query_node(&mut fixture, reference, &mut diagnostics).is_ok());
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn qualified_namespace_references_follow_canonical_export_tables() {
        let mut fixture = fixture(concat!(
            "namespace N { ",
            "export interface Shape { value: string; } ",
            "export type Text = string; ",
            "export namespace Deep { export interface Item {} } ",
            "} ",
            "type ResolvedShape = N.Shape; ",
            "type ResolvedText = N.Text; ",
            "type ResolvedItem = N.Deep.Item;",
        ));
        let shape = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Shape");
        let item = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Item");
        let resolved_shape =
            named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "ResolvedShape");
        let resolved_text =
            named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "ResolvedText");
        let resolved_item =
            named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "ResolvedItem");
        let string_type = fixture.store.intrinsic_bootstrap().unwrap().string_type;
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let shape_type = query_declared(
            &mut fixture,
            resolved_shape,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let item_type = query_declared(
            &mut fixture,
            resolved_item,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert_eq!(
            query_declared(
                &mut fixture,
                resolved_text,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(string_type),
        );
        assert_eq!(
            fixture
                .store
                .declared_type_links(shape)
                .and_then(|links| links.declared_type),
            Some(shape_type),
        );
        assert_eq!(
            fixture
                .store
                .declared_type_links(item)
                .and_then(|links| links.declared_type),
            Some(item_type),
        );
        for (name, expected) in [
            ("ResolvedShape", shape),
            (
                "ResolvedText",
                named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Text"),
            ),
            ("ResolvedItem", item),
        ] {
            let reference = alias_parts(&fixture, name).2;
            assert_eq!(
                fixture
                    .store
                    .symbol_node_links(reference)
                    .and_then(|links| links.resolved_symbol),
                Some(expected),
            );
        }

        let warm = store_state(&fixture.store);
        for symbol in [resolved_shape, resolved_text, resolved_item] {
            query_declared(
                &mut fixture,
                symbol,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
        }
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn qualified_generic_namespace_interfaces_preserve_target_and_argument_identities() {
        let mut fixture = fixture(concat!(
            "namespace Shapes { ",
            "export interface Box<T> {} ",
            "export namespace Deep { export interface Pair<Left, Right> {} } ",
            "} ",
            "type Text = Shapes.Box<string>; ",
            "type Again = Shapes.Box<string>; ",
            "type Mixed = Shapes.Deep.Pair<string, number>;",
        ));
        let box_symbol = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Box");
        let pair_symbol = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Pair");
        let text = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Text");
        let again = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Again");
        let mixed = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Mixed");
        let (string, number) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.number_type)
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let text_type = query_declared(
            &mut fixture,
            text,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert_eq!(
            query_declared(
                &mut fixture,
                again,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(text_type),
        );
        let mixed_type = query_declared(
            &mut fixture,
            mixed,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        for (resolved, symbol, arguments) in [
            (text_type, box_symbol, &[string][..]),
            (mixed_type, pair_symbol, &[string, number][..]),
        ] {
            let reference = validate_direct_generic_reference(&fixture.store, resolved).unwrap();
            assert_eq!(
                Some(reference.target),
                fixture
                    .store
                    .declared_type_links(symbol)
                    .and_then(|links| links.declared_type),
            );
            assert_eq!(reference.type_arguments.as_slice(), arguments);
        }
        for (name, symbol) in [
            ("Text", box_symbol),
            ("Again", box_symbol),
            ("Mixed", pair_symbol),
        ] {
            let reference = alias_parts(&fixture, name).2;
            assert_eq!(
                fixture
                    .store
                    .symbol_node_links(reference)
                    .and_then(|links| links.resolved_symbol),
                Some(symbol),
            );
        }

        let warm = store_state(&fixture.store);
        for (symbol, expected) in [(text, text_type), (again, text_type), (mixed, mixed_type)] {
            assert_eq!(
                query_declared(
                    &mut fixture,
                    symbol,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

