    #[test]
    #[allow(clippy::too_many_lines)] // Keep ambient import identity, both targets, and forged caches together.
    fn ambient_react_type_imports_resolve_cold_and_reject_forged_alias_caches() {
        let PropTypesInferPropsFixture {
            library,
            declarations,
            library_file,
            declaration_file,
            files,
            mut store,
        } = prop_types_declaration_fixture(
            parse_source_file("interface LibraryMarker {}"),
            parse_source_file(concat!(
                "declare module 'prop-types' { ",
                "import { ReactNode, ReactElement } from 'react'; ",
                "export interface Requireable<Value> { value: Value; } ",
                "export const node: Requireable<ReactNode>; ",
                "export const element: Requireable<ReactElement<any>>; ",
                "} ",
                "declare module 'react' { ",
                "export = React; ",
                "namespace React { ",
                "type ReactNode = string | number; ",
                "interface ReactElement<Props> { props: Props; } ",
                "} }",
            )),
            true,
        );
        let bound = files.get(&declaration_file).unwrap();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, files.get(&library_file).unwrap()),
                (&declarations.arena, bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let import = |expected: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::ImportSpecifier(import) = &record.data else {
                        return None;
                    };
                    (identifier_text(&declarations.arena, import.name) == Some(expected)).then_some(
                        NodeRef::new(declarations.arena.id(), declaration_file, node),
                    )
                })
                .unwrap()
        };
        let declaration_named = |kind: SyntaxKind, expected: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == kind
                        && declaration_name(&declarations.arena, record) == Some(expected))
                    .then_some(NodeRef::new(
                        declarations.arena.id(),
                        declaration_file,
                        node,
                    ))
                })
                .unwrap()
        };
        let variable_annotation = |expected: &str| {
            let declaration = declaration_named(SyntaxKind::VariableDeclaration, expected);
            let NodeData::VariableDeclaration(variable) =
                &declarations.arena.get(declaration.node).unwrap().data
            else {
                unreachable!("the declaration was selected by its variable syntax")
            };
            NodeRef::new(declaration.arena, declaration.file, variable.type_.unwrap())
        };
        let reference_named = |expected: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::TypeReferenceNode(reference) = &record.data else {
                        return None;
                    };
                    (identifier_text(&declarations.arena, reference.type_name) == Some(expected))
                        .then_some(NodeRef::new(
                            declarations.arena.id(),
                            declaration_file,
                            node,
                        ))
                })
                .unwrap()
        };
        let node_alias = bound.symbol(import("ReactNode")).unwrap();
        let element_alias = bound.symbol(import("ReactElement")).unwrap();
        let node_target = bound
            .symbol(declaration_named(
                SyntaxKind::TypeAliasDeclaration,
                "ReactNode",
            ))
            .unwrap();
        let element_target = bound
            .symbol(declaration_named(
                SyntaxKind::InterfaceDeclaration,
                "ReactElement",
            ))
            .unwrap();
        let node_reference = reference_named("ReactNode");
        let element_reference = reference_named("ReactElement");
        let node_root = variable_annotation("node");
        let element_root = variable_annotation("element");
        assert!(store.alias_symbol_links(node_alias).is_none());
        assert!(store.alias_symbol_links(element_alias).is_none());
        let aliases = HashMap::new();
        let planner = TypeQueryPlanner::new(&store, &host, None, None, false, &aliases);
        assert_eq!(
            planner.authenticated_ambient_module_import_alias_target(node_reference, node_alias),
            Some(node_target),
        );
        assert_eq!(
            planner.authenticated_ambient_module_import_alias_target(
                element_reference,
                element_alias,
            ),
            Some(element_target),
        );
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let node_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(node_root)
        .unwrap();
        let element_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(element_root)
        .unwrap();
        for (alias, reference, target) in [
            (node_alias, node_reference, node_target),
            (element_alias, element_reference, element_target),
        ] {
            assert!(store.alias_symbol_links(alias).is_none());
            assert_eq!(
                store
                    .symbol_node_links(reference)
                    .and_then(|links| links.resolved_symbol),
                Some(target),
            );
        }
        let warm = store_state(&store);
        for (root, expected) in [(node_root, node_type), (element_root, element_type)] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_type_from_type_node(root),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&store), warm);

        assert!(store.set_alias_symbol_links(
            node_alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(element_target),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        let poisoned = store_state(&store);
        let result = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(node_reference);
        assert!(matches!(
            result,
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::ImportAliasTypeReference { node, alias }
            )) if node == node_reference && alias == node_alias
        ));
        assert_eq!(store_state(&store), poisoned);
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Keep cold namespace imports, warm replay, and forged owners together.
    fn ambient_react_namespace_import_types_resolve_cold_and_reject_forged_module_caches() {
        let PropTypesInferPropsFixture {
            library,
            declarations,
            library_file,
            declaration_file,
            files,
            mut store,
        } = prop_types_declaration_fixture(
            parse_source_file("interface LibraryMarker {}"),
            parse_source_file(concat!(
                "declare module 'prop-types' { ",
                "export interface Validator<Value> { value: Value; } ",
                "export type InferProps<Value> = Value; ",
                "} ",
                "declare module 'forged-prop-types' { ",
                "export interface Validator<Value> { forged: Value; } ",
                "export type InferProps<Value> = number; ",
                "} ",
                "declare module 'react' { ",
                "import * as PropTypes from 'prop-types'; ",
                "namespace React { ",
                "export const validator: PropTypes.Validator<string>; ",
                "export const inferred: PropTypes.InferProps<string>; ",
                "} }",
            )),
            true,
        );
        let bound = files.get(&declaration_file).unwrap();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, files.get(&library_file).unwrap()),
                (&declarations.arena, bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let declaration = |kind: SyntaxKind, expected: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == kind
                        && declaration_name(&declarations.arena, record) == Some(expected))
                    .then_some(NodeRef::new(
                        declarations.arena.id(),
                        declaration_file,
                        node,
                    ))
                })
                .unwrap()
        };
        let module = |expected: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::ModuleDeclaration(module) = &record.data else {
                        return None;
                    };
                    let NodeData::StringLiteral(name) = &declarations.arena.get(module.name)?.data
                    else {
                        return None;
                    };
                    (name.text == expected).then_some(NodeRef::new(
                        declarations.arena.id(),
                        declaration_file,
                        node,
                    ))
                })
                .unwrap()
        };
        let annotation = |expected: &str| {
            let declaration = declaration(SyntaxKind::VariableDeclaration, expected);
            let NodeData::VariableDeclaration(variable) =
                &declarations.arena.get(declaration.node).unwrap().data
            else {
                unreachable!("the declaration was selected by its variable syntax")
            };
            NodeRef::new(declaration.arena, declaration.file, variable.type_.unwrap())
        };
        let binding = declarations
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::NamespaceImport).then_some(NodeRef::new(
                    declarations.arena.id(),
                    declaration_file,
                    node,
                ))
            })
            .unwrap();
        let alias = bound.symbol(binding).unwrap();
        let imported_module = store
            .get_merged_symbol(bound.symbol(module("prop-types")).unwrap())
            .unwrap();
        let forged_module = store
            .get_merged_symbol(bound.symbol(module("forged-prop-types")).unwrap())
            .unwrap();
        let validator = annotation("validator");
        let inferred = annotation("inferred");
        let validator_target = bound
            .symbol(declaration(SyntaxKind::InterfaceDeclaration, "Validator"))
            .unwrap();
        let inferred_target = bound
            .symbol(declaration(SyntaxKind::TypeAliasDeclaration, "InferProps"))
            .unwrap();
        assert!(store.alias_symbol_links(alias).is_none());
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let validator_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(validator)
        .unwrap();
        let inferred_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(inferred)
        .unwrap();
        assert!(store.alias_symbol_links(alias).is_none());
        for (reference, target) in [(validator, validator_target), (inferred, inferred_target)] {
            assert_eq!(
                store
                    .symbol_node_links(reference)
                    .and_then(|links| links.resolved_symbol),
                Some(target),
            );
        }

        let cold_replay = store_state(&store);
        for (reference, expected) in [(validator, validator_type), (inferred, inferred_type)] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_type_from_type_node(reference),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&store), cold_replay);

        assert!(store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(imported_module),
                alias_target: crate::semantic::AliasTargetState::Resolved(imported_module),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        let warm = store_state(&store);
        assert_eq!(
            CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(validator),
            Ok(validator_type),
        );
        assert_eq!(store_state(&store), warm);

        assert!(store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(forged_module),
                alias_target: crate::semantic::AliasTargetState::Resolved(forged_module),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        let poisoned = store_state(&store);
        let result = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(validator);
        assert!(matches!(
            result,
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::ImportAliasTypeReference { node, alias: actual }
            )) if node == validator && actual == alias
        ));
        assert_eq!(store_state(&store), poisoned);
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // The runtime import and export-assignment cache share one proof.
    fn ambient_jsx_runtime_imports_authenticate_react_export_assignment_namespaces() {
        let PropTypesInferPropsFixture {
            library,
            declarations,
            library_file,
            declaration_file,
            files,
            mut store,
        } = prop_types_declaration_fixture(
            parse_source_file("interface LibraryMarker {}"),
            parse_source_file(concat!(
                "declare module 'react' { ",
                "export = React; ",
                "namespace React { ",
                "interface ReactElement<Props> { props: Props; } ",
                "type ReactNode = string; ",
                "} ",
                "namespace Forged { ",
                "interface ReactElement<Props> { forged: Props; } ",
                "type ReactNode = number; ",
                "} } ",
                "declare module 'react/jsx-runtime' { ",
                "import * as React from 'react'; ",
                "export const element: React.ReactElement<string>; ",
                "export const node: React.ReactNode; ",
                "}",
            )),
            true,
        );
        let bound = files.get(&declaration_file).unwrap();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, files.get(&library_file).unwrap()),
                (&declarations.arena, bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let declaration = |kind: SyntaxKind, expected: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == kind
                        && declaration_name(&declarations.arena, record) == Some(expected))
                    .then_some(NodeRef::new(
                        declarations.arena.id(),
                        declaration_file,
                        node,
                    ))
                })
                .unwrap()
        };
        let annotation = |expected: &str| {
            let declaration = declaration(SyntaxKind::VariableDeclaration, expected);
            let NodeData::VariableDeclaration(variable) =
                &declarations.arena.get(declaration.node).unwrap().data
            else {
                unreachable!("the declaration was selected by its variable syntax")
            };
            NodeRef::new(declaration.arena, declaration.file, variable.type_.unwrap())
        };
        let binding = declarations
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::NamespaceImport).then_some(NodeRef::new(
                    declarations.arena.id(),
                    declaration_file,
                    node,
                ))
            })
            .unwrap();
        let assignment = declarations
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ExportAssignment).then_some(NodeRef::new(
                    declarations.arena.id(),
                    declaration_file,
                    node,
                ))
            })
            .unwrap();
        let alias = bound.symbol(binding).unwrap();
        let export_equals = bound.symbol(assignment).unwrap();
        let element = annotation("element");
        let node = annotation("node");
        let element_target = bound
            .symbol(declaration(
                SyntaxKind::InterfaceDeclaration,
                "ReactElement",
            ))
            .unwrap();
        let node_target = bound
            .symbol(declaration(SyntaxKind::TypeAliasDeclaration, "ReactNode"))
            .unwrap();
        let namespace = store.get_parent_of_symbol(element_target).unwrap();
        let forged_element = declarations
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::InterfaceDeclaration
                    && declaration_name(&declarations.arena, record) == Some("ReactElement"))
                .then_some(NodeRef::new(
                    declarations.arena.id(),
                    declaration_file,
                    node,
                ))
            })
            .nth(1)
            .and_then(|declaration| bound.symbol(declaration))
            .unwrap();
        let forged_namespace = store.get_parent_of_symbol(forged_element).unwrap();
        assert!(store.alias_symbol_links(alias).is_none());
        assert!(store.alias_symbol_links(export_equals).is_none());
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let element_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(element)
        .unwrap();
        let node_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(node)
        .unwrap();
        for (reference, target) in [(element, element_target), (node, node_target)] {
            assert_eq!(
                store
                    .symbol_node_links(reference)
                    .and_then(|links| links.resolved_symbol),
                Some(target),
            );
        }
        assert!(store.alias_symbol_links(alias).is_none());
        assert!(store.alias_symbol_links(export_equals).is_none());

        let cold = store_state(&store);
        for (reference, expected) in [(element, element_type), (node, node_type)] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_type_from_type_node(reference),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&store), cold);

        for symbol in [export_equals, alias] {
            assert!(store.set_alias_symbol_links(
                symbol,
                crate::semantic::AliasSymbolLinks {
                    immediate_target: Some(namespace),
                    alias_target: crate::semantic::AliasTargetState::Resolved(namespace),
                    ..crate::semantic::AliasSymbolLinks::default()
                },
            ));
        }
        let warm = store_state(&store);
        assert_eq!(
            CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(element),
            Ok(element_type),
        );
        assert_eq!(store_state(&store), warm);

        for poisoned_alias in [export_equals, alias] {
            assert!(store.set_alias_symbol_links(
                poisoned_alias,
                crate::semantic::AliasSymbolLinks {
                    immediate_target: Some(forged_namespace),
                    alias_target: crate::semantic::AliasTargetState::Resolved(forged_namespace),
                    ..crate::semantic::AliasSymbolLinks::default()
                },
            ));
            let poisoned = store_state(&store);
            let result = CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(element);
            assert!(matches!(
                result,
                Err(DeclaredTypeError::TypeNodeUnavailable(
                    TypeNodeUnavailable::ImportAliasTypeReference { node, alias: actual }
                )) if node == element && actual == alias
            ));
            assert_eq!(store_state(&store), poisoned);
            assert!(store.set_alias_symbol_links(
                poisoned_alias,
                crate::semantic::AliasSymbolLinks {
                    immediate_target: Some(namespace),
                    alias_target: crate::semantic::AliasTargetState::Resolved(namespace),
                    ..crate::semantic::AliasSymbolLinks::default()
                },
            ));
        }
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Keep imported typeof ownership and forged value caches together.
    fn ambient_react_prop_type_queries_authenticate_imported_namespace_values() {
        let PropTypesInferPropsFixture {
            library,
            declarations,
            library_file,
            declaration_file,
            files,
            mut store,
        } = prop_types_declaration_fixture(
            parse_source_file("interface LibraryMarker {}"),
            parse_source_file(concat!(
                "declare module 'prop-types' { ",
                "export const any: string; ",
                "export const node: number; ",
                "} ",
                "declare module 'forged-prop-types' { ",
                "export const any: boolean; ",
                "export const node: string; ",
                "} ",
                "declare module 'react' { ",
                "import * as PropTypes from 'prop-types'; ",
                "namespace React { ",
                "interface ReactPropTypes { ",
                "any: typeof PropTypes.any; ",
                "node: typeof PropTypes.node; ",
                "} } }",
            )),
            true,
        );
        let bound = files.get(&declaration_file).unwrap();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, files.get(&library_file).unwrap()),
                (&declarations.arena, bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let variable = |expected: &str, occurrence: usize| {
            declarations
                .arena
                .iter()
                .filter_map(|(node, record)| {
                    (record.kind == SyntaxKind::VariableDeclaration
                        && declaration_name(&declarations.arena, record) == Some(expected))
                    .then_some(NodeRef::new(
                        declarations.arena.id(),
                        declaration_file,
                        node,
                    ))
                })
                .nth(occurrence)
                .unwrap()
        };
        let query = |expected: &str| {
            declarations
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::TypeQueryNode(query) = &record.data else {
                        return None;
                    };
                    let name = declarations.arena.get(query.expr_name)?;
                    let NodeData::QualifiedName(qualified) = &name.data else {
                        return None;
                    };
                    (identifier_text(&declarations.arena, qualified.right) == Some(expected))
                        .then_some((
                            NodeRef::new(declarations.arena.id(), declaration_file, node),
                            NodeRef::new(
                                declarations.arena.id(),
                                declaration_file,
                                query.expr_name,
                            ),
                        ))
                })
                .unwrap()
        };
        let binding = declarations
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::NamespaceImport).then_some(NodeRef::new(
                    declarations.arena.id(),
                    declaration_file,
                    node,
                ))
            })
            .unwrap();
        let alias = bound.symbol(binding).unwrap();
        let any_symbol = bound.symbol(variable("any", 0)).unwrap();
        let node_symbol = bound.symbol(variable("node", 0)).unwrap();
        let forged_symbol = bound.symbol(variable("any", 1)).unwrap();
        let module = store.get_parent_of_symbol(any_symbol).unwrap();
        let forged_module = store.get_parent_of_symbol(forged_symbol).unwrap();
        let (any, any_name) = query("any");
        let (node, node_name) = query("node");
        let (string, number, boolean) = {
            let bootstrap = store.intrinsic_bootstrap().unwrap();
            (
                bootstrap.string_type,
                bootstrap.number_type,
                bootstrap.boolean_type,
            )
        };
        assert!(store.alias_symbol_links(alias).is_none());
        assert!(store.value_symbol_links(any_symbol).is_none());
        assert!(store.value_symbol_links(node_symbol).is_none());
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        for (reference, name, symbol, expected) in [
            (any, any_name, any_symbol, string),
            (node, node_name, node_symbol, number),
        ] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_type_from_type_node(reference),
                Ok(expected),
            );
            assert_eq!(
                store
                    .symbol_node_links(name)
                    .and_then(|links| links.resolved_symbol),
                Some(symbol),
            );
            assert!(store.value_symbol_links(symbol).is_none());
        }
        assert!(store.alias_symbol_links(alias).is_none());

        let cold = store_state(&store);
        for (reference, expected) in [(any, string), (node, number)] {
            assert_eq!(
                CanonicalTypeQuery::new(
                    &mut store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .get_type_from_type_node(reference),
                Ok(expected),
            );
        }
        assert_eq!(store_state(&store), cold);

        assert!(store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(module),
                alias_target: crate::semantic::AliasTargetState::Resolved(module),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        let warm = store_state(&store);
        assert_eq!(
            CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(any),
            Ok(string),
        );
        assert_eq!(store_state(&store), warm);

        assert!(store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(forged_module),
                alias_target: crate::semantic::AliasTargetState::Resolved(forged_module),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        let poisoned_module = store_state(&store);
        assert!(matches!(
            CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(any),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::ImportAliasTypeReference { node, alias: actual }
            )) if node == any && actual == alias
        ));
        assert_eq!(store_state(&store), poisoned_module);

        assert!(store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(module),
                alias_target: crate::semantic::AliasTargetState::Resolved(module),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        assert!(store.set_value_symbol_links(
            any_symbol,
            ValueSymbolLinks {
                resolved_type: Some(boolean),
                ..ValueSymbolLinks::default()
            },
        ));
        let poisoned_value = store_state(&store);
        assert_eq!(
            CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(any),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidTypeReference(any),
            )),
        );
        assert_eq!(store_state(&store), poisoned_value);
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Proves cross-file ownership and poisoned alias retries.
    fn import_equals_preserves_merged_namespace_interface_identity() {
        let declarations = parse_source_file(concat!(
            "declare module 'foo' { ",
            "namespace B { export interface A {} } ",
            "interface B {} ",
            "export = B; ",
            "}",
        ));
        let importer = parse_source_file(concat!(
            "import foo = require('foo'); ",
            "declare var direct: foo; ",
            "declare var qualified: foo.A;",
        ));
        assert!(declarations.diagnostics.is_empty());
        assert!(importer.diagnostics.is_empty());
        let declaration_file = FileId::new(8_782);
        let importer_file = FileId::new(8_783);
        let mut binder = CanonicalBinder::new();
        for (parsed, file, state) in [
            (
                &declarations,
                declaration_file,
                CanonicalModuleState::Script,
            ),
            (&importer, importer_file, CanonicalModuleState::External),
        ] {
            binder
                .bind_source_file_with_facts(
                    &parsed.arena,
                    parsed.source_file,
                    file,
                    CanonicalSourceFileFacts::new(
                        EscapedName::source(format!("\"/merged-import-{}.ts\"", file.index())),
                        CanonicalSourceLanguage::TypeScript,
                        false,
                        state,
                    ),
                )
                .unwrap();
            binder
                .bind_typescript_declaration_slice(&parsed.arena, file)
                .unwrap();
        }
        let (symbols, files) = binder.finish().try_into_parts().unwrap();
        let mut store = CanonicalTypeMapperStore::from_symbol_store(symbols);
        for (parsed, file) in [
            (&declarations, declaration_file),
            (&importer, importer_file),
        ] {
            assert!(
                store
                    .register_source_file(&parsed.arena, parsed.source_file, file)
                    .is_some()
            );
        }
        store
            .initialize_intrinsic_bootstrap(IntrinsicBootstrapOptions::default())
            .unwrap();
        let declaration_bound = files.get(&declaration_file).unwrap();
        let importer_bound = files.get(&importer_file).unwrap();
        let interface = declarations
            .arena
            .iter()
            .find_map(|(node, record)| {
                let NodeData::InterfaceDeclaration(interface) = &record.data else {
                    return None;
                };
                (identifier_text(&declarations.arena, interface.name) == Some("B")).then_some(
                    NodeRef::new(declarations.arena.id(), declaration_file, node),
                )
            })
            .unwrap();
        let target = store
            .get_merged_symbol(declaration_bound.symbol(interface).unwrap())
            .unwrap();
        let assignment = declarations
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ExportAssignment).then_some(NodeRef::new(
                    declarations.arena.id(),
                    declaration_file,
                    node,
                ))
            })
            .unwrap();
        let export = store
            .get_merged_symbol(declaration_bound.symbol(assignment).unwrap())
            .unwrap();
        let import = importer
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ImportEqualsDeclaration).then_some(NodeRef::new(
                    importer.arena.id(),
                    importer_file,
                    node,
                ))
            })
            .unwrap();
        let alias = store
            .get_merged_symbol(importer_bound.symbol(import).unwrap())
            .unwrap();
        assert!(store.set_alias_symbol_links(
            export,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(target),
                alias_target: crate::semantic::AliasTargetState::Resolved(target),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        assert!(store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(export),
                alias_target: crate::semantic::AliasTargetState::Resolved(target),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&declarations.arena, declaration_bound),
                (&importer.arena, importer_bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        assert_eq!(
            authenticated_merged_namespace_interface(&store, &host, target),
            Some(interface)
        );
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let annotation = |name: &str| {
            importer
                .arena
                .iter()
                .find_map(|(_, record)| {
                    let NodeData::VariableDeclaration(variable) = &record.data else {
                        return None;
                    };
                    (identifier_text(&importer.arena, variable.name) == Some(name)).then(|| {
                        NodeRef::new(
                            importer.arena.id(),
                            importer_file,
                            variable.type_.expect("the imported variable is annotated"),
                        )
                    })
                })
                .unwrap()
        };
        let direct = annotation("direct");
        let qualified = annotation("qualified");

        let direct_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(direct)
        .unwrap();
        assert_eq!(
            store.type_payload(direct_type).unwrap().symbol(),
            Some(target)
        );
        let qualified_type = CanonicalTypeQuery::new(
            &mut store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_from_type_node(qualified)
        .unwrap();
        assert_ne!(qualified_type, direct_type);
        assert_eq!(
            store
                .symbol_node_links(direct)
                .and_then(|links| links.resolved_symbol),
            Some(target)
        );
        assert!(store.value_symbol_links(alias).is_none());

        assert!(store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(target),
                alias_target: crate::semantic::AliasTargetState::Resolved(target),
                ..crate::semantic::AliasSymbolLinks::default()
            },
        ));
        let before = store_state(&store);
        assert!(matches!(
            CanonicalTypeQuery::new(
                &mut store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_from_type_node(direct),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::ImportAliasTypeReference { node, alias: actual }
            )) if node == direct && actual == alias
        ));
        assert_eq!(store_state(&store), before);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn default_import_interface_return_requires_its_authenticated_root_capability() {
        let mut fixture = fixture_with_module_state(
            concat!(
                "import Color from 'pkg'; ",
                "interface Shape { value: string; } ",
                "export declare function styled(): Color; ",
                "let invalid: Color;",
            ),
            CanonicalModuleState::External,
        );
        let binding = fixture
            .parsed
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ImportClause).then_some(NodeRef::new(
                    fixture.parsed.arena.id(),
                    fixture.file,
                    node,
                ))
            })
            .unwrap();
        let alias = node_symbol(&fixture, binding);
        let target = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Shape");
        assert!(fixture.store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(target),
                alias_target: crate::semantic::AliasTargetState::Resolved(target),
                referenced: false,
                type_only_declaration: None,
            },
        ));
        let declaration = named_node(&fixture, SyntaxKind::FunctionDeclaration, "styled");
        let NodeData::FunctionDeclaration(function) =
            &fixture.parsed.arena.get(declaration.node).unwrap().data
        else {
            unreachable!()
        };
        let root = NodeRef::new(declaration.arena, declaration.file, function.type_.unwrap());
        let capability =
            CanonicalTypeReferenceAliasTarget::new(root, root, binding, alias, target, target);
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let resolved = CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .with_type_reference_alias_targets([capability])
        .unwrap()
        .get_type_from_type_node(root)
        .unwrap();
        assert_eq!(
            fixture
                .store
                .declared_type_links(target)
                .and_then(|links| links.declared_type),
            Some(resolved),
        );
        assert_eq!(
            fixture
                .store
                .symbol_node_links(root)
                .and_then(|links| links.resolved_symbol),
            Some(target),
        );
        assert!(fixture.store.value_symbol_links(alias).is_none());

        let invalid = variable_type_node(&fixture, "invalid");
        let invalid_capability = CanonicalTypeReferenceAliasTarget::new(
            invalid, invalid, binding, alias, target, target,
        );
        let before = store_state(&fixture.store);
        let result = CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .with_type_reference_alias_targets([invalid_capability]);
        assert!(matches!(
            result,
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidImportAliasTarget { .. }
            ))
        ));
        assert_eq!(store_state(&fixture.store), before);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn unresolved_source_generic_constraints_recover_once_with_exact_ts2304() {
        let mut fixture = fixture("function value<Item extends Missing>(item: Item) {}");
        let declaration = named_node(&fixture, SyntaxKind::FunctionDeclaration, "value");
        let NodeData::FunctionDeclaration(function) =
            &fixture.parsed.arena.get(declaration.node).unwrap().data
        else {
            unreachable!()
        };
        let parameter = NodeRef::new(
            declaration.arena,
            declaration.file,
            function.type_parameters.as_ref().unwrap().nodes[0],
        );
        let NodeData::TypeParameterDeclaration(parameter_data) =
            &fixture.parsed.arena.get(parameter.node).unwrap().data
        else {
            unreachable!()
        };
        let constraint = NodeRef::new(
            parameter.arena,
            parameter.file,
            parameter_data.constraint.unwrap(),
        );
        let NodeData::TypeReferenceNode(reference) =
            &fixture.parsed.arena.get(constraint.node).unwrap().data
        else {
            unreachable!()
        };
        let name = NodeRef::new(constraint.arena, constraint.file, reference.type_name);
        let error = fixture.store.intrinsic_bootstrap().unwrap().error_type;
        let before = store_state(&fixture.store);
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .preflight_type_from_type_node(constraint)
        .unwrap();
        assert_eq!(store_state(&fixture.store), before);

        assert_eq!(
            query_node(&mut fixture, constraint, &mut diagnostics),
            Ok(error),
        );
        assert!(
            fixture
                .store
                .source_recovered_unresolved_type_reference_is_exact(constraint, error)
        );
        assert!(fixture.store.symbol_node_links(constraint).is_none());
        assert!(fixture.store.symbol_node_links(name).is_none());
        let [diagnostic] = diagnostics.as_slice() else {
            panic!("the missing constraint must report exactly one diagnostic")
        };
        assert_eq!(diagnostic.node, Some(name));
        assert_eq!(diagnostic.diagnostic.code(), 2304);
        assert_eq!(diagnostic.diagnostic.arguments, ["Missing"]);

        let warm = store_state(&fixture.store);
        assert_eq!(
            query_node(&mut fixture, constraint, &mut diagnostics),
            Ok(error),
        );
        assert_eq!(store_state(&fixture.store), warm);
        assert_eq!(diagnostics.len(), 1);

        let parameter_symbol = node_symbol(&fixture, parameter);
        assert!(fixture.store.set_symbol_node_links(
            constraint,
            SymbolNodeLinks {
                resolved_symbol: Some(parameter_symbol),
            },
        ));
        let forged = store_state(&fixture.store);
        assert!(matches!(
            query_node(&mut fixture, constraint, &mut diagnostics),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidTypeReference(node)
            )) if node == constraint
        ));
        assert_eq!(store_state(&fixture.store), forged);
        assert_eq!(diagnostics.len(), 1);
    }

    #[test]
    fn imported_generic_callable_annotations_require_their_exact_root_capabilities() {
        let mut fixture = fixture_with_module_state(
            concat!(
                "import type { Remote as Local } from 'pkg'; ",
                "type Remote<T> = T; ",
                "function accept(value: Local<string>): Local<number> { return 1; }",
            ),
            CanonicalModuleState::External,
        );
        let binding = named_node(&fixture, SyntaxKind::ImportSpecifier, "Local");
        let alias = node_symbol(&fixture, binding);
        let target = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Remote");
        assert!(fixture.store.set_alias_symbol_links(
            alias,
            crate::semantic::AliasSymbolLinks {
                immediate_target: Some(target),
                alias_target: crate::semantic::AliasTargetState::Resolved(target),
                referenced: false,
                type_only_declaration: Some(binding),
            },
        ));
        let declaration = named_node(&fixture, SyntaxKind::FunctionDeclaration, "accept");
        let owner = node_symbol(&fixture, declaration);
        let NodeData::FunctionDeclaration(function) =
            &fixture.parsed.arena.get(declaration.node).unwrap().data
        else {
            unreachable!()
        };
        let parameter = NodeRef::new(
            declaration.arena,
            declaration.file,
            function.parameters.nodes[0],
        );
        let parameter_root = parameter_type_node(&fixture, parameter);
        let return_root = NodeRef::new(
            declaration.arena,
            declaration.file,
            function
                .type_
                .expect("function has an explicit return type"),
        );
        let parameter_capability = CanonicalTypeReferenceAliasTarget::new(
            parameter_root,
            parameter_root,
            binding,
            alias,
            target,
            target,
        );
        let return_capability = CanonicalTypeReferenceAliasTarget::new(
            return_root,
            return_root,
            binding,
            alias,
            target,
            target,
        );
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .with_type_reference_alias_targets([parameter_capability, return_capability])
        .unwrap()
        .preflight_type_of_source_callable(declaration, owner)
        .unwrap();

        CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .with_type_reference_alias_targets([parameter_capability])
        .unwrap()
        .get_type_of_source_callable(declaration, owner)
        .unwrap();
        let signature = function_signature(&fixture.store, declaration);
        let (string, number) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.string_type, bootstrap.number_type)
        };
        assert_eq!(
            fixture.store.callable_signature_parameter_types(signature),
            Some(&[string][..]),
        );
        assert_eq!(
            CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .with_type_reference_alias_targets([parameter_capability])
            .unwrap()
            .get_return_type_of_signature(signature),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::ImportAliasCapabilityUnsupported(parameter_root),
            )),
        );
        assert_eq!(
            CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .with_type_reference_alias_targets([return_capability])
            .unwrap()
            .get_return_type_of_signature(signature),
            Ok(number),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn malformed_literal_payloads_and_operators_fail_before_semantic_writes() {
        let mut malformed_number = fixture_with_mutation("type Bad = 1;", |parsed| {
            let numeric = parsed
                .arena
                .iter()
                .find_map(|(id, node)| (node.kind == SyntaxKind::NumericLiteral).then_some(id))
                .unwrap();
            let NodeData::NumericLiteral(data) = &mut parsed.arena.get_mut(numeric).unwrap().data
            else {
                unreachable!()
            };
            data.text = "not-a-number".into();
        });
        assert_invalid_literal_query_is_atomic(&mut malformed_number);

        let mut invalid_prefix = fixture_with_mutation("type Bad = -1n;", |parsed| {
            let prefix = parsed
                .arena
                .iter()
                .find_map(|(id, node)| {
                    (node.kind == SyntaxKind::PrefixUnaryExpression).then_some(id)
                })
                .unwrap();
            let NodeData::PrefixUnaryExpression(data) =
                &mut parsed.arena.get_mut(prefix).unwrap().data
            else {
                unreachable!()
            };
            data.operator = SyntaxKind::PlusToken;
        });
        assert_invalid_literal_query_is_atomic(&mut invalid_prefix);
    }

