    #[test]
    fn lazy_declared_values_reject_paired_literal_cache_changes() {
        let mut fixture = fixture(concat!(
            "interface Catalog { key: 'expected'; other: 'wrong'; } ",
            "declare var catalog: Catalog;",
        ));
        let variable = named_symbol(&fixture, SyntaxKind::VariableDeclaration, "catalog");
        let owner = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Catalog");
        let members = fixture.store.symbol(owner).unwrap().members().unwrap();
        let key = fixture
            .store
            .symbol_table(members)
            .unwrap()
            .get_source("key")
            .unwrap();
        let other = fixture
            .store
            .symbol_table(members)
            .unwrap()
            .get_source("other")
            .unwrap();
        let annotation = fixture
            .store
            .source_direct_type_annotation(
                fixture
                    .store
                    .symbol(key)
                    .unwrap()
                    .value_declaration()
                    .unwrap(),
            )
            .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let receiver = query_declared_value(&mut fixture, variable, &mut diagnostics).unwrap();
        let expected = query_declared_value(&mut fixture, key, &mut diagnostics).unwrap();
        let wrong = query_declared_value(&mut fixture, other, &mut diagnostics).unwrap();
        assert_ne!(expected, wrong);
        let provenance = fixture.store.declared_value_provenance(key).unwrap();
        assert!(fixture.store.set_type_node_links(
            annotation,
            TypeNodeLinks {
                resolved_type: Some(wrong),
                ..TypeNodeLinks::default()
            }
        ));
        assert!(fixture.store.set_value_symbol_links(
            key,
            ValueSymbolLinks {
                resolved_type: Some(wrong),
                ..ValueSymbolLinks::default()
            }
        ));
        let before = union_state(&fixture.store);
        assert!(
            fixture
                .store
                .resolved_own_property(receiver, "key")
                .is_err()
        );
        assert!(query_declared_value(&mut fixture, key, &mut diagnostics).is_err());
        assert_eq!(union_state(&fixture.store), before);
        assert_eq!(
            fixture.store.declared_value_provenance(key),
            Some(provenance)
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn value_type_query_reuses_earlier_ambient_let_annotation_before_value_publication() {
        let mut fixture = fixture(concat!(
            "declare let value: { id: '00' } | { id: '01' }; ",
            "declare let result: typeof value | { id: '02' };",
        ));
        let symbol = fixture
            .store
            .get_merged_symbol(named_symbol(
                &fixture,
                SyntaxKind::VariableDeclaration,
                "value",
            ))
            .unwrap();
        let annotation = variable_type_node(&fixture, "value");
        let result = variable_type_node(&fixture, "result");
        let query = fixture
            .parsed
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::TypeQuery).then_some(NodeRef::new(
                    fixture.parsed.arena.id(),
                    fixture.file,
                    node,
                ))
            })
            .unwrap();
        let name = type_query_name(&fixture, query);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let before = union_state(&fixture.store);
        {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .preflight_type_from_type_node(result)
            .unwrap();
        }
        assert_eq!(union_state(&fixture.store), before);
        assert!(fixture.store.type_node_links(annotation).is_none());
        assert!(fixture.store.type_node_links(query).is_none());
        assert!(fixture.store.symbol_node_links(name).is_none());

        let expected = query_node(&mut fixture, annotation, &mut diagnostics).unwrap();
        assert!(fixture.store.value_symbol_links(symbol).is_none());

        assert_eq!(
            query_node(&mut fixture, query, &mut diagnostics),
            Ok(expected),
        );
        assert_eq!(
            fixture.store.type_node_links(query),
            Some(&TypeNodeLinks {
                resolved_type: Some(expected),
                ..TypeNodeLinks::default()
            }),
        );
        assert_eq!(
            fixture.store.symbol_node_links(name),
            Some(&SymbolNodeLinks {
                resolved_symbol: Some(symbol),
            }),
        );
        assert!(fixture.store.symbol_node_links(query).is_none());
        assert!(fixture.store.value_symbol_links(symbol).is_none());

        let combined = query_node(&mut fixture, result, &mut diagnostics).unwrap();
        assert_eq!(union_types(&fixture.store, combined).len(), 3);
        assert!(
            union_types(&fixture.store, expected)
                .iter()
                .all(|member| union_types(&fixture.store, combined).contains(member))
        );

        let warm = union_state(&fixture.store);
        assert_eq!(
            query_node(&mut fixture, query, &mut diagnostics),
            Ok(expected),
        );
        assert_eq!(
            query_node(&mut fixture, result, &mut diagnostics),
            Ok(combined),
        );
        assert_eq!(union_state(&fixture.store), warm);
        assert!(fixture.store.value_symbol_links(symbol).is_none());
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn value_type_queries_materialize_authenticated_abstract_and_concrete_class_constructors() {
        for (source, abstract_class) in [
            (
                concat!(
                    "abstract class Model { abstract value: string; } ",
                    "declare let result: typeof Model;",
                ),
                true,
            ),
            (
                "class Model { value!: string; } declare let result: typeof Model;",
                false,
            ),
        ] {
            let mut fixture = fixture(source);
            let symbol = named_symbol(&fixture, SyntaxKind::ClassDeclaration, "Model");
            let query = variable_type_node(&fixture, "result");
            let name = type_query_name(&fixture, query);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let cold = function_store_state(&fixture.store);
            {
                let host = post_global_host(
                    &fixture.parsed.arena,
                    fixture.files.get(&fixture.file).unwrap(),
                );
                CanonicalTypeQuery::new(
                    &mut fixture.store,
                    &host,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .unwrap()
                .preflight_type_from_type_node(query)
                .unwrap();
            }
            assert_eq!(function_store_state(&fixture.store), cold, "{source}");
            assert!(fixture.store.declared_type_links(symbol).is_none());
            assert!(fixture.store.value_symbol_links(symbol).is_none());

            let value = query_node(&mut fixture, query, &mut diagnostics).unwrap();
            let (authenticated, signature) =
                authenticated_class_constructor_value(&fixture.store, symbol).unwrap();

            assert_eq!(value, authenticated, "{source}");
            assert_eq!(
                fixture.store.signature(signature).unwrap().flags(),
                SignatureFlags::CONSTRUCT
                    | if abstract_class {
                        SignatureFlags::ABSTRACT
                    } else {
                        SignatureFlags::NONE
                    },
                "{source}",
            );
            assert_eq!(
                fixture.store.type_node_links(query),
                Some(&TypeNodeLinks {
                    resolved_type: Some(value),
                    ..TypeNodeLinks::default()
                }),
                "{source}",
            );
            assert_eq!(
                fixture.store.symbol_node_links(name),
                Some(&SymbolNodeLinks {
                    resolved_symbol: Some(symbol),
                }),
                "{source}",
            );

            let warm = function_store_state(&fixture.store);
            assert_eq!(query_node(&mut fixture, query, &mut diagnostics), Ok(value));
            assert_eq!(function_store_state(&fixture.store), warm, "{source}");
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn abstract_class_constructor_union_preflights_every_provider_without_publication() {
        let mut fixture = fixture(concat!(
            "abstract class Abstract { abstract value: string; } ",
            "class Concrete {} ",
            "type Choice = typeof Abstract | typeof Concrete;",
        ));
        let abstract_class = named_symbol(&fixture, SyntaxKind::ClassDeclaration, "Abstract");
        let concrete_class = named_symbol(&fixture, SyntaxKind::ClassDeclaration, "Concrete");
        let union = alias_parts(&fixture, "Choice").2;
        let queries = fixture
            .parsed
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::TypeQuery).then_some(NodeRef::new(
                    fixture.parsed.arena.id(),
                    fixture.file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        assert_eq!(queries.len(), 2);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let cold = function_store_state(&fixture.store);
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );

        CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .preflight_type_from_type_node(union)
        .unwrap();

        assert_eq!(function_store_state(&fixture.store), cold);
        for class in [abstract_class, concrete_class] {
            assert!(fixture.store.declared_type_links(class).is_none());
            assert!(fixture.store.value_symbol_links(class).is_none());
        }
        for query in queries {
            assert!(fixture.store.type_node_links(query).is_none());
            assert!(
                fixture
                    .store
                    .symbol_node_links(type_query_name(&fixture, query))
                    .is_none()
            );
        }
        assert!(fixture.store.type_node_links(union).is_none());
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn forged_class_constructor_type_queries_fail_before_class_or_query_publication() {
        for corruption in 0..3 {
            let mut fixture = fixture(concat!(
                "abstract class Model { abstract value: string; } ",
                "class Other {} ",
                "declare let result: typeof Model;",
            ));
            let symbol = named_symbol(&fixture, SyntaxKind::ClassDeclaration, "Model");
            let other = named_symbol(&fixture, SyntaxKind::ClassDeclaration, "Other");
            let query = variable_type_node(&fixture, "result");
            let name = type_query_name(&fixture, query);
            let wrong = fixture.store.intrinsic_bootstrap().unwrap().number_type;
            match corruption {
                0 => {
                    assert!(fixture.store.set_type_node_links(
                        query,
                        TypeNodeLinks {
                            resolved_type: Some(wrong),
                            ..TypeNodeLinks::default()
                        },
                    ));
                    assert!(fixture.store.set_symbol_node_links(
                        name,
                        SymbolNodeLinks {
                            resolved_symbol: Some(symbol),
                        },
                    ));
                }
                1 => assert!(fixture.store.set_symbol_node_links(
                    name,
                    SymbolNodeLinks {
                        resolved_symbol: Some(other),
                    },
                )),
                2 => {
                    let annotation = fixture
                        .parsed
                        .arena
                        .iter()
                        .find_map(|(node, record)| {
                            (record.kind == SyntaxKind::StringKeyword).then_some(NodeRef::new(
                                fixture.parsed.arena.id(),
                                fixture.file,
                                node,
                            ))
                        })
                        .unwrap();
                    assert!(fixture.store.set_type_node_links(
                        annotation,
                        TypeNodeLinks {
                            resolved_type: Some(wrong),
                            ..TypeNodeLinks::default()
                        },
                    ));
                }
                _ => unreachable!("only class type-query cache poison is visited"),
            }
            let state = function_store_state(&fixture.store);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();

            assert!(
                query_node(&mut fixture, query, &mut diagnostics).is_err(),
                "corruption case {corruption}",
            );
            assert_eq!(
                function_store_state(&fixture.store),
                state,
                "corruption case {corruption}",
            );
            assert!(fixture.store.declared_type_links(symbol).is_none());
            assert!(fixture.store.value_symbol_links(symbol).is_none());
            assert!(diagnostics.is_empty());
        }
    }

