    #[test]
    fn unsupported_value_type_queries_fail_before_semantic_writes() {
        let cases = [
            ("let value = 'ok'; let result: typeof value;", true),
            ("const value = 'ok'; let result: typeof value;", false),
            (
                "const value = 'ok'; let result: typeof value<string>;",
                true,
            ),
            (
                "const value = 'ok'; let result: typeof value.missing;",
                true,
            ),
        ];

        for (source, seed_initializer) in cases {
            let mut fixture = fixture(source);
            let query = variable_type_node(&fixture, "result");
            let name = type_query_name(&fixture, query);
            if seed_initializer {
                let initializer = variable_initializer_node(&fixture, "value");
                let expected = fixture.store.intrinsic_bootstrap().unwrap().string_type;
                assert!(fixture.store.set_type_node_links(
                    initializer,
                    TypeNodeLinks {
                        resolved_type: Some(expected),
                        ..TypeNodeLinks::default()
                    },
                ));
            }

            let before = store_state(&fixture.store);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            assert_eq!(
                query_node(&mut fixture, query, &mut diagnostics),
                Err(DeclaredTypeError::TypeNodeUnavailable(
                    TypeNodeUnavailable::UnsupportedSyntax {
                        node: query,
                        kind: SyntaxKind::TypeQuery,
                    },
                )),
                "source: {source}",
            );
            assert_eq!(store_state(&fixture.store), before, "source: {source}");
            assert!(fixture.store.type_node_links(query).is_none());
            assert!(fixture.store.symbol_node_links(query).is_none());
            assert!(fixture.store.symbol_node_links(name).is_none());
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn corrupted_value_type_query_caches_fail_atomically() {
        for corruption in 0..7 {
            let mut fixture =
                fixture("const value = 'ok'; const other = 'bad'; let result: typeof value;");
            let symbol = fixture
                .store
                .get_merged_symbol(named_symbol(
                    &fixture,
                    SyntaxKind::VariableDeclaration,
                    "value",
                ))
                .unwrap();
            let other = fixture
                .store
                .get_merged_symbol(named_symbol(
                    &fixture,
                    SyntaxKind::VariableDeclaration,
                    "other",
                ))
                .unwrap();
            let query = variable_type_node(&fixture, "result");
            let name = type_query_name(&fixture, query);
            let initializer = variable_initializer_node(&fixture, "value");
            let (expected, wrong) = {
                let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
                (bootstrap.string_type, bootstrap.number_type)
            };
            assert!(fixture.store.set_type_node_links(
                initializer,
                TypeNodeLinks {
                    resolved_type: Some(expected),
                    ..TypeNodeLinks::default()
                },
            ));

            match corruption {
                0 => {
                    assert!(fixture.store.set_type_node_links(
                        query,
                        TypeNodeLinks {
                            resolved_type: Some(wrong),
                            ..TypeNodeLinks::default()
                        },
                    ));
                    assert!(fixture.store.set_symbol_node_links(
                        name,
                        SymbolNodeLinks {
                            resolved_symbol: Some(symbol),
                        },
                    ));
                }
                1 => {
                    assert!(fixture.store.set_type_node_links(
                        query,
                        TypeNodeLinks {
                            resolved_type: Some(expected),
                            ..TypeNodeLinks::default()
                        },
                    ));
                    assert!(fixture.store.set_symbol_node_links(
                        name,
                        SymbolNodeLinks {
                            resolved_symbol: Some(other),
                        },
                    ));
                }
                2 => {
                    assert!(fixture.store.set_value_symbol_links(
                        symbol,
                        ValueSymbolLinks {
                            resolved_type: Some(wrong),
                            ..ValueSymbolLinks::default()
                        },
                    ));
                }
                3 => {
                    assert!(fixture.store.set_type_node_links(
                        query,
                        TypeNodeLinks {
                            resolved_type: Some(expected),
                            ..TypeNodeLinks::default()
                        },
                    ));
                }
                4 => {
                    assert!(fixture.store.set_symbol_node_links(
                        name,
                        SymbolNodeLinks {
                            resolved_symbol: Some(symbol),
                        },
                    ));
                }
                5 => {
                    assert!(fixture.store.set_type_node_links(
                        query,
                        TypeNodeLinks {
                            resolved_type: Some(expected),
                            outer_type_parameters: Some(vec![expected]),
                        },
                    ));
                    assert!(fixture.store.set_symbol_node_links(
                        name,
                        SymbolNodeLinks {
                            resolved_symbol: Some(symbol),
                        },
                    ));
                }
                6 => {
                    assert!(fixture.store.set_type_node_links(
                        query,
                        TypeNodeLinks {
                            resolved_type: Some(expected),
                            ..TypeNodeLinks::default()
                        },
                    ));
                    assert!(fixture.store.set_symbol_node_links(
                        name,
                        SymbolNodeLinks {
                            resolved_symbol: Some(symbol),
                        },
                    ));
                    assert!(fixture.store.set_symbol_node_links(
                        query,
                        SymbolNodeLinks {
                            resolved_symbol: Some(symbol),
                        },
                    ));
                }
                _ => unreachable!(),
            }

            let before = store_state(&fixture.store);
            let cached_type = fixture.store.type_node_links(query).cloned();
            let cached_symbol = fixture.store.symbol_node_links(name).cloned();
            let wrapper_symbol = fixture.store.symbol_node_links(query).cloned();
            let value_links = fixture.store.value_symbol_links(symbol).cloned();
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            assert_eq!(
                query_node(&mut fixture, query, &mut diagnostics),
                Err(DeclaredTypeError::TypeNodeUnavailable(
                    TypeNodeUnavailable::InvalidTypeReference(query),
                )),
                "corruption case {corruption}",
            );
            assert_eq!(store_state(&fixture.store), before);
            assert_eq!(fixture.store.type_node_links(query).cloned(), cached_type);
            assert_eq!(
                fixture.store.symbol_node_links(name).cloned(),
                cached_symbol
            );
            assert_eq!(
                fixture.store.symbol_node_links(query).cloned(),
                wrapper_symbol
            );
            assert_eq!(
                fixture.store.value_symbol_links(symbol).cloned(),
                value_links
            );
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn every_remaining_deferred_type_node_family_and_recursive_array_fail_atomically() {
        let source = concat!(
            "declare const value: string; ",
            "type ArrayAlias = string[]; ",
            "type IntersectionAlias = object & {}; ",
            "type OperatorAlias = keyof object; ",
            "type MappedAlias<T> = { [K in keyof T]: T[K] }; ",
            "type ConditionalAlias<T> = T extends string ? string : number; ",
            "type InferAlias<T> = T extends infer U ? U : never; ",
            "type ImportTypeAlias = import('pkg').Value; type QueryAlias = typeof value; ",
            "type ThisAlias = this; type RecursiveArray = RecursiveArray[];",
        );
        let aliases = [
            "ArrayAlias",
            "IntersectionAlias",
            "OperatorAlias",
            "MappedAlias",
            "ImportTypeAlias",
            "QueryAlias",
            "ThisAlias",
            "RecursiveArray",
        ];
        let mut fixture = fixture(source);
        for name in aliases {
            let alias = named_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, name);
            let before = store_state(&fixture.store);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let result = query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            );
            assert!(
                matches!(result, Err(DeclaredTypeError::TypeNodeUnavailable(_))),
                "unexpected deferred type node for {name}: {result:?}"
            );
            assert_eq!(store_state(&fixture.store), before, "alias {name}");
            assert!(diagnostics.is_empty());
            assert!(fixture.store.type_alias_links(alias).is_none());
        }
    }

    #[test]
    fn jsdoc_foreign_and_stale_inputs_fail_before_checker_writes() {
        let mut jsdoc = fixture_with_mutation("type A = string;", |parsed| {
            let body = parsed
                .arena
                .iter()
                .find_map(|(_, node)| {
                    let NodeData::TypeAliasDeclaration(alias) = &node.data else {
                        return None;
                    };
                    Some(alias.type_)
                })
                .unwrap();
            parsed.arena.get_mut(body).unwrap().flags = NodeFlags(NODE_FLAG_JSDOC);
        });
        let alias = named_symbol(&jsdoc, SyntaxKind::TypeAliasDeclaration, "A");
        let before = store_state(&jsdoc.store);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        assert!(matches!(
            query_declared(
                &mut jsdoc,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::JsDoc(_)
            ))
        ));
        assert_eq!(store_state(&jsdoc.store), before);
        assert!(diagnostics.is_empty());

        let mut local = fixture("type Local = string;");
        let foreign = fixture("type Foreign = string;");
        let foreign_body = alias_parts(&foreign, "Foreign").2;
        let before = store_state(&local.store);
        let host = post_global_host(&local.parsed.arena, local.files.get(&local.file).unwrap());
        {
            let mut query = CanonicalTypeQuery::new(
                &mut local.store,
                &host,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            assert!(matches!(
                query.get_type_from_type_node(foreign_body),
                Err(DeclaredTypeError::Unavailable(
                    DeclaredTypeUnavailable::MissingOrForeignFacts(_)
                ))
            ));
        }
        assert_eq!(store_state(&local.store), before);

        let mut stale = fixture("type Stale = string;");
        let before = store_state(&stale.store);
        let orphan = stale
            .parsed
            .arena
            .iter()
            .next()
            .map(|(_, node)| node.clone())
            .unwrap();
        stale.parsed.arena.alloc(orphan);
        assert!(matches!(
            DeclaredTypeHost::new([(&stale.parsed.arena, stale.files.get(&stale.file).unwrap())]),
            Err(DeclaredTypeHostError::ArenaRevisionMismatch { .. })
        ));
        assert_eq!(store_state(&stale.store), before);
    }

    fn canonical_fixture_symbol(
        fixture: &Fixture,
        kind: SyntaxKind,
        name: &str,
    ) -> SemanticSymbolId {
        fixture
            .store
            .get_merged_symbol(named_symbol(fixture, kind, name))
            .unwrap()
    }

    fn property_type_literal_child(fixture: &Fixture, literal: NodeRef, index: usize) -> NodeRef {
        let NodeData::TypeLiteralNode(literal_data) =
            &fixture.parsed.arena.get(literal.node).unwrap().data
        else {
            panic!("expected a type literal")
        };
        let member = literal_data.members.nodes[index];
        let NodeData::PropertyDeclaration(property) =
            &fixture.parsed.arena.get(member).unwrap().data
        else {
            panic!("the parser currently emits property declarations for type members")
        };
        NodeRef::new(
            literal.arena,
            literal.file,
            property.type_.expect("property has an annotation"),
        )
    }

    #[test]
    fn parser_property_members_feed_ordered_type_literal_and_interface_construction() {
        let mut fixture = fixture(concat!(
            "interface Model { readonly id: string; optional?: number; ",
            "nested: { enabled: boolean; leaf: { value: null } } } ",
            "type Shape = { first: string; readonly second?: number; ",
            "nested: { count: bigint } }; ",
            r#"const sample = { field: "value" };"#,
        ));
        let interface_node = named_node(&fixture, SyntaxKind::InterfaceDeclaration, "Model");
        let NodeData::InterfaceDeclaration(interface_data) =
            &fixture.parsed.arena.get(interface_node.node).unwrap().data
        else {
            unreachable!()
        };
        assert!(interface_data.members.nodes.iter().all(|member| {
            fixture.parsed.arena.get(*member).unwrap().kind == SyntaxKind::PropertyDeclaration
        }));
        let (_, _, shape_node) = alias_parts(&fixture, "Shape");
        let NodeData::TypeLiteralNode(shape_data) =
            &fixture.parsed.arena.get(shape_node.node).unwrap().data
        else {
            unreachable!()
        };
        assert!(shape_data.members.nodes.iter().all(|member| {
            fixture.parsed.arena.get(*member).unwrap().kind == SyntaxKind::PropertyDeclaration
        }));
        let object_node = fixture
            .parsed
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ObjectLiteralExpression).then_some(NodeRef::new(
                    fixture.parsed.arena.id(),
                    fixture.file,
                    node,
                ))
            })
            .unwrap();

        let model = canonical_fixture_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Model");
        let shape = canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Shape");
        let (model_plan, shape_plan, object_plan) = {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            (
                object_members::plan_interface(&fixture.store, &host, model).unwrap(),
                object_members::plan_type_literal(&fixture.store, &host, shape_node, Some(shape))
                    .unwrap(),
                object_members::plan_object_literal(&fixture.store, &host, object_node).unwrap(),
            )
        };
        assert_eq!(
            model_plan
                .properties
                .iter()
                .map(|property| property.name.as_str())
                .collect::<Vec<_>>(),
            ["id", "optional", "nested"]
        );
        assert_eq!(
            shape_plan
                .properties
                .iter()
                .map(|property| property.name.as_str())
                .collect::<Vec<_>>(),
            ["first", "second", "nested"]
        );
        assert!(!model_plan.properties[0].optional);
        assert!(model_plan.properties[1].optional);
        assert!(shape_plan.properties[1].optional);
        assert_eq!(
            model_plan
                .properties
                .iter()
                .map(|property| property.readonly)
                .collect::<Vec<_>>(),
            [true, false, false]
        );
        assert_eq!(
            shape_plan
                .properties
                .iter()
                .map(|property| property.readonly)
                .collect::<Vec<_>>(),
            [false, true, false]
        );
        assert_eq!(object_plan.properties.len(), 1);
        assert!(!object_plan.properties[0].readonly);
        for plan in [&model_plan, &shape_plan, &object_plan] {
            for property in &plan.properties {
                let name = fixture.parsed.arena.get(property.name_node.node).unwrap();
                let NodeData::Identifier(identifier) = &name.data else {
                    panic!("planned property name must remain an identifier")
                };
                assert_eq!(identifier.text, property.name);
                assert_eq!(name.parent, Some(property.declaration.node));
            }
        }
        let before_rejected_publication = store_state(&fixture.store);
        let (error_type, string_type) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (bootstrap.error_type, bootstrap.string_type)
        };
        assert_eq!(
            object_members::publish_property_members(
                &mut fixture.store,
                &object_plan,
                PropertyObjectState::Shell(error_type),
                &[string_type],
            ),
            Err(PropertyObjectError::InvalidObjectLiteral(object_node))
        );
        assert_eq!(store_state(&fixture.store), before_rejected_publication);
        assert!(
            fixture
                .store
                .value_symbol_links(object_plan.properties[0].symbol)
                .is_none()
        );

        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let model_type = query_declared(
            &mut fixture,
            model,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let shape_type = query_declared(
            &mut fixture,
            shape,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert!(diagnostics.is_empty());

        let TypeData::Interface(model_data) =
            fixture.store.type_payload(model_type).unwrap().data()
        else {
            panic!("interface construction must retain interface identity")
        };
        assert_eq!(
            fixture
                .store
                .type_payload(model_type)
                .unwrap()
                .object_flags(),
            ObjectFlags::INTERFACE | ObjectFlags::MEMBERS_RESOLVED
        );
        let expected_model_properties = model_plan
            .properties
            .iter()
            .map(|property| property.symbol)
            .collect::<Vec<_>>();
        assert_eq!(
            model_data.reference.object.structured.properties.as_deref(),
            Some(expected_model_properties.as_slice())
        );
        let TypeData::Object(shape_data) = fixture.store.type_payload(shape_type).unwrap().data()
        else {
            panic!("type literal aliases construct anonymous object types")
        };
        assert_eq!(
            fixture
                .store
                .type_payload(shape_type)
                .unwrap()
                .object_flags(),
            ObjectFlags::ANONYMOUS | ObjectFlags::MEMBERS_RESOLVED
        );
        let expected_shape_properties = shape_plan
            .properties
            .iter()
            .map(|property| property.symbol)
            .collect::<Vec<_>>();
        assert_eq!(
            shape_data.structured.properties.as_deref(),
            Some(expected_shape_properties.as_slice())
        );
        let alias = fixture
            .store
            .type_payload(shape_type)
            .unwrap()
            .alias()
            .and_then(|alias| fixture.store.type_alias(alias))
            .unwrap();
        assert_eq!(alias.symbol(), Some(shape));
        assert_eq!(alias.type_arguments(), None);
        assert_eq!(
            fixture
                .store
                .value_symbol_links(model_plan.properties[1].symbol)
                .and_then(|links| links.resolved_type),
            Some(fixture.store.intrinsic_bootstrap().unwrap().number_type)
        );
        assert_eq!(
            fixture
                .store
                .symbol(model_plan.properties[0].symbol)
                .unwrap()
                .check_flags(),
            CheckFlags::READONLY
        );

        let warm_state = store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                model,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(model_type)
        );
        assert_eq!(
            query_declared(
                &mut fixture,
                shape,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(shape_type)
        );
        assert_eq!(store_state(&fixture.store), warm_state);
    }

    #[test]
    fn type_literal_index_signature_publishes_exact_record_cold_and_warm() {
        let mut fixture = fixture(concat!(
            "type Value = { nested: boolean }; ",
            "type Table = { readonly [key: string]: Value };",
        ));
        let value = canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Value");
        let table = canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Table");
        let (_, _, literal) = alias_parts(&fixture, "Table");
        let plan = {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            object_members::plan_type_literal(&fixture.store, &host, literal, Some(table)).unwrap()
        };
        let [planned] = plan.indexes.as_slice() else {
            panic!("the exact type literal has one planned index")
        };
        assert!(plan.properties.is_empty());
        assert!(planned.readonly);
        assert_eq!(
            fixture.store.source_node_kind(planned.key_type_node),
            Some(SyntaxKind::StringKeyword)
        );
        assert_eq!(
            fixture.store.source_node_kind(planned.value_type_node),
            Some(SyntaxKind::TypeReference)
        );
        let before_indexes = fixture.store.index_info_len();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let table_type = query_declared(
            &mut fixture,
            table,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        assert!(diagnostics.is_empty());
        assert_eq!(fixture.store.index_info_len(), before_indexes + 1);
        assert_eq!(
            object_members::type_literal_state(&fixture.store, &plan),
            Ok(Some(PropertyObjectState::Resolved(table_type)))
        );
        let TypeData::Object(object) = fixture.store.type_payload(table_type).unwrap().data()
        else {
            panic!("type literal indexes retain anonymous object identity")
        };
        assert_eq!(object.structured.properties, None);
        assert_eq!(object.structured.signatures, None);
        let [index] = object.structured.index_infos.as_deref().unwrap() else {
            panic!("one index info is attached")
        };
        let info = fixture.store.index_info(*index).unwrap();
        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        let value_type = fixture
            .store
            .type_alias_links(value)
            .and_then(|links| links.declared_type)
            .expect("the index annotation dependency resolves first");
        assert_eq!(info.key_type(), bootstrap.string_type);
        assert_eq!(info.value_type(), value_type);
        assert_eq!(
            fixture
                .store
                .type_node_links(planned.value_type_node)
                .and_then(|links| links.resolved_type),
            Some(value_type)
        );
        assert!(info.is_readonly());
        assert_eq!(info.declaration(), Some(planned.declaration));
        assert_eq!(info.index_symbol(), None);
        assert!(info.components().is_empty());
        let members = object.structured.members.unwrap();
        let member_table = fixture.store.symbol_table(members).unwrap();
        assert_eq!(member_table.len(), 1);
        assert_eq!(
            member_table.get(InternalSymbolName::Index.as_ref()),
            Some(planned.symbol)
        );
        let bound_index = fixture.store.symbol(planned.symbol).unwrap();
        assert_eq!(bound_index.flags(), SymbolFlags::SIGNATURE);
        assert_eq!(bound_index.check_flags(), CheckFlags::NONE);
        assert_eq!(bound_index.declarations(), Some(&[planned.declaration][..]));
        assert_eq!(bound_index.value_declaration(), None);
        assert_eq!(bound_index.parent(), Some(plan.symbol));

        let warm_state = (store_state(&fixture.store), fixture.store.index_info_len());
        assert_eq!(
            query_declared(
                &mut fixture,
                table,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(table_type)
        );
        assert_eq!(
            (store_state(&fixture.store), fixture.store.index_info_len()),
            warm_state
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Keep signature, rest, return, and warm identity together.
    fn type_literal_call_signatures_preserve_implicit_any_rest_and_return_identity() {
        for (source, implicit_return) in [
            (
                "type Callback = { (value: number, ...rest): string };",
                false,
            ),
            ("type Callback = { (value: number, ...rest) };", true),
        ] {
            let mut fixture = fixture(source);
            let alias =
                canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Callback");
            let literal = alias_parts(&fixture, "Callback").2;
            let plan = {
                let host = post_global_host(
                    &fixture.parsed.arena,
                    fixture.files.get(&fixture.file).unwrap(),
                );
                object_members::plan_type_literal(&fixture.store, &host, literal, Some(alias))
                    .unwrap_or_else(|error| panic!("{source}: {error:?}"))
            };
            let [planned] = plan.call_signatures.as_slice() else {
                panic!("the type literal must retain exactly one binder-owned call signature")
            };
            assert_eq!(planned.implicit_any_return, implicit_return);
            let [value, rest] = planned.parameters.as_slice() else {
                panic!("the call signature must retain its value and rest parameters")
            };
            assert!(!value.implicit_any_rest);
            assert!(rest.implicit_any_rest);
            let declaration = planned.declaration;
            let parameter_symbols = [value.symbol, rest.symbol];
            let mut diagnostics = CanonicalCheckerDiagnostics::default();

            let callable = query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap_or_else(|error| panic!("{source}: {error:?}"));

            let TypeData::Object(object) = fixture.store.type_payload(callable).unwrap().data()
            else {
                panic!("type-literal call signatures must retain their anonymous object")
            };
            assert_eq!(object.structured.call_signature_count, 1);
            let [signature] = object.structured.signatures.as_deref().unwrap() else {
                panic!("the type literal must publish exactly one canonical signature")
            };
            let signature = *signature;
            let record = fixture.store.signature(signature).unwrap();
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            let rest_type = source_callables::implicit_any_array_type(&fixture.store).unwrap();
            let return_type = if implicit_return {
                bootstrap.any_type
            } else {
                bootstrap.string_type
            };
            assert_eq!(record.declaration(), Some(declaration));
            assert_eq!(record.flags(), SignatureFlags::HAS_REST_PARAMETER);
            assert_eq!(record.parameters(), parameter_symbols.as_slice());
            assert_eq!(record.min_argument_count(), 1);
            assert_eq!(record.resolved_return_type(), Some(return_type));
            assert_eq!(
                fixture.store.callable_signature_parameter_types(signature),
                Some([bootstrap.number_type, rest_type].as_slice()),
            );
            assert_eq!(
                fixture
                    .store
                    .value_symbol_links(parameter_symbols[1])
                    .and_then(|links| links.resolved_type),
                Some(rest_type),
            );
            assert_eq!(
                fixture
                    .store
                    .function_signature_return_annotation(signature)
                    .is_none(),
                implicit_return,
            );
            let StoredCallableSetValidation::Valid { projection, .. } =
                validate_stored_callable_set(&fixture.store, callable)
            else {
                panic!("the published call signature must remain fully authenticated")
            };
            let [projected] = projection.call_signatures.as_ref() else {
                panic!("the callable projection must expose exactly one call signature")
            };
            assert_eq!(projected.signature, signature);
            assert_eq!(projected.parameters, [bootstrap.number_type]);
            assert_eq!(projected.rest_parameter, Some(rest_type));
            assert_eq!(projected.return_type, Some(return_type));
            assert_eq!(
                query_signature_return(&mut fixture, signature, &mut diagnostics),
                Ok(return_type),
            );

            let warm = function_store_state(&fixture.store);
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(callable),
            );
            assert_eq!(
                query_signature_return(&mut fixture, signature, &mut diagnostics),
                Ok(return_type),
            );
            assert_eq!(function_store_state(&fixture.store), warm);
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn mixed_type_literal_signatures_preserve_implicit_call_rest_and_constructor_identity() {
        let mut fixture = fixture(concat!(
            "type Callback = { ",
            "new(value: string): number; ",
            "(value: number, ...rest) ",
            "};",
        ));
        let alias =
            canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Callback");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let callable = query_declared(
            &mut fixture,
            alias,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let TypeData::Object(object) = fixture.store.type_payload(callable).unwrap().data() else {
            panic!("mixed signatures must retain their anonymous object")
        };
        assert_eq!(object.structured.call_signature_count, 1);
        let [call, construct] = object.structured.signatures.as_deref().unwrap() else {
            panic!("mixed signatures must publish the call before the constructor")
        };
        let (call, construct) = (*call, *construct);
        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        let (any, number, string) = (
            bootstrap.any_type,
            bootstrap.number_type,
            bootstrap.string_type,
        );
        let rest = source_callables::implicit_any_array_type(&fixture.store).unwrap();
        let call_record = fixture.store.signature(call).unwrap();
        assert_eq!(call_record.flags(), SignatureFlags::HAS_REST_PARAMETER);
        assert_eq!(call_record.min_argument_count(), 1);
        assert_eq!(call_record.resolved_return_type(), Some(any));
        assert_eq!(
            fixture.store.callable_signature_parameter_types(call),
            Some([number, rest].as_slice()),
        );
        assert!(
            fixture
                .store
                .function_signature_return_annotation(call)
                .is_none()
        );
        let construct_record = fixture.store.signature(construct).unwrap();
        assert_eq!(construct_record.flags(), SignatureFlags::CONSTRUCT);
        assert_eq!(construct_record.resolved_return_type(), Some(number));
        assert_eq!(
            fixture.store.callable_signature_parameter_types(construct),
            Some([string].as_slice()),
        );
        let StoredCallableSetValidation::Valid { projection, .. } =
            validate_stored_callable_set(&fixture.store, callable)
        else {
            panic!("mixed implicit signatures must retain both authenticated families")
        };
        let [projected] = projection.call_signatures.as_ref() else {
            panic!("the mixed object must expose one call signature")
        };
        assert_eq!(projected.signature, call);
        assert_eq!(projected.rest_parameter, Some(rest));
        assert_eq!(projection.construct_signatures.as_ref(), &[construct]);
        assert_eq!(
            query_signature_return(&mut fixture, call, &mut diagnostics),
            Ok(any)
        );

        let warm = function_store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(callable),
        );
        assert_eq!(
            query_signature_return(&mut fixture, call, &mut diagnostics),
            Ok(any)
        );
        assert_eq!(function_store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Keep overload, property, dependency, and warm identity together.
    fn type_literal_call_overloads_and_properties_preserve_exact_binder_identity() {
        let mut fixture = fixture(concat!(
            "type Callable = { ",
            "(value: 'specific'): number; ",
            "readonly label?: boolean; ",
            "(value: string, ...rest); ",
            "value: string; ",
            "readonly stable: number; ",
            "};",
        ));
        let alias =
            canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Callable");
        let literal = alias_parts(&fixture, "Callable").2;
        let plan = {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            object_members::plan_type_literal(&fixture.store, &host, literal, Some(alias)).unwrap()
        };
        let [specialized_plan, general_plan] = plan.call_signatures.as_slice() else {
            panic!("interleaved declarations must retain both call overloads")
        };
        assert!(!specialized_plan.implicit_any_return);
        assert!(general_plan.implicit_any_return);
        assert!(general_plan.parameters[1].implicit_any_rest);
        assert_eq!(
            plan.properties
                .iter()
                .map(|property| property.name.as_str())
                .collect::<Vec<_>>(),
            ["label", "value", "stable"],
        );
        assert_eq!(
            plan.properties
                .iter()
                .map(|property| (property.optional, property.readonly))
                .collect::<Vec<_>>(),
            [(true, true), (false, false), (false, true)],
        );

        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let callable = query_declared(
            &mut fixture,
            alias,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let TypeData::Object(object) = fixture.store.type_payload(callable).unwrap().data() else {
            panic!("mixed callable declarations must retain their anonymous type literal")
        };
        let [specialized, general] = object.structured.signatures.as_deref().unwrap() else {
            panic!("both call overloads must publish in declaration order")
        };
        let specialized = *specialized;
        let general = *general;
        assert_eq!(object.structured.call_signature_count, 2);
        assert_eq!(
            object.structured.properties.as_deref(),
            Some(
                plan.properties
                    .iter()
                    .map(|property| property.symbol)
                    .collect::<Vec<_>>()
                    .as_slice(),
            ),
        );
        let members = object.structured.members.unwrap();
        let table = fixture.store.symbol_table(members).unwrap();
        assert_eq!(table.len(), plan.properties.len() + 1);
        assert_eq!(
            table.get(InternalSymbolName::Call.as_ref()),
            Some(specialized_plan.symbol),
        );
        assert_eq!(
            fixture
                .store
                .symbol(specialized_plan.symbol)
                .unwrap()
                .declarations(),
            Some(
                plan.call_signatures
                    .iter()
                    .map(|signature| signature.declaration)
                    .collect::<Vec<_>>()
                    .as_slice(),
            ),
        );

        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        let (any, boolean, number, string) = (
            bootstrap.any_type,
            bootstrap.boolean_type,
            bootstrap.number_type,
            bootstrap.string_type,
        );
        for (property, expected_type) in plan.properties.iter().zip([boolean, string, number]) {
            let record = fixture.store.symbol(property.symbol).unwrap();
            let expected_flags = SymbolFlags::PROPERTY
                | if property.optional {
                    SymbolFlags::OPTIONAL
                } else {
                    SymbolFlags::NONE
                };
            let expected_checks = if property.readonly {
                CheckFlags::READONLY
            } else {
                CheckFlags::NONE
            };
            assert_eq!(record.flags(), expected_flags);
            assert_eq!(record.check_flags(), expected_checks);
            assert_eq!(record.value_declaration(), Some(property.declaration));
            assert_eq!(record.parent(), Some(plan.symbol));
            assert_eq!(table.get_source(&property.name), Some(property.symbol));
            assert_eq!(
                fixture
                    .files
                    .get(&fixture.file)
                    .unwrap()
                    .symbol(property.declaration),
                Some(property.symbol),
            );
            assert_eq!(
                fixture.store.value_symbol_links(property.symbol),
                Some(&ValueSymbolLinks {
                    resolved_type: Some(expected_type),
                    ..ValueSymbolLinks::default()
                }),
            );
        }

        let literal_parameter = fixture
            .store
            .callable_signature_parameter_types(specialized)
            .unwrap()[0];
        let rest = source_callables::implicit_any_array_type(&fixture.store).unwrap();
        let specialized_record = fixture.store.signature(specialized).unwrap();
        assert_eq!(
            specialized_record.flags(),
            SignatureFlags::HAS_LITERAL_TYPES
        );
        assert_eq!(
            specialized_record.declaration(),
            Some(specialized_plan.declaration),
        );
        assert_eq!(specialized_record.resolved_return_type(), Some(number));
        let general_record = fixture.store.signature(general).unwrap();
        assert_eq!(general_record.flags(), SignatureFlags::HAS_REST_PARAMETER);
        assert_eq!(general_record.declaration(), Some(general_plan.declaration));
        assert_eq!(general_record.resolved_return_type(), Some(any));
        assert_eq!(
            fixture.store.callable_signature_parameter_types(general),
            Some([string, rest].as_slice()),
        );

        let StoredCallableSetValidation::Valid {
            projection, edges, ..
        } = validate_stored_callable_set(&fixture.store, callable)
        else {
            panic!("call overloads and properties must retain one authenticated provider")
        };
        let [specialized_projection, general_projection] = projection.call_signatures.as_ref()
        else {
            panic!("the callable projection must preserve both declaration-ordered overloads")
        };
        assert_eq!(specialized_projection.signature, specialized);
        assert_eq!(specialized_projection.parameters, [literal_parameter]);
        assert_eq!(specialized_projection.return_type, Some(number));
        assert_eq!(general_projection.signature, general);
        assert_eq!(general_projection.parameters, [string]);
        assert_eq!(general_projection.rest_parameter, Some(rest));
        assert_eq!(general_projection.return_type, Some(any));
        assert_eq!(
            edges,
            vec![
                literal_parameter,
                number,
                string,
                rest,
                any,
                boolean,
                string,
                number
            ],
        );
        assert_eq!(
            query_signature_return(&mut fixture, specialized, &mut diagnostics),
            Ok(number),
        );
        assert_eq!(
            query_signature_return(&mut fixture, general, &mut diagnostics),
            Ok(any),
        );

        let warm = function_store_state(&fixture.store);
        assert_eq!(
            query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            ),
            Ok(callable),
        );
        assert_eq!(
            query_signature_return(&mut fixture, specialized, &mut diagnostics),
            Ok(number),
        );
        assert_eq!(
            query_signature_return(&mut fixture, general, &mut diagnostics),
            Ok(any),
        );
        assert_eq!(function_store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Keep optional arity, overload selection, and warm identity together.
    fn optional_type_literal_call_overloads_preserve_literal_specialization_and_properties() {
        use crate::semantic::calls::{
            DirectCallApplicability, DirectCallForm, DirectCallRequest, resolve_direct_call,
        };

        let mut fixture = global_array_fixture(concat!(
            "type Callable = { ",
            "(value?: any): boolean; ",
            "readonly label?: string; ",
            "(value: 'specific'): number; ",
            "enabled: boolean; ",
            "};",
        ));
        let global_types = initialize_fixture_global_types(&mut fixture);
        let alias =
            canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Callable");
        let literal = alias_parts(&fixture, "Callable").2;
        let plan = {
            let host = post_global_host(
                &fixture.parsed.arena,
                fixture.files.get(&fixture.file).unwrap(),
            );
            object_members::plan_type_literal(&fixture.store, &host, literal, Some(alias)).unwrap()
        };
        let [general_plan, specialized_plan] = plan.call_signatures.as_slice() else {
            panic!("the callable type literal must retain both source-ordered overloads")
        };
        assert_eq!(general_plan.min_argument_count(), 0);
        assert_eq!(specialized_plan.min_argument_count(), 1);
        assert_eq!(
            plan.properties
                .iter()
                .map(|property| (property.name.as_str(), property.optional, property.readonly))
                .collect::<Vec<_>>(),
            [("label", true, true), ("enabled", false, false)],
        );

        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let callable =
            query_global_declared(&mut fixture, &global_types, alias, &mut diagnostics).unwrap();
        let TypeData::Object(object) = fixture.store.type_payload(callable).unwrap().data() else {
            panic!("optional call overloads must retain their anonymous type literal")
        };
        let [general, specialized] = object.structured.signatures.as_deref().unwrap() else {
            panic!("published call overloads must remain in declaration order")
        };
        let general = *general;
        let specialized = *specialized;
        assert_eq!(object.structured.call_signature_count, 2);
        assert_eq!(
            object.structured.properties.as_deref(),
            Some(
                plan.properties
                    .iter()
                    .map(|property| property.symbol)
                    .collect::<Vec<_>>()
                    .as_slice(),
            ),
        );
        let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
        let (any, boolean, number, string) = (
            bootstrap.any_type,
            bootstrap.boolean_type,
            bootstrap.number_type,
            bootstrap.string_type,
        );
        let specific = fixture
            .store
            .callable_signature_parameter_types(specialized)
            .unwrap()[0];
        let general_record = fixture.store.signature(general).unwrap();
        assert_eq!(general_record.declaration(), Some(general_plan.declaration));
        assert_eq!(general_record.min_argument_count(), 0);
        assert_eq!(general_record.resolved_return_type(), Some(boolean));
        assert_eq!(
            fixture.store.callable_signature_parameter_types(general),
            Some([any].as_slice()),
        );
        let specialized_record = fixture.store.signature(specialized).unwrap();
        assert_eq!(
            specialized_record.declaration(),
            Some(specialized_plan.declaration),
        );
        assert_eq!(
            specialized_record.flags(),
            SignatureFlags::HAS_LITERAL_TYPES
        );
        assert_eq!(specialized_record.min_argument_count(), 1);
        assert_eq!(specialized_record.resolved_return_type(), Some(number));
        for (property, expected_type) in plan.properties.iter().zip([string, boolean]) {
            assert_eq!(
                fixture.store.value_symbol_links(property.symbol),
                Some(&ValueSymbolLinks {
                    resolved_type: Some(expected_type),
                    ..ValueSymbolLinks::default()
                }),
            );
        }
        assert_eq!(
            fixture
                .store
                .symbol(plan.properties[0].symbol)
                .unwrap()
                .flags(),
            SymbolFlags::PROPERTY | SymbolFlags::OPTIONAL,
        );
        assert_eq!(
            fixture
                .store
                .symbol(plan.properties[0].symbol)
                .unwrap()
                .check_flags(),
            CheckFlags::READONLY,
        );

        let StoredCallableSetValidation::Valid {
            projection, edges, ..
        } = validate_stored_callable_set(&fixture.store, callable)
        else {
            panic!("optional call overloads must retain authenticated callable provenance")
        };
        let [general_projection, specialized_projection] = projection.call_signatures.as_ref()
        else {
            panic!("callable projection must preserve both original overload identities")
        };
        assert_eq!(general_projection.signature, general);
        assert_eq!(general_projection.min_argument_count, 0);
        assert_eq!(general_projection.parameters, [any]);
        assert_eq!(specialized_projection.signature, specialized);
        assert_eq!(specialized_projection.min_argument_count, 1);
        assert_eq!(specialized_projection.parameters, [specific]);
        assert_eq!(edges, vec![any, boolean, specific, number, string, boolean]);

        let no_arguments = [];
        let specific_arguments = [specific];
        let general_arguments = [string];
        let calls = [
            (no_arguments.as_slice(), general, boolean),
            (specific_arguments.as_slice(), specialized, number),
            (general_arguments.as_slice(), general, boolean),
        ];
        for (arguments, expected_signature, expected_return) in calls {
            let resolution = resolve_direct_call(
                &mut fixture.store,
                &global_types,
                false,
                DirectCallRequest {
                    form: DirectCallForm::Call,
                    optional_chain: false,
                    type_argument_count: 0,
                    has_spread_argument: false,
                    callee: callable,
                    arguments,
                },
            )
            .unwrap();
            assert_eq!(resolution.projection.signature, expected_signature);
            assert_eq!(resolution.projection.return_type, expected_return);
            assert_eq!(
                resolution.applicability,
                DirectCallApplicability::Applicable
            );
        }

        let warm = function_store_state(&fixture.store);
        for (arguments, expected_signature, expected_return) in calls {
            let resolution = resolve_direct_call(
                &mut fixture.store,
                &global_types,
                false,
                DirectCallRequest {
                    form: DirectCallForm::Call,
                    optional_chain: false,
                    type_argument_count: 0,
                    has_spread_argument: false,
                    callee: callable,
                    arguments,
                },
            )
            .unwrap();
            assert_eq!(resolution.projection.signature, expected_signature);
            assert_eq!(resolution.projection.return_type, expected_return);
        }
        assert_eq!(
            query_global_declared(&mut fixture, &global_types, alias, &mut diagnostics),
            Ok(callable),
        );
        assert_eq!(function_store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn optional_type_literal_call_parameters_keep_any_identity_and_reject_forged_links() {
        for strict_null_checks in [false, true] {
            let mut fixture = fixture_with_intrinsic(
                concat!(
                    "type Callable = { ",
                    "(required: string, first?: any, second?: any); ",
                    "readonly ready?: boolean; ",
                    "};",
                ),
                IntrinsicBootstrapOptions {
                    strict_null_checks,
                    ..IntrinsicBootstrapOptions::default()
                },
            );
            let alias =
                canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Callable");
            let literal = alias_parts(&fixture, "Callable").2;
            let plan = {
                let host = post_global_host(
                    &fixture.parsed.arena,
                    fixture.files.get(&fixture.file).unwrap(),
                );
                object_members::plan_type_literal(&fixture.store, &host, literal, Some(alias))
                    .unwrap()
            };
            let [planned] = plan.call_signatures.as_slice() else {
                panic!("the callable type literal must retain one optional-parameter signature")
            };
            assert_eq!(planned.min_argument_count(), 1);
            assert!(planned.implicit_any_return);

            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let callable = query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let TypeData::Object(object) = fixture.store.type_payload(callable).unwrap().data()
            else {
                panic!("optional parameters must retain their source-owned type literal")
            };
            let [signature] = object.structured.signatures.as_deref().unwrap() else {
                panic!("the optional parameter list must publish one exact signature")
            };
            let signature = *signature;
            let record = fixture.store.signature(signature).unwrap();
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            let (any, boolean, string) = (
                bootstrap.any_type,
                bootstrap.boolean_type,
                bootstrap.string_type,
            );
            assert_eq!(record.min_argument_count(), 1);
            assert_eq!(record.resolved_return_type(), Some(any));
            assert_eq!(
                fixture.store.callable_signature_parameter_types(signature),
                Some([string, any, any].as_slice()),
            );
            assert_eq!(
                object_members::validate_stored_declared_call_set(&fixture.store, callable),
                object_members::StoredDeclaredCallSetValidation::Valid(vec![
                    string, any, any, any, boolean,
                ]),
            );
            let optional = planned.parameters[2].symbol;
            let original = fixture.store.value_symbol_links(optional).unwrap().clone();

            let warm = function_store_state(&fixture.store);
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(callable),
            );
            assert_eq!(function_store_state(&fixture.store), warm);

            assert!(fixture.store.set_value_symbol_links(
                optional,
                ValueSymbolLinks {
                    resolved_type: Some(string),
                    ..ValueSymbolLinks::default()
                },
            ));
            assert!(matches!(
                validate_stored_callable_set(&fixture.store, callable),
                StoredCallableSetValidation::Malformed { .. }
            ));
            let poisoned = function_store_state(&fixture.store);
            assert!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .is_err(),
            );
            assert_eq!(function_store_state(&fixture.store), poisoned);
            assert!(fixture.store.set_value_symbol_links(optional, original));
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(callable),
            );
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn optional_type_literal_call_parameters_keep_unsupported_shapes_atomic() {
        for (source, owner_kind) in [
            (
                "type Invalid = { (value?: string): boolean };",
                SyntaxKind::TypeAliasDeclaration,
            ),
            (
                "type Invalid = { (value?: any, ...rest): boolean };",
                SyntaxKind::TypeAliasDeclaration,
            ),
            (
                "type Invalid = { <T>(value?: T): boolean };",
                SyntaxKind::TypeAliasDeclaration,
            ),
            (
                "interface Invalid { (value?: any): boolean; }",
                SyntaxKind::InterfaceDeclaration,
            ),
        ] {
            let mut fixture = fixture(source);
            let owner = canonical_fixture_symbol(&fixture, owner_kind, "Invalid");
            let before = function_store_state(&fixture.store);
            let mut diagnostics = CanonicalCheckerDiagnostics::default();

            assert!(
                matches!(
                    query_declared(
                        &mut fixture,
                        owner,
                        CanonicalTypeQueryOptions::default(),
                        &mut diagnostics,
                    ),
                    Err(DeclaredTypeError::TypeNodeUnavailable(
                        TypeNodeUnavailable::UnsupportedSyntax {
                            kind: SyntaxKind::CallSignature,
                            ..
                        }
                    ))
                ),
                "source: {source}",
            );
            assert_eq!(function_store_state(&fixture.store), before);
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn callable_type_literal_properties_reject_forged_identity_and_links_atomically() {
        for corruption in 0..3 {
            let mut fixture = fixture(concat!(
                "type Callable = { ",
                "(value: string): number; label: boolean; other: string; ",
                "};",
            ));
            let alias =
                canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Callable");
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let callable = query_declared(
                &mut fixture,
                alias,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let owner = fixture
                .store
                .type_payload(callable)
                .unwrap()
                .symbol()
                .unwrap();
            let members = fixture.store.symbol(owner).unwrap().members().unwrap();
            let table = fixture.store.symbol_table(members).unwrap();
            let property = table.get_source("label").unwrap();
            let other = table.get_source("other").unwrap();
            let original_links = fixture.store.value_symbol_links(property).unwrap().clone();
            let forged_type = fixture.store.intrinsic_bootstrap().unwrap().number_type;

            match corruption {
                0 => assert!(
                    fixture
                        .store
                        .set_symbol_relationships(property, None, None, None, None)
                ),
                1 => assert_eq!(
                    fixture
                        .store
                        .insert_symbol(members, EscapedName::source("label"), other),
                    Some(Some(property)),
                ),
                2 => assert!(fixture.store.set_value_symbol_links(
                    property,
                    ValueSymbolLinks {
                        resolved_type: Some(forged_type),
                        ..ValueSymbolLinks::default()
                    },
                )),
                _ => unreachable!(),
            }
            assert_eq!(
                object_members::validate_stored_declared_call_set(&fixture.store, callable),
                object_members::StoredDeclaredCallSetValidation::Malformed,
            );
            assert!(matches!(
                validate_stored_callable_set(&fixture.store, callable),
                StoredCallableSetValidation::Malformed { .. }
            ));
            let poisoned = function_store_state(&fixture.store);
            assert!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                )
                .is_err(),
                "corruption case {corruption}",
            );
            assert_eq!(function_store_state(&fixture.store), poisoned);

            match corruption {
                0 => assert!(fixture.store.set_symbol_relationships(
                    property,
                    None,
                    None,
                    Some(owner),
                    None,
                )),
                1 => assert_eq!(
                    fixture
                        .store
                        .insert_symbol(members, EscapedName::source("label"), property,),
                    Some(Some(other)),
                ),
                2 => assert!(
                    fixture
                        .store
                        .set_value_symbol_links(property, original_links)
                ),
                _ => unreachable!(),
            }
            assert_eq!(
                query_declared(
                    &mut fixture,
                    alias,
                    CanonicalTypeQueryOptions::default(),
                    &mut diagnostics,
                ),
                Ok(callable),
            );
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
