    #[test]
    fn warm_indexed_methods_reject_forged_parameter_signature_owner_and_return_caches() {
        for corruption in 0..5 {
            let mut fixture = fixture(concat!(
                "type Bad = ",
                "{ bivarianceHack(value: string): void }['bivarianceHack'];",
            ));
            let bad = canonical_fixture_symbol(&fixture, SyntaxKind::TypeAliasDeclaration, "Bad");
            let (_, object, _) = indexed_access_parts(&fixture, "Bad");
            let object_plan = {
                let host = post_global_host(
                    &fixture.parsed.arena,
                    fixture.files.get(&fixture.file).unwrap(),
                );
                object_members::plan_concrete_indexed_access_type_literal(
                    &fixture.store,
                    &host,
                    object,
                )
                .unwrap()
            };
            let method = &object_plan.methods[0];
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let callable = query_declared(
                &mut fixture,
                bad,
                CanonicalTypeQueryOptions::default(),
                &mut diagnostics,
            )
            .unwrap();
            let signature = fixture
                .store
                .signature_links(method.declaration)
                .and_then(|links| links.resolved_signature.signature())
                .unwrap();
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            let number = bootstrap.number_type;
            let void = bootstrap.void_type;
            assert_eq!(
                query_signature_return(&mut fixture, signature, &mut diagnostics),
                Ok(void),
            );
            match corruption {
                0 => assert!(fixture.store.set_value_symbol_links(
                    method.parameters[0].symbol,
                    ValueSymbolLinks {
                        resolved_type: Some(number),
                        ..ValueSymbolLinks::default()
                    },
                )),
                1 => assert!(
                    fixture
                        .store
                        .set_signature_links(method.declaration, SignatureLinks::default())
                ),
                2 => assert!(fixture.store.set_value_symbol_links(
                    method.symbol,
                    ValueSymbolLinks {
                        resolved_type: Some(number),
                        ..ValueSymbolLinks::default()
                    },
                )),
                3 => assert!(
                    fixture
                        .store
                        .set_signature_resolved_return_type(signature, Some(number))
                ),
                4 => assert!(fixture.store.set_type_node_links(
                    method.return_type,
                    TypeNodeLinks {
                        resolved_type: Some(number),
                        ..TypeNodeLinks::default()
                    },
                )),
                _ => unreachable!("corruption cases are bounded"),
            }
            assert!(matches!(
                validate_stored_callable_set(&fixture.store, callable),
                StoredCallableSetValidation::Malformed { .. }
            ));
            let before = (store_state(&fixture.store), fixture.store.signature_len());
            for _ in 0..2 {
                assert!(matches!(
                    query_signature_return(&mut fixture, signature, &mut diagnostics),
                    Err(DeclaredTypeError::TypeNodeUnavailable(
                        TypeNodeUnavailable::InvalidFunctionSignature(cached),
                    )) if cached == signature
                ));
                assert_eq!(
                    (store_state(&fixture.store), fixture.store.signature_len()),
                    before,
                );
                assert!(
                    query_declared(
                        &mut fixture,
                        bad,
                        CanonicalTypeQueryOptions::default(),
                        &mut diagnostics,
                    )
                    .is_err(),
                    "corruption case {corruption}",
                );
                assert_eq!(
                    (store_state(&fixture.store), fixture.store.signature_len()),
                    before,
                );
            }
        }
    }

