    #[test]
    fn declared_owner_relationship_and_back_edge_poisons_are_repairable() {
        let mut fixture = global_array_fixture("interface Item { value: number; }");
        let global_types = initialize_fixture_global_types(&mut fixture);
        let item_symbol = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Item");
        let array_symbol = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Array");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let item =
            query_global_declared(&mut fixture, &global_types, item_symbol, &mut diagnostics)
                .unwrap();
        assert_eq!(
            object_members::validate_resolved_declared_property_object(&fixture.store, item),
            object_members::DeclaredPropertyObjectValidation::Valid(
                object_members::DeclaredPropertyObjectProof::Interface,
            ),
        );

        let (members, exports, parent, export_symbol) = {
            let owner = fixture.store.symbol(item_symbol).unwrap();
            (
                owner.members(),
                owner.exports(),
                owner.parent(),
                owner.export_symbol(),
            )
        };
        assert!(fixture.store.set_symbol_relationships(
            item_symbol,
            members,
            exports,
            Some(array_symbol),
            export_symbol,
        ));
        assert_eq!(
            object_members::validate_resolved_declared_property_object(&fixture.store, item),
            object_members::DeclaredPropertyObjectValidation::Malformed,
            "a top-level declaration cannot acquire a nested owner relationship",
        );
        assert!(fixture.store.set_symbol_relationships(
            item_symbol,
            members,
            exports,
            parent,
            export_symbol,
        ));
        assert_eq!(
            object_members::validate_resolved_declared_property_object(&fixture.store, item),
            object_members::DeclaredPropertyObjectValidation::Valid(
                object_members::DeclaredPropertyObjectProof::Interface,
            ),
        );

        let original_links = fixture
            .store
            .declared_type_links(item_symbol)
            .cloned()
            .unwrap();
        let number = fixture.store.intrinsic_bootstrap().unwrap().number_type;
        let mut poisoned_links = original_links.clone();
        poisoned_links.declared_type = Some(number);
        assert!(
            fixture
                .store
                .set_declared_type_links(item_symbol, poisoned_links)
        );
        assert_eq!(
            object_members::validate_resolved_declared_property_object(&fixture.store, item),
            object_members::DeclaredPropertyObjectValidation::Malformed,
            "a contradictory declared-type back edge is cache corruption",
        );
        assert!(
            fixture
                .store
                .set_declared_type_links(item_symbol, original_links)
        );
        assert_eq!(
            object_members::validate_resolved_declared_property_object(&fixture.store, item),
            object_members::DeclaredPropertyObjectValidation::Valid(
                object_members::DeclaredPropertyObjectProof::Interface,
            ),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn bound_merged_property_declarations_share_one_declared_object() {
        let mut fixture = global_array_fixture(concat!(
            "interface Item { values: Array<number>; } ",
            "interface Item { values: Array<number>; }",
        ));
        let global_types = initialize_fixture_global_types(&mut fixture);
        let item_symbol = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Item");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let members = fixture
            .store
            .symbol(item_symbol)
            .unwrap()
            .members()
            .unwrap();
        let item_property = fixture
            .store
            .symbol_table(members)
            .unwrap()
            .get_source("values")
            .unwrap();
        let declarations = fixture
            .store
            .symbol(item_property)
            .unwrap()
            .declarations()
            .unwrap()
            .to_vec();
        assert_eq!(declarations.len(), 2);
        assert_ne!(declarations[0], declarations[1]);
        assert!(declarations.iter().all(|declaration| {
            fixture.store.source_node_kind(*declaration) == Some(SyntaxKind::PropertyDeclaration)
        }));
        let cold = store_state(&fixture.store);

        let item =
            query_global_declared(&mut fixture, &global_types, item_symbol, &mut diagnostics)
                .unwrap();
        assert_ne!(store_state(&fixture.store), cold);
        assert_eq!(
            object_members::validate_resolved_declared_property_object(&fixture.store, item),
            object_members::DeclaredPropertyObjectValidation::Valid(
                object_members::DeclaredPropertyObjectProof::Interface,
            ),
        );
        assert!(matches!(
            object_members::validate_resolved_declared_property_type_graph(&fixture.store, item),
            object_members::DeclaredPropertyTypeGraphValidation::Traversable(properties)
                if properties.len() == 1
        ));
        let warm = store_state(&fixture.store);
        assert_eq!(
            query_global_declared(&mut fixture, &global_types, item_symbol, &mut diagnostics),
            Ok(item),
        );
        assert_eq!(store_state(&fixture.store), warm);

        assert!(fixture.store.set_symbol_declarations(
            item_property,
            Some(vec![declarations[0], declarations[0]]),
            Some(declarations[0]),
        ));
        assert_eq!(
            object_members::validate_resolved_declared_property_object(&fixture.store, item),
            object_members::DeclaredPropertyObjectValidation::Malformed,
            "repeated declaration identities remain cache corruption",
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn merged_interface_template_indexes_keep_their_exact_pattern_identity() {
        let mut fixture = fixture(concat!(
            "interface Attributes { key?: string; } ",
            "interface Attributes { ",
            "[name: `do-${string}`]: number; ",
            "\"ns:thing\"?: string; ",
            "}",
        ));
        let attributes = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Attributes");
        let pattern = fixture
            .parsed
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::TemplateLiteralType).then_some(NodeRef::new(
                    fixture.parsed.arena.id(),
                    fixture.file,
                    node,
                ))
            })
            .expect("the merged interface has one template-pattern index");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let resolved = query_declared(
            &mut fixture,
            attributes,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let pattern_type = fixture
            .store
            .type_node_links(pattern)
            .and_then(|links| links.resolved_type)
            .expect("template index keys retain their resolved identity");
        let TypeData::Interface(interface) = fixture.store.type_payload(resolved).unwrap().data()
        else {
            unreachable!()
        };
        let [index] = interface
            .reference
            .object
            .structured
            .index_infos
            .as_deref()
            .unwrap()
        else {
            panic!("the merged interface has exactly one index signature")
        };
        let index = fixture.store.index_info(*index).unwrap();
        assert_eq!(index.key_type(), pattern_type);
        assert_eq!(
            index.value_type(),
            fixture.store.intrinsic_bootstrap().unwrap().number_type,
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn direct_global_array_cache_poison_fails_atomically_and_retries() {
        let mut fixture = global_array_fixture("let literal: Array<'x'>; let warm: Array<number>;");
        let global_types = initialize_fixture_global_types(&mut fixture);
        let literal = variable_type_node(&fixture, "literal");
        let literal_argument = type_reference_argument_node(&fixture, literal, 0);
        let warm = variable_type_node(&fixture, "warm");
        let (any, number, string) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (
                bootstrap.any_type,
                bootstrap.number_type,
                bootstrap.string_type,
            )
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        assert!(fixture.store.set_type_reference_resolution(
            global_types.any_array_type,
            None,
            Some(vec![number]),
        ));
        let poisoned_target = store_state(&fixture.store);
        assert!(matches!(
            query_global_node(&mut fixture, &global_types, literal, &mut diagnostics),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidTypeReference(error_node)
            )) if error_node == literal
        ));
        assert_eq!(store_state(&fixture.store), poisoned_target);
        assert!(fixture.store.type_node_links(literal).is_none());
        assert!(fixture.store.type_node_links(literal_argument).is_none());
        assert!(fixture.store.set_type_reference_resolution(
            global_types.any_array_type,
            None,
            Some(vec![any]),
        ));

        let literal_type =
            query_global_node(&mut fixture, &global_types, literal, &mut diagnostics).unwrap();
        let literal_argument_type = fixture
            .store
            .type_node_links(literal_argument)
            .and_then(|links| links.resolved_type)
            .unwrap();
        let warm_type =
            query_global_node(&mut fixture, &global_types, warm, &mut diagnostics).unwrap();
        let readonly_number = fixture
            .store
            .create_canonical_array_type(&global_types, number, true)
            .unwrap();
        assert!(fixture.store.set_type_node_links(
            warm,
            TypeNodeLinks {
                resolved_type: Some(readonly_number),
                ..TypeNodeLinks::default()
            },
        ));
        let poisoned_node = store_state(&fixture.store);
        assert!(matches!(
            query_global_node(&mut fixture, &global_types, warm, &mut diagnostics),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidTypeReference(error_node)
            )) if error_node == warm
        ));
        assert_eq!(store_state(&fixture.store), poisoned_node);
        assert!(fixture.store.set_type_node_links(
            warm,
            TypeNodeLinks {
                resolved_type: Some(warm_type),
                ..TypeNodeLinks::default()
            },
        ));
        let array_symbol = fixture
            .store
            .type_payload(global_types.array_type)
            .unwrap()
            .symbol()
            .unwrap();
        let readonly_symbol = fixture
            .store
            .type_payload(global_types.readonly_array_type)
            .unwrap()
            .symbol()
            .unwrap();
        assert!(fixture.store.set_symbol_node_links(
            warm,
            SymbolNodeLinks {
                resolved_symbol: Some(readonly_symbol),
            },
        ));
        let poisoned_symbol = store_state(&fixture.store);
        assert!(matches!(
            query_global_node(&mut fixture, &global_types, warm, &mut diagnostics),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidCachedSymbol {
                    node: error_node,
                    symbol,
                }
            )) if error_node == warm && symbol == readonly_symbol
        ));
        assert_eq!(store_state(&fixture.store), poisoned_symbol);
        assert!(fixture.store.set_symbol_node_links(
            warm,
            SymbolNodeLinks {
                resolved_symbol: Some(array_symbol),
            },
        ));

        assert!(fixture.store.set_type_node_links(
            literal_argument,
            TypeNodeLinks {
                resolved_type: Some(string),
                ..TypeNodeLinks::default()
            },
        ));
        let dirty_argument = store_state(&fixture.store);
        assert!(matches!(
            query_global_node(&mut fixture, &global_types, literal, &mut diagnostics),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidTypeReference(error_node)
            )) if error_node == literal
        ));
        assert_eq!(store_state(&fixture.store), dirty_argument);
        assert!(fixture.store.set_type_node_links(
            literal_argument,
            TypeNodeLinks {
                resolved_type: Some(literal_argument_type),
                ..TypeNodeLinks::default()
            },
        ));
        assert_eq!(
            query_global_node(&mut fixture, &global_types, literal, &mut diagnostics),
            Ok(literal_type)
        );
        assert_eq!(
            query_global_node(&mut fixture, &global_types, warm, &mut diagnostics),
            Ok(warm_type)
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn constructor_type_nodes_publish_authenticated_construct_signatures_cold_and_warm() {
        let mut fixture = fixture("declare const factory: new () => string;");
        let constructor = variable_type_node(&fixture, "factory");
        let owner = node_symbol(&fixture, constructor);
        let construct_symbol = fixture
            .store
            .symbol(owner)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|members| fixture.store.symbol_table(members))
            .and_then(|members| members.get(InternalSymbolName::New.as_ref()))
            .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let type_ = query_node(&mut fixture, constructor, &mut diagnostics).unwrap();
        let signature = function_signature(&fixture.store, constructor);
        let record = fixture.store.signature(signature).unwrap();
        let string = fixture.store.intrinsic_bootstrap().unwrap().string_type;
        assert_eq!(record.flags(), SignatureFlags::CONSTRUCT);
        assert_eq!(record.declaration(), Some(constructor));
        assert!(record.type_parameters().is_empty());
        assert!(record.parameters().is_empty());
        assert_eq!(record.min_argument_count(), 0);
        assert_eq!(record.resolved_return_type(), Some(string));
        assert_eq!(
            fixture.store.callable_signature_parameter_types(signature),
            Some(&[][..]),
        );
        assert_eq!(
            fixture
                .store
                .symbol(construct_symbol)
                .unwrap()
                .declarations(),
            Some(&[constructor][..]),
        );
        let TypeData::Object(object) = fixture.store.type_payload(type_).unwrap().data() else {
            panic!("a constructor type must retain its anonymous object")
        };
        assert_eq!(object.structured.call_signature_count, 0);
        assert_eq!(
            object.structured.signatures.as_deref(),
            Some(&[signature][..])
        );
        assert!(object.structured.properties.is_none());
        assert_eq!(
            object_members::validate_stored_declared_call_set(&fixture.store, type_),
            object_members::StoredDeclaredCallSetValidation::Valid(vec![string]),
        );
        let StoredCallableSetValidation::Valid { projection, .. } =
            validate_stored_callable_set(&fixture.store, type_)
        else {
            panic!("the constructor must expose an authenticated construct-only provider")
        };
        assert!(projection.call_signatures.is_empty());
        assert_eq!(projection.construct_signatures.as_ref(), &[signature]);
        let host = post_global_host(
            &fixture.parsed.arena,
            fixture.files.get(&fixture.file).unwrap(),
        );
        assert_eq!(
            type_to_string_with_host_and_flags(
                &fixture.store,
                &host,
                type_,
                CanonicalTypeFormatFlags::TYPE_TO_STRING_DEFAULT,
            ),
            Ok("new () => string".to_owned()),
        );

        let warm = function_store_state(&fixture.store);
        assert_eq!(
            query_node(&mut fixture, constructor, &mut diagnostics),
            Ok(type_)
        );
        assert_eq!(function_store_state(&fixture.store), warm);
        assert_eq!(
            query_signature_return(&mut fixture, signature, &mut diagnostics),
            Ok(string),
        );
        assert_eq!(function_store_state(&fixture.store), warm);
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn default_library_object_constructor_returns_preserve_mixed_signature_identity() {
        let mut fixture = default_library_fixture(concat!(
            "interface Object {} ",
            "interface ObjectConstructor { ",
            "new(value?: any): Object; ",
            "(): any; ",
            "(value: any): any; ",
            "readonly prototype: Object; ",
            "freeze<Value>(value: Value): Value; ",
            "} ",
            "declare var Object: ObjectConstructor;",
        ));
        let owner = named_symbol(
            &fixture,
            SyntaxKind::InterfaceDeclaration,
            "ObjectConstructor",
        );
        let object = named_symbol(&fixture, SyntaxKind::InterfaceDeclaration, "Object");
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let constructor = query_declared(
            &mut fixture,
            owner,
            CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap();
        let object_type = fixture
            .store
            .declared_type_links(object)
            .and_then(|links| links.declared_type)
            .unwrap();
        let TypeData::Interface(interface) =
            fixture.store.type_payload(constructor).unwrap().data()
        else {
            panic!("ObjectConstructor must preserve its default-library interface identity")
        };
        let [signature] = interface.declared_construct_signatures.as_deref().unwrap() else {
            panic!("ObjectConstructor must retain its real optional construct signature")
        };
        let signature = *signature;
        assert_eq!(
            interface.declared_call_signatures.as_ref().map(Vec::len),
            Some(2)
        );
        assert_eq!(
            fixture
                .store
                .signature(signature)
                .unwrap()
                .min_argument_count(),
            0
        );
        assert_eq!(
            fixture.store.callable_signature_parameter_types(signature),
            Some([fixture.store.intrinsic_bootstrap().unwrap().any_type].as_slice()),
        );

        let warm = function_store_state(&fixture.store);
        assert_eq!(
            query_signature_return(&mut fixture, signature, &mut diagnostics),
            Ok(object_type),
        );
        assert_eq!(function_store_state(&fixture.store), warm);

        let string = fixture.store.intrinsic_bootstrap().unwrap().string_type;
        assert!(
            fixture
                .store
                .set_signature_resolved_return_type(signature, Some(string))
        );
        let poisoned = function_store_state(&fixture.store);
        assert!(matches!(
            query_signature_return(&mut fixture, signature, &mut diagnostics),
            Err(DeclaredTypeError::TypeNodeUnavailable(
                TypeNodeUnavailable::InvalidFunctionSignature(actual)
            )) if actual == signature
        ));
        assert_eq!(function_store_state(&fixture.store), poisoned);

        assert!(
            fixture
                .store
                .set_signature_resolved_return_type(signature, Some(object_type))
        );
        assert_eq!(
            query_signature_return(&mut fixture, signature, &mut diagnostics),
            Ok(object_type),
        );
        assert!(diagnostics.is_empty());
    }

